test('persistent recovery admission failures release the provider queue for later sessions', async () => {
  const directory = tempDir('panel-metadata-fairness-');
  const files = ['failed', 'healthy'].map((name) => path.join(directory, name + '.jsonl'));
  const padding = (JSON.stringify({ type: 'ignored', body: 'x'.repeat(1024) }) + '\n').repeat(17_000);
  for (const file of files)
    fs.writeFileSync(
      file,
      JSON.stringify({ type: 'event_msg', payload: { type: 'task_started', turn_id: 'empty' } }) + '\n' + padding,
    );
  const sessions = files.map((file, i) => ({
    file,
    sessionId: String(i),
    agent: 'codex',
    size: fs.statSync(file).size,
    mtimeMs: fs.statSync(file).mtimeMs,
  }));
  const marker = path.join(directory, 'refuse');
  const source =
    progressiveWorkerSource +
    `\nconst nativeStat = require('node:fs').statSync; require('node:fs').statSync = (...args) => { if (args[0] === ${JSON.stringify(files[0])} && require('node:fs').existsSync(${JSON.stringify(marker)})) throw new Error('refused stat'); return nativeStat(...args); };`;
  const fixture = metadataEnrichmentFixture(sessions, source);
  try {
    await fixture.pass();
    assert.equal(fixture.provider.metadataRecoverySession, '0');
    fs.writeFileSync(marker, 'refuse');
    for (let pass = 0; pass < 7; pass++) await fixture.pass();
    assert.equal(
      fixture.provider.titles.get(files[1]).expandedStatsRead,
      true,
      'the failed active owner stranded the healthy waiting session',
    );
    assert.ok(railEnrichmentNeeds(fixture.provider.titles.get(files[0]), sessions[0])?.recovery);
    assert.ok(
      fixture.requests.filter((request) => request.kind === 'metadata-recovery' && request.session.file === files[0])
        .length > 2,
    );
  } finally {
    fixture.worker.stop();
    fs.rmSync(directory, { recursive: true, force: true });
  }
});

function metadataEnrichmentFixture(sessions: any[], source = progressiveWorkerSource) {
  const fixture = liveProviderFixture(livePress({ sessionId: 'metadata', agent: 'codex' }));
  const provider = fixture.provider as unknown as Record<string, any>;
  const worker = new ProgressiveWorker(source);
  const requests: any[] = [];
  const run = worker.run.bind(worker);
  worker.run = (request, generation, signal) => {
    requests.push(request);
    return run(request, generation, signal);
  };
  Object.assign(provider, {
    progressiveWorker: worker,
    titles: new Map(),
    metadataRevision: 0,
    drawnMetadataRevision: 0,
    codexMetas: new Map(),
    carriedNames: new Map(),
    refreshGeneration: 1,
    metadataRecoverySession: null,
    derivedCacheCheckpointState: { markChanged() {} },
    revisionOf: (session: any) => fs.statSync(session.file),
    observeStoredEntry() {},
    observeStoredName: (_session: any, entry: any) => entry,
    allSessions: () => sessions,
    catalog: { sessions },
    authoritativeCatalog: sessions,
    prepareClaudeChildren: async () => true,
    activityFor: (session: any) => session.mtimeMs,
    performanceCounters: { recordRefreshStage() {}, recordRefresh() {}, recordStartup() {} },
    ensureProjectSpendWorkspace() {},
    scheduleProjectSpendHydration() {},
    repositoryScopeRoots: [],
    trail: emptyTrail(),
    shownSessions: () => [],
    windows: new Map(),
    glanceAt: () => new Map(),
    outcomesFor: () => new Map(),
    newestBySession: new Map(),
    agentListingStamp: () => '',
    sessionParentEdges: () => ({ key: '' }),
    dropSpentPresses: () => false,
    liveOpenChildren: () => new Map(),
    liveBackgroundCommands: () => new Map(),
    drawnOpenChildren: openChildrenKey(new Map(), new Map()),
    collectedAt: Date.now(),
    refresh: async () => {},
  });
  Object.defineProperty(provider, 'lastSignature', {
    configurable: true,
    get: () =>
      listingSignature({
        showing: provider.showing,
        files: provider.authoritativeCatalog,
        threadNames: provider.threadNames?.stamp ?? null,
        children: '',
        sessionParents: '',
      }),
    set() {},
  });
  const pass = async () => {
    provider.refreshGeneration++;
    const signal = new AbortController().signal;
    assert.equal(await provider.prepareMetadata(sessions, provider.refreshGeneration, signal), true);
    return provider.prepareRailEnrichment(sessions, provider.refreshGeneration, signal);
  };
  return { provider, worker, requests, pass };
}

test.each([13 * 1024 * 1024, 84_686_045])(
  'accepted null Codex metadata stops repeated expanded requests for %i bytes',
  async (bytes) => {
    const directory = tempDir('panel-metadata-negative-');
    const file = path.join(directory, 'negative.jsonl');
    const healthy = path.join(directory, 'healthy.jsonl');
    const record = (payload: object) =>
      JSON.stringify({ timestamp: '2026-08-26T13:30:37Z', type: 'event_msg', payload }) + '\n';
    const starts = Array.from({ length: 19 }, (_, i) => record({ type: 'task_started', turn_id: String(i) })).join('');
    const padding = JSON.stringify({ type: 'ignored', body: 'x'.repeat(1024) }) + '\n';
    fs.writeFileSync(file, starts + padding.repeat(Math.ceil((bytes - starts.length) / padding.length)));
    const healthyOpening =
      record({ type: 'task_started', turn_id: 'healthy' }) +
      record({ type: 'user_message', message: 'Healthy later session' }) +
      JSON.stringify({
        type: 'turn_context',
        timestamp: '2026-08-26T13:30:37Z',
        payload: { turn_id: 'healthy', model: 'gpt-5-codex' },
      }) +
      '\n' +
      record({
        type: 'token_count',
        info: {
          last_token_usage: { input_tokens: 12000, output_tokens: 50, cached_input_tokens: 500 },
          total_token_usage: { input_tokens: 12000, output_tokens: 50, cached_input_tokens: 500 },
          model_context_window: 200000,
        },
      });
    fs.writeFileSync(
      healthy,
      healthyOpening +
        (bytes > 16 * 1024 * 1024 ? padding.repeat(Math.ceil((17 * 1024 * 1024) / padding.length)) : '') +
        record({ type: 'task_complete', turn_id: 'healthy', last_agent_message: 'Finished' }),
    );
    const sessions = [file, healthy].map((file, i) => ({
      file,
      sessionId: String(i),
      agent: 'codex',
      size: fs.statSync(file).size,
      mtimeMs: fs.statSync(file).mtimeMs,
    }));
    const fixture = metadataEnrichmentFixture(sessions);
    try {
      const answers = [];
      for (let i = 0; i < 12; i++) answers.push(await fixture.pass());
      assert.equal(
        fixture.requests.filter(
          (request) =>
            request.kind === 'metadata' && request.session.file === file && request.tailBytes === 16 * 1024 * 1024,
        ).length,
        1,
        'an unchanged null result repeated its accepted expanded window',
      );
      assert.equal(fixture.provider.titles.get(file).expandedStatsRead, true);
      assert.equal(fixture.provider.titles.get(file).stats, null);
      assert.equal(railEnrichmentNeeds(fixture.provider.titles.get(file), sessions[0]), null);
      assert.ok(fixture.provider.titles.get(healthy).stats, 'the later healthy session was not enriched');
      assert.equal(answers.at(-1).changed, false, 'unchanged accepted facts caused another refresh');
      assert.equal(answers.at(-1).progress, false);
      const completeHealthy = readCodexSession(healthy, '1', { tailBytes: fs.statSync(healthy).size });
      assert.deepEqual(fixture.provider.titles.get(healthy).stats, sessionStatFactsOf(completeHealthy));
      assert.deepEqual(fixture.provider.titles.get(healthy).outcome, sessionOutcomeOf(completeHealthy));
      const cache = path.join(directory, 'derived.json');
      saveDerivedCache(cache, fixture.provider.titles);
      fixture.provider.titles = loadDerivedCache(cache).titles;
      fixture.worker.stop();
      fixture.provider.progressiveWorker = new ProgressiveWorker(progressiveWorkerSource);
      assert.equal((await fixture.pass()).changed, false);
      fixture.provider.progressiveWorker.stop();
    } finally {
      fixture.worker.stop();
      fs.rmSync(directory, { recursive: true, force: true });
    }
  },
);

test('ordinary unchanged refresh retries failed metadata and enriches later sessions', async () => {
  const directory = tempDir('panel-metadata-retry-');
  const files = ['failed', 'healthy'].map((name) => path.join(directory, name + '.jsonl'));
  for (const file of files)
    fs.writeFileSync(
      file,
      JSON.stringify({
        timestamp: '2026-08-26T13:30:37Z',
        type: 'event_msg',
        payload: { type: 'task_started', turn_id: 'unfinished' },
      }) + '\n',
    );
  const sessions = files.map((file, i) => ({
    file,
    sessionId: String(i),
    agent: 'codex',
    size: fs.statSync(file).size,
    mtimeMs: fs.statSync(file).mtimeMs,
  }));
  const source =
    `const sourceFs = require('node:fs'); const nativeRead = sourceFs.readSync;
    let refused = false; sourceFs.readSync = (...args) => {
      if (!refused) { refused = true; throw new Error('transient read refusal'); }
      return nativeRead(...args);
    };\n` + progressiveWorkerSource;
  const fixture = metadataEnrichmentFixture(sessions, source);
  try {
    await fixture.provider.prepareMetadata(sessions, 1, new AbortController().signal);
    assert.equal(fixture.provider.titles.has(files[0]), false, 'a failed tail acquired accepted coverage');
    assert.equal(fixture.provider.titles.has(files[1]), true, 'one metadata failure stopped later work');
    await PanelProvider.prototype.refresh.call(fixture.provider, false, true);
    assert.ok(
      fixture.provider.titles.get(files[0])?.expandedStatsRead,
      'an unforced refresh stranded retryable metadata behind its unchanged-render decision',
    );
  } finally {
    fixture.worker.stop();
    fs.rmSync(directory, { recursive: true, force: true });
  }
});
