test('folderless ownership survives tab closure, pending checkpoint, reclamation and reopening', async () => {
  const listener = vi
    .spyOn(PanelProvider.prototype as unknown as { wireEditorListeners(): void }, 'wireEditorListeners')
    .mockImplementation(() => {});
  const cache = tempDir('panel-cache-tabs-');
  const partition = new WorkspaceCachePartition(cache, normalizedWorkspaceIdentity([]));
  const file = path.join(partition.root, 'derived-session-cache.json');
  const owner = new PanelProvider(
    '',
    {} as vscode.Uri,
    undefined,
    undefined,
    file,
    undefined,
    undefined,
    undefined,
    undefined,
    partition,
  );
  const provider = owner as unknown as Record<string, any>;
  Object.assign(provider, {
    notePanelStart() {},
    allowThemeFiles() {},
    shell: () => '',
    releaseQueuedEditOffer() {},
    closeBrowserStagingForHost() {},
  });
  const disposable = { dispose() {} };
  const attach = () => {
    let close = () => {};
    provider.attach({
      active: () => true,
      visible: () => true,
      webview: { html: '', onDidReceiveMessage: () => disposable },
      onDidChangeVisibility: () => disposable,
      onDidDispose: (listener: () => void) => {
        close = listener;
        return disposable;
      },
    });
    return () => close();
  };
  vi.useFakeTimers({ toFake: ['setTimeout', 'clearTimeout'] });
  try {
    provider.writeDerivedCache();
    const generation = fs.readFileSync(path.join(partition.root, FOLDERLESS_OWNER_FILE), 'utf8');
    const close = attach();
    provider.derivedCacheCheckpointState.markChanged();
    provider.checkpointDerivedCache();
    assert.ok(provider.derivedCacheCheckpointTick);
    close();
    await reclaimFolderlessCaches(cache, {
      platform: 'linux',
      signal: new AbortController().signal,
      inspect: async () => 'live',
    });
    assert.equal(fs.readFileSync(path.join(partition.root, FOLDERLESS_OWNER_FILE), 'utf8'), generation);
    assert.equal(fs.existsSync(path.join(partition.root, 'released.json')), false);
    const closeAgain = attach();
    await vi.runOnlyPendingTimersAsync();
    assert.ok(loadDerivedCache(file));
    assert.equal(fs.readFileSync(path.join(partition.root, FOLDERLESS_OWNER_FILE), 'utf8'), generation);
    closeAgain();
  } finally {
    owner.dispose();
    vi.useRealTimers();
    listener.mockRestore();
  }
});

test('terminal folderless shutdown closes admission before flushing pending writers and release', async () => {
  const listener = vi
    .spyOn(PanelProvider.prototype as unknown as { wireEditorListeners(): void }, 'wireEditorListeners')
    .mockImplementation(() => {});
  const cache = tempDir('panel-cache-shutdown-');
  const partition = new WorkspaceCachePartition(cache, normalizedWorkspaceIdentity([]));
  const file = path.join(partition.root, 'derived-session-cache.json');
  const owner = new PanelProvider(
    '',
    {} as vscode.Uri,
    undefined,
    path.join(partition.root, 'project-spend'),
    file,
    undefined,
    undefined,
    undefined,
    undefined,
    partition,
  );
  const provider = owner as unknown as Record<string, any>;
  vi.useFakeTimers({ toFake: ['setTimeout', 'clearTimeout'] });
  const original = provider.flushProjectSpendSave.bind(provider);
  provider.flushProjectSpendSave = () => {
    assert.equal(
      partition.write(() => assert.fail('new write during shutdown')),
      false,
    );
    assert.equal(fs.existsSync(path.join(partition.root, 'released.json')), false);
    original();
  };
  try {
    provider.projectSpendWorkspace = cache;
    provider.scheduleProjectSpendSave();
    provider.derivedCacheCheckpointState.markChanged();
    provider.checkpointDerivedCache();
    owner.dispose();
    assert.ok(loadDerivedCache(file));
    assert.ok(fs.existsSync(path.join(partition.root, 'project-spend')));
    assert.ok(fs.existsSync(path.join(partition.root, 'released.json')));
    const before = fs.readFileSync(file, 'utf8');
    provider.writeDerivedCache();
    provider.scheduleProjectSpendSave();
    provider.checkpointDerivedCache();
    await vi.runOnlyPendingTimersAsync();
    assert.equal(fs.readFileSync(file, 'utf8'), before);
    assert.equal(provider.projectSpendSaveScheduler.pending, false);
    assert.equal(provider.derivedCacheCheckpointTick, null);
    await reclaimFolderlessCaches(cache, { platform: 'linux', signal: new AbortController().signal });
    assert.ok(fs.existsSync(partition.root));
  } finally {
    owner.dispose();
    vi.useRealTimers();
    listener.mockRestore();
  }
});

test('commit repository replies expire on parent-only changes and reject stale or changed ownership', async () => {
  const directory = tempDir('host-commit-evidence-');
  const parentFile = path.join(directory, 'parent.jsonl');
  const childFile = path.join(directory, 'child.jsonl');
  fs.writeFileSync(parentFile, 'parent');
  fs.writeFileSync(childFile, 'child');
  const parent = { agent: 'codex', sessionId: 'parent', file: parentFile, size: 6, mtimeMs: 1 };
  const child = {
    threadId: 'child',
    parentThreadId: 'parent',
    file: childFile,
    agentPath: '/root/worker',
    backgroundReview: false,
    openedAt: 1,
    startedAt: 1,
    threadSource: 'subagent',
  };
  const session = { ...parent, sessionId: 'child', file: childFile };
  const commit = {
    sha: 'a'.repeat(7),
    printedSha: 'a'.repeat(40),
    subject: 'Recorded',
    at: 5,
    files: 1,
    added: 2,
    removed: 0,
    dir: null,
    place: null,
    repositoryEvidence: { dirs: ['C:/first/worktree'], at: 6, turnId: 'turn', complete: true },
  };
  const turns = [turn({ commits: [commit] })];
  const provider: any = Object.create(PanelProvider.prototype);
  provider.codexSubagents = [child];
  provider.allSessions = () => [parent];
  provider.commitRepositoryReplies = new Map();
  provider.commitRepositoryReservations = new CommitRepositoryReservations();
  let alter = () => {};
  provider.progressiveWorker = {
    async run(request: any, generation: number) {
      alter();
      return {
        generation,
        revision: request.parent.revision,
        value: {
          kind: 'commit-repositories',
          status: 'complete',
          token: 'complete',
          parent: request.parent,
          child: request.child,
          parserVersion: request.parserVersion,
          readBytes: { parent: 0, child: 0 },
          covered: { parent: [0, request.parent.revision.size], child: [0, request.child.revision.size] },
          targets: [
            {
              sha: commit.printedSha,
              dirs: ['C:/first'],
              occurrence: JSON.stringify([
                commit.repositoryEvidence.turnId,
                commit.at,
                commit.repositoryEvidence.at,
                commit.printedSha,
                commit.repositoryEvidence.dirs,
              ]),
            },
          ],
        },
      };
    },
  };
  await provider.hydrateCommitRepositories(session, turns, 1, new AbortController().signal);
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.deepEqual(turns[0].commits[0].candidates, { dirs: ['C:/first'], complete: true });
  fs.appendFileSync(parentFile, ' changed');
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.equal(turns[0].commits[0].candidates?.complete, false);
  assert.equal(turns[0].commits[0].dir, null);
  alter = () => fs.appendFileSync(parentFile, ' stale');
  await provider.hydrateCommitRepositories(session, turns, 2, new AbortController().signal);
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.equal(turns[0].commits[0].candidates?.complete, false);
  alter = () => {};
  await provider.hydrateCommitRepositories(session, turns, 3, new AbortController().signal);
  fs.renameSync(parentFile, parentFile + '.old');
  fs.writeFileSync(parentFile, 'replacement');
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.equal(turns[0].commits[0].candidates?.complete, false);
  provider.codexSubagents = [{ ...child, parentThreadId: 'other' }];
  provider.applyCommitRepositoryEvidence(session, turns);
  assert.equal(turns[0].commits[0].candidates?.complete, false);
});

