test.each(['identity', 'storage'])(
  'browser readiness recovers a temporary %s setup failure without changing folders',
  async (failure) => {
    const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
    const setupSource = extensionSource.slice(
      extensionSource.indexOf('const setupProjects = new SetupProjects('),
      extensionSource.indexOf('// What each agent published for its slash menu'),
    );
    const compiled = esbuild.transformSync(setupSource, { loader: 'ts', format: 'cjs', target: 'esnext' }).code;
    const folderA = tempDir('setup-recovery-A-');
    const folderB = tempDir('setup-recovery-B-');
    let folder = folderA;
    const projectA = `git:${normalizeProjectPath(fs.realpathSync(folderA))}`;
    const projectB = `git:${normalizeProjectPath(fs.realpathSync(folderB))}`;
    const values = { agent: 'claude' as const, model: 'saved', effort: '', permissionMode: '' };
    const pin = { id: 'legacy-id', ...values };
    const recent = { ...values, source: 'recent' as const };
    const saved = new Map<string, unknown>([[STORED_STATE_KEYS.pinnedSetups, [pin]]]);
    if (failure === 'identity') saved.set(projectSetupKey(projectA), { version: 1, pins: [pin], recents: [recent] });
    let refuseStorage = failure === 'storage';
    const errors: string[] = [];
    let identityCalls = 0;
    let releaseIdentity!: () => void;
    let heldIdentity: Promise<void> | null = null;
    let workspaceChanged!: () => void;
    const provider = Object.create(PanelProvider.prototype) as Record<string, any>;
    Object.assign(provider, {
      hosts: [],
      readyHosts: new Set(),
      panelVisibility: createPanelVisibility(),
      sendToHost: async () => true,
      performanceCounters: { recordStartup: () => undefined },
      startPolling: () => undefined,
      requestInitialCatalogRefresh: () => undefined,
      refresh: vi.fn<() => void>(),
      post: async () => undefined,
      usagePayload: () => ({}),
    });
    const [bootstrap] = sourceNodes(
      bootstrapSource,
      (node) => ts.isFunctionDeclaration(node) && node.name?.text === 'startBrowserPanel',
    );
    assert.ok(bootstrap);
    const browserModule = { exports: {} as { startBrowserPanel: () => unknown } };
    const browserMessages: unknown[] = [];
    new Function(
      'module',
      'exports',
      'createHost',
      'acquireVsCodeApi',
      'createSavedState',
      'startPanel',
      'panelDom',
      'document',
      'window',
      'requestAnimationFrame',
      esbuild.transformSync(bootstrap, { loader: 'ts', format: 'cjs', target: 'esnext' }).code,
    )(
      browserModule,
      browserModule.exports,
      () => ({ host: { send: (message: unknown) => browserMessages.push(message) }, browserState: {} }),
      () => ({}),
      () => ({ publishRecovery: () => undefined }),
      () => ({ receiveHostMessage: () => undefined, dispose: () => undefined }),
      () => ({}),
      { addEventListener: () => undefined },
      { addEventListener: () => undefined },
      (callback: () => void) => callback(),
    );
    const readyPanel = async (host: { visible: () => boolean }) => {
      browserModule.exports.startBrowserPanel();
      for (const message of browserMessages.splice(0)) await provider.onMessage(message, host);
    };
    const refreshPending = new Function(
      'SetupProjects',
      'nodeGitRunner',
      'ProjectSetupStore',
      'context',
      'panel',
      'workspaceCwd',
      'vscode',
      `${compiled}\nreturn () => setupRefresh?.pending ?? Promise.resolve();`,
    )(
      SetupProjects,
      () => ({
        run: async () => null,
        identity: async (destination: string) => {
          const call = ++identityCalls;
          if (heldIdentity) await heldIdentity;
          return {
            stdout: failure === 'identity' && call === 1 ? null : `${destination}\n${destination}\n${destination}\n`,
            outsideGit: false,
          };
        },
      }),
      ProjectSetupStore,
      {
        globalState: {
          get: (key: string) => saved.get(key),
          update: async (key: string, value: unknown) => {
            if (refuseStorage) throw new Error('temporary storage failure');
            saved.set(key, structuredClone(value));
          },
        },
        subscriptions: [],
      },
      provider,
      () => folder,
      {
        window: { showErrorMessage: (message: string) => errors.push(message) },
        workspace: {
          onDidChangeWorkspaceFolders: (callback: () => void) => {
            workspaceChanged = callback;
          },
        },
      },
    );
    await refreshPending();
    if (failure === 'storage') assert.equal(errors.length, 1);
    else assert.equal(provider.setupOwner, 'project:1');
    assert.equal(provider.setupProject, null);
    assert.deepEqual(provider.pinnedSetups, []);
    refuseStorage = false;
    heldIdentity = new Promise<void>((resolve) => {
      releaseIdentity = resolve;
    });
    await readyPanel({ visible: () => true });
    assert.equal(identityCalls, 1, 'an unregistered browser retried setup loading');
    const firstHost = { visible: () => true };
    const secondHost = { visible: () => true };
    provider.hosts.push(firstHost, secondHost);
    await readyPanel(firstHost);
    await readyPanel(firstHost);
    await readyPanel(secondHost);
    heldIdentity = null;
    releaseIdentity();
    await vi.waitFor(() => assert.equal(provider.setupProject, projectA));
    assert.deepEqual(provider.pinnedSetups, [pin]);
    assert.deepEqual(provider.recentProfiles, failure === 'identity' ? [recent] : []);
    assert.equal(identityCalls, 2, 'concurrent browser readiness repeated the recovery read');
    assert.equal(provider.refresh.mock.calls.length, 2);

    heldIdentity = new Promise<void>((resolve) => {
      releaseIdentity = resolve;
    });
    const reopenedHost = { visible: () => true };
    provider.hosts.push(reopenedHost);
    await readyPanel(reopenedHost);
    assert.equal(identityCalls, 3);
    const obsolete = refreshPending();
    const releaseA = releaseIdentity;
    heldIdentity = null;
    folder = folderB;
    workspaceChanged();
    await vi.waitFor(() => assert.equal(provider.setupProject, projectB));
    releaseA();
    await obsolete;
    assert.equal(provider.setupProject, projectB, 'an obsolete recovery published into the current project');
    assert.equal(provider.setupOwner, 'project:4');
  },
);

test('pin changes read stored setups in order and adopt the result after each write', async () => {
  const compiled = esbuild.transformSync(
    `export function changePinnedSetups(change: unknown) {${methodBody('private changePinnedSetups(')}}`,
    { loader: 'ts', format: 'cjs', target: 'esnext' },
  ).code;
  const module = {
    exports: {} as { changePinnedSetups: (this: Record<string, any>, change: unknown) => Promise<boolean> },
  };
  const errors: string[] = [];
  let nextId = 0;
  new Function(
    'module',
    'exports',
    'normalizePinnedSetups',
    'normalizeSetupValues',
    'sameValues',
    'pinValues',
    'unpinId',
    'sessionLauncherView',
    'launcherProfile',
    'crypto',
    'vscode',
    compiled,
  )(
    module,
    module.exports,
    normalizePinnedSetups,
    normalizeSetupValues,
    sameValues,
    pinValues,
    unpinId,
    () => ({}),
    (_view: unknown, request: { key: string }) => {
      if (request.key.startsWith('recent:')) return host.recentProfiles[Number(request.key.slice(7))] ?? null;
      return request.key === 'one' || request.key === 'two'
        ? { agent: 'claude', model: request.key, effort: '', permissionMode: '', source: 'recent' }
        : null;
    },
    { randomUUID: () => `id-${++nextId}` },
    { window: { showErrorMessage: (message: string) => errors.push(message) } },
  );
  const change = module.exports.changePinnedSetups;
  let stored: PinnedSetup[] = [];
  const writes: PinnedSetup[][] = [];
  const posts: unknown[] = [];
  let releaseFirst: (() => void) | undefined;
  const firstWrite = new Promise<void>((resolve) => {
    releaseFirst = resolve;
  });
  const host: Record<string, any> = {
    hosts: [],
    showing: null,
    recentProfiles: [],
    pinnedSetups: [],
    pinnedSetupWrites: Promise.resolve(),
    models: {},
    composerState: () => null,
    launcherFor: () => ({ view: {}, owner: null, state: null }),
    readPinnedSetups: () => stored,
    persistPinnedSetups: async (list: PinnedSetup[]) => {
      if (writes.length === 0) await firstWrite;
      writes.push(list);
      stored = list;
    },
    usagePayload: () => ({ pinned: host.pinnedSetups }),
    post: (message: unknown) => {
      posts.push(message);
      return Promise.resolve();
    },
  };
  const pinRequest = (key: string) => ({
    kind: 'row',
    key,
    values: { agent: 'claude', model: key, effort: '', permissionMode: '' },
  });
  const first = change.call(host, { kind: 'pin', request: pinRequest('one') });
  const second = change.call(host, { kind: 'pin', request: pinRequest('two') });
  await vi.waitFor(() => assert.equal(nextId, 1));
  assert.deepEqual(writes, []);
  releaseFirst!();
  assert.deepEqual(await Promise.all([first, second]), [true, true]);
  assert.deepEqual(
    stored.map((one) => one.model),
    ['one', 'two'],
  );
  assert.deepEqual(host.pinnedSetups, stored);

  stored = [...stored, { id: 'external', agent: 'claude', model: 'retired', effort: '', permissionMode: '' }];
  assert.equal(await change.call(host, { kind: 'unpin', id: 'absent' }), true);
  assert.deepEqual(host.pinnedSetups, stored);
  assert.deepEqual(posts.at(-1), { type: 'usage', usage: { pinned: stored } });
  assert.equal(await change.call(host, { kind: 'pin', request: pinRequest('one') }), true);
  assert.equal(stored.length, 3);
  assert.equal(await change.call(host, { kind: 'pin', request: pinRequest('unoffered') }), false);
  assert.equal(stored.length, 3);

  host.persistPinnedSetups = async () => {
    throw new Error('storage refused');
  };
  assert.equal(await change.call(host, { kind: 'unpin', id: 'id-1' }), false);
  assert.deepEqual(host.pinnedSetups, stored);
  assert.deepEqual(errors, ['Arc: pinned setups did not change. storage refused']);

  host.readPinnedSetups = () => [
    { id: 'from-another-window', agent: 'claude', model: 'external', effort: '', permissionMode: '' },
  ];
  const postsBeforeFailure = posts.length;
  assert.equal(await change.call(host, { kind: 'unpin', id: 'id-2' }), false);
  assert.deepEqual(host.pinnedSetups, host.readPinnedSetups());
  assert.equal(posts.length, postsBeforeFailure + 1);
  assert.deepEqual(
    stored.map((one) => one.model),
    ['one', 'two', 'retired'],
  );

  host.persistPinnedSetups = null;
  assert.equal(await change.call(host, { kind: 'unpin', id: 'id-2' }), false);
  assert.equal(errors.at(-1), 'Arc: pinned setups did not change. Saving is unavailable.');
});

