test('completion slices post changed figures once on retained and newest launching turns', async () => {
  const directory = tempDir('dispatch-host-completion-');
  const parentFile = path.join(directory, 'parent.jsonl');
  const id = 'aaaaaaaa-1111-1111-1111-111111111111';
  const childFile = path.join(directory, id + '.jsonl');
  const clock = path.join(directory, 'clock');
  const record = (type: string, second: number, payload: object) =>
    JSON.stringify({ type, timestamp: new Date(NOW + second * 1000).toISOString(), payload }) + '\n';
  const launch = (name: string, second: number) =>
    record('event_msg', second, { type: 'task_started', turn_id: name }) +
    record('turn_context', second + 1, { turn_id: name }) +
    record('event_msg', second + 1, { type: 'user_message', message: 'review' }) +
    record('event_msg', second + 2, {
      type: 'item_completed',
      item: {
        type: 'CommandExecution',
        id: name,
        status: 'completed',
        exit_code: 0,
        parsed_cmd: [{ type: 'unknown', cmd: 'python child.py --arc-dispatch' }],
        stdout: `ARC_DISPATCH_SESSION={"agent":"codex","session_id":"${id}"}`,
      },
    }) +
    record('event_msg', second + 3, { type: 'task_complete', turn_id: name });
  fs.writeFileSync(
    parentFile,
    record('session_meta', 0, { id: 'parent', cwd: directory, source: 'cli' }) +
      launch('first', 1) +
      launch('last', 10),
  );
  fs.writeFileSync(
    childFile,
    record('session_meta', 0, { id, cwd: directory, source: 'exec', model_provider: 'openai' }) +
      record('event_msg', 1, { type: 'task_started', turn_id: 'work' }) +
      record('turn_context', 2, { turn_id: 'work', model: 'gpt-6.1-sol', effort: 'high' }) +
      record('event_msg', 3, { type: 'agent_message', message: 'x'.repeat(700 * 1024) }) +
      record('event_msg', 3, { type: 'agent_message', message: 'x'.repeat(700 * 1024) }) +
      record('event_msg', 4, {
        type: 'token_count',
        info: {
          last_token_usage: { input_tokens: 10, output_tokens: 3 },
          total_token_usage: { input_tokens: 10, output_tokens: 3 },
        },
      }) +
      record('event_msg', 5, { type: 'task_complete', turn_id: 'work' }),
  );
  const now = fs.statSync(childFile).mtimeMs + 300_000;
  fs.writeFileSync(clock, String(now));
  const worker = new ProgressiveWorker(
    progressiveWorkerSource +
      `\nDate.now = () => Number(require('node:fs').readFileSync(${JSON.stringify(clock)}, 'utf8'));`,
  );
  const sessions = [
    [parentFile, 'parent'],
    [childFile, id],
  ].map(([file, sessionId]) => ({
    file,
    sessionId,
    agent: 'codex',
    size: fs.statSync(file).size,
    mtimeMs: fs.statSync(file).mtimeMs,
  }));
  const turns = readCodexSession(parentFile, 'parent').turns;
  const fixture = dispatchedRefreshFixture(sessions, worker, turns);
  const provider = fixture.provider;
  provider.repositoryScopeRoots = [directory];
  vi.useFakeTimers({ now, toFake: ['Date', 'setTimeout', 'clearTimeout'] });
  try {
    await provider.prepareClaudeChildren(1, new AbortController().signal);
    assert.equal(provider.dispatchFacts.size, 1);
    assert.equal(provider.dispatchDiscoveryPending, true);
    provider.drawnDispatchFiguresRevision = provider.dispatchFiguresRevision;
    provider.threadNames = readThreadNames(codexSessionIndexPath(), null);
    provider.lastSignature = listingSignature({
      showing: 'parent',
      files: provider.catalog.sessions,
      threadNames: provider.threadNames.stamp,
      children: '',
      sessionParents: '',
    });
    await provider.refresh(false, true);
    assert.equal(fixture.collections(), 0);
    assert.equal(fixture.posted.filter((message) => message.type === 'render').length, 0);
    for (let i = 0; i < 8 && provider.dispatchDiscoveryPending; i++) {
      const before = fixture.refreshes.length;
      await vi.advanceTimersByTimeAsync(0);
      assert.ok(fixture.refreshes.length > before);
      await fixture.refreshes.at(-1);
    }
    assert.equal(fixture.collections(), 1);
    const renders = fixture.posted.filter((message) => message.type === 'render');
    assert.equal(renders.length, 1);
    const cards = renders[0].cards as CardView[];
    assert.equal(cards.length, 2);
    for (const card of cards) {
      assert.ok(card.dispatched);
      assert.equal(card.dispatched[0].model, 'gpt-6.1-sol');
      assert.equal(card.dispatched[0].effort, 'high');
      assert.ok(card.dispatched[0].figures.some((figure) => figure.metric === 'cost'));
    }
    await provider.refresh(false, true);
    assert.equal(fixture.collections(), 1);
    assert.equal(fixture.posted.filter((message) => message.type === 'render').length, 1);
    // An unchanged unknown source becomes eligible at its accepted deadline.
    fs.appendFileSync(childFile, record('event_msg', 6, { type: 'task_started', turn_id: 'resumed' }));
    Object.assign(sessions[1], { size: fs.statSync(childFile).size, mtimeMs: fs.statSync(childFile).mtimeMs });
    await provider.refresh(false, true);
    assert.equal(provider.dispatchFacts.get(id).spend.found, false);
    const deadline = provider.dispatchFacts.get(id).refreshAt;
    fs.writeFileSync(clock, String(deadline + 1));
    vi.setSystemTime(deadline + 1);
    await provider.refresh(false, true);
    assert.equal(provider.dispatchFacts.get(id).spend.found, true);
    assert.equal(fixture.collections(), 3);
    await provider.refresh(false, true);
    assert.equal(fixture.collections(), 3);
  } finally {
    vi.useRealTimers();
    worker.stop();
    fs.rmSync(directory, { recursive: true, force: true });
  }
});

test('dispatch figure posts retain pending revisions until the captured payload is accepted', async () => {
  const sessions = [
    { file: 'parent.jsonl', sessionId: 'parent', agent: 'codex', size: 1, mtimeMs: 1 },
    { file: 'child.jsonl', sessionId: 'child', agent: 'codex', size: 1, mtimeMs: 1 },
  ];
  let toolUses = 1;
  let artifactRevision = 'first';
  const artifactCommits: string[] = [];
  let stale = false;
  const worker = {
    run: async (_request: unknown, generation: number) => ({
      generation: stale ? generation - 1 : generation,
      value: {
        kind: 'claude-children',
        complete: true,
        references: [],
        children: [],
        referenceEntries: [],
        continuation: false,
        dispatchFacts: [
          {
            sessionId: 'child',
            revision: { size: 1, mtimeMs: 1 },
            refreshAt: null,
            spend: {
              models: [],
              found: false,
              partial: false,
              effort: null,
              artifacts: { files: [], commits: [...artifactCommits], complete: true, revision: artifactRevision },
            },
            person: false,
            startedAt: null,
            endedAt: null,
            toolUses,
          },
        ],
      },
    }),
  } as unknown as ProgressiveWorker;
  const fixture = dispatchedRefreshFixture(sessions, worker, []);
  const provider = fixture.provider;
  provider.lastSignature = listingSignature({
    showing: 'parent',
    files: sessions,
    threadNames: '',
    children: '',
    sessionParents: '',
  });
  await provider.prepareClaudeChildren(1, new AbortController().signal);
  assert.equal(provider.dispatchFiguresRevision, 1);
  provider.sendToHost = () => Promise.resolve(false);
  await provider.refresh(false, true);
  assert.equal(provider.drawnDispatchFiguresRevision, 0);
  provider.sendToHost = () => Promise.reject(new Error('closed'));
  await provider.refresh(false, true);
  assert.equal(provider.drawnDispatchFiguresRevision, 0);
  let accept!: (value: boolean) => void;
  let postedController!: AbortController;
  provider.sendToHost = () =>
    new Promise<boolean>((resolve) => {
      accept = resolve;
      postedController = provider.refreshController;
    });
  await provider.refresh(false, true);
  toolUses = 2;
  await provider.prepareClaudeChildren(provider.refreshGeneration, new AbortController().signal);
  assert.equal(provider.dispatchFiguresRevision, 2);
  accept(true);
  await Promise.resolve();
  assert.equal(provider.drawnDispatchFiguresRevision, 1);
  provider.sendToHost = () => Promise.resolve(true);
  await provider.refresh(false, true);
  assert.equal(provider.drawnDispatchFiguresRevision, 2);
  const collected = fixture.collections();
  artifactRevision = 'source-only';
  await provider.prepareClaudeChildren(provider.refreshGeneration, new AbortController().signal);
  assert.equal(provider.dispatchFiguresRevision, 2, 'artifact source provenance does not change rendered figures');
  await provider.refresh(false, true);
  assert.equal(fixture.collections(), collected);
  toolUses = 3;
  stale = true;
  assert.equal(await provider.prepareClaudeChildren(provider.refreshGeneration, new AbortController().signal), false);
  assert.equal(provider.dispatchFiguresRevision, 2);
  stale = false;
  const canceled = new AbortController();
  canceled.abort();
  assert.equal(await provider.prepareClaudeChildren(provider.refreshGeneration, canceled.signal), false);
  assert.equal(provider.dispatchFiguresRevision, 2);
  await provider.prepareClaudeChildren(provider.refreshGeneration, new AbortController().signal);
  provider.sendToHost = () =>
    new Promise<boolean>((resolve) => {
      accept = resolve;
      postedController = provider.refreshController;
    });
  await provider.refresh(false, true);
  provider.refreshGeneration++;
  accept(true);
  await Promise.resolve();
  assert.equal(provider.drawnDispatchFiguresRevision, 2);
  await provider.refresh(false, true);
  postedController.abort();
  // Cancellation after posting still rejects its acknowledgment.
  accept(true);
  await Promise.resolve();
  assert.equal(provider.drawnDispatchFiguresRevision, 2);
  provider.sendToHost = () => Promise.resolve(true);
  await provider.refresh(false, true);
  assert.equal(provider.drawnDispatchFiguresRevision, 3);
  const restarted = dispatchedRefreshFixture(sessions, worker, []).provider;
  await restarted.prepareClaudeChildren(1, new AbortController().signal);
  assert.equal(restarted.dispatchFiguresRevision, 1);
  assert.equal(restarted.drawnDispatchFiguresRevision, 0);
  artifactCommits.push('recorded-commit');
  await restarted.prepareClaudeChildren(1, new AbortController().signal);
  assert.equal(restarted.dispatchFiguresRevision, 2, 'changed artifact content changes rendered figures');
});

test('the host payload keeps dispatched artifacts on the child card', () => {
  const start = panelHostSource.indexOf('private renderTurnCard(');
  const end = start + memberFrom(panelHostSource, start).length;
  assert.ok(start >= 0 && end > start);
  const source = panelHostSource.slice(start, end).replace('private renderTurnCard(', 'function renderTurnCard(');
  const compiled = ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022 } }).outputText;
  const renderTurnCard = new Function(
    'toCard',
    'dispatchedAgentCard',
    'dispatchedChip',
    'dispatchedState',
    'pressOfKind',
    'renderRichMarkdown',
    'withRecoveredCommits',
    'sameCommitSha',
    'countedDispatchedCosts',
    `${compiled}\nreturn renderTurnCard;`,
  )(
    toCard,
    dispatchedAgentCard,
    dispatchedChip,
    dispatchedState,
    () => null,
    renderRichMarkdown,
    withRecoveredCommits,
    sameCommitSha,
    countedDispatchedCosts,
  ) as Function;
  const parent = turn({ sessionId: 'parent', files: [], commits: [], agents: [], dispatchToolUseIds: ['launch'] });
  const childId = '4f4bf298-958f-4751-8782-d8688ff808a6';
  const childFile = 'C:/repo/child-only.ts';
  const childSha = '9f8e7d6c5b4a3210';
  const spend = {
    found: true,
    partial: false,
    effort: null,
    models: [],
    artifacts: {
      complete: true,
      revision: 'one',
      files: [{ path: childFile, added: 3, removed: 1, isNew: false }],
      commits: [childSha],
    },
    commits: [
      { sha: childSha, subject: 'Child work', at: NOW, files: 1, added: 3, removed: 1, place: null, dir: 'C:/repo' },
    ],
  };
  const provider = {
    live: {},
    turnsByKey: new Map(),
    projectSpendHydrated: true,
    dispatchedTurnCosts: () => ({}),
    repositoryCommits: { apply() {} },
    claudeChildReferences: [
      {
        kind: 'dispatch',
        agent: 'claude',
        parentSessionId: 'parent',
        sessionId: childId,
        toolUseIds: ['launch'],
        name: 'Child work',
        owned: false,
      },
    ],
    dispatchFacts: new Map([[childId, { spend, startedAt: NOW - 1000, endedAt: NOW, toolUses: 2 }]]),
  };
  const statuses = new Map([[childId, 'done']]);
  const card = renderTurnCard.call(provider, parent, false, 'Parent', NOW, ['C:/repo'], new Set(), new Map(), statuses);
  assert.deepEqual([card.files, card.commits], [[], []]);
  assert.deepEqual(
    card.dispatched[0].files.map((file: { path: string }) => file.path),
    [childFile],
  );
  assert.deepEqual(
    card.dispatched[0].commits.map((commit: { sha: string; dir: string }) => [commit.sha, commit.dir]),
    [[childSha, 'C:/repo']],
  );
  // The host appends the dispatched figure after the figures `toCard` built, so on a parent
  // with its own commits and a subagent it lands directly after the subagents figure.
  const busy = turn({ ...subagentCommitTurn(), sessionId: 'parent', dispatchToolUseIds: ['launch'] });
  const busyCard = renderTurnCard.call(
    provider,
    busy,
    false,
    'Parent',
    NOW,
    ['C:/repo'],
    new Set(),
    new Map(),
    statuses,
  );
  assert.deepEqual(
    busyCard.chips.map((chip: { metric: string; label: string }) => [chip.metric, chip.label]),
    [
      ['files', 'no file changes'],
      ['commits', '2 commits'],
      ['agents', '1 subagent'],
      ['dispatched', '1 dispatched'],
    ],
  );
  const rows = detailRowsFor(card, 'dispatched');
  assert.equal(rows?.kind, 'dispatched');
  if (rows?.kind === 'dispatched') {
    assert.deepEqual(
      rows.agents[0].files?.map((file) => file.path),
      [childFile],
    );
  }
  const overlapping = turn({ ...parent, files: [{ path: childFile, added: 7, removed: 0, isNew: false, edits: [] }] });
  const sharedPath = renderTurnCard.call(
    provider,
    overlapping,
    false,
    'Parent',
    NOW,
    ['C:/repo'],
    new Set(),
    new Map(),
    statuses,
  );
  assert.equal(sharedPath.files[0].added, 7);
  assert.equal(sharedPath.dispatched[0].files[0].added, 3);
  let resolved = 0;
  const owner = {
    ...provider,
    dispatchFacts: new Map([
      [
        childId,
        {
          spend: {
            ...spend,
            commits: [],
            artifacts: { ...spend.artifacts, commits: [] },
            commitIntents: [{ dir: 'C:/repo', from: NOW - 1000, to: NOW, expected: 1 }],
          },
          startedAt: NOW - 1000,
          endedAt: NOW,
          toolUses: 2,
        },
      ],
    ]),
    repositoryCommits: {
      apply(turns: Array<{ commits: unknown[] }>) {
        resolved++;
        turns[0].commits.push(spend.commits[0]);
      },
    },
  };
  const recovered = renderTurnCard.call(
    owner,
    parent,
    false,
    'Parent',
    NOW,
    ['C:/repo'],
    new Set(),
    new Map(),
    statuses,
  );
  assert.equal(resolved, 1);
  assert.deepEqual(
    recovered.dispatched[0].commits.map((commit: { sha: string; dir: string }) => [commit.sha, commit.dir]),
    [[childSha, 'C:/repo']],
  );
  const printed = {
    ...provider,
    dispatchFacts: new Map([
      [
        childId,
        {
          spend: { ...spend, commits: [{ ...spend.commits[0], dir: 'C:/repo/.claude/worktrees/deleted' }] },
          startedAt: NOW - 1000,
          endedAt: NOW,
          toolUses: 2,
        },
      ],
    ]),
    repositoryCommits: {
      apply(turns: Array<{ commits: Array<{ dir: string }> }>) {
        turns[0].commits[0].dir = 'C:/repo';
      },
    },
  };
  const corrected = renderTurnCard.call(
    printed,
    parent,
    false,
    'Parent',
    NOW,
    ['C:/repo'],
    new Set(),
    new Map(),
    statuses,
  );
  assert.equal(corrected.dispatched[0].commits[0].dir, 'C:/repo');
});
