test('a session cache budget change evicts by budget alone, never by a stale catalog', () => {
  sourceMatch(
    panelHostSource,
    /affectsConfiguration\(settingName\('sessionCacheMiB'\)\) && catalog\) \{\s*this\.evictCache\(catalog, catalog\);\s*this\.evictOlderHistoryByBudget\(\);/,
    'a sessionCacheMiB change does not run both eviction passes',
  );
  const from = panelHostSource.indexOf('private evictOlderHistoryByBudget(): void {');
  assert.notEqual(
    from,
    -1,
    'panelhost.ts no longer contains evictOlderHistoryByBudget, so this guard cannot see the budget-only pass',
  );
  const body = memberFrom(panelHostSource, from);
  sourceMatch(
    body,
    /historyEvictions\([\s\S]*entries, this\.protectedHistorySessions\(\), this\.sessionCacheBudgetBytes\(\)[\s\S]*\)/,
    'the budget-only pass no longer evicts by historyEvictions, so a setting change could evict nothing',
  );
  sourceDoesNotMatch(
    body,
    /historyAfterRevision|\.size\b|mtimeMs/,
    'the budget-only pass compares a page against a catalog revision, so a selected session that grew since the last refresh could have its older pages reset by a setting change instead of only evicted for budget',
  );
});

test('live process operations hold an AgentHost activity lease', () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  for (const operation of ['setModel', 'setEffort']) {
    sourceMatch(
      extensionSource,
      new RegExp(`withActivity\\([^\\n]+\\((\\w+)\\) => \\1\\.${operation}\\(`),
      `${operation} can outlive the process retirement guard`,
    );
  }
  const permissionAt = extensionSource.indexOf('const setAskModeFor = async');
  const permission = extensionSource.slice(permissionAt, extensionSource.indexOf('const setModelFor', permissionAt));
  sourceMatch(
    permission,
    /withActivities\([\s\S]*applyMode\(sessions\)/,
    'a later permission target can retire while an earlier target waits for its response',
  );
  sourceMatch(
    permission,
    /withRetiringActivities\(liveTargets\.map\([\s\S]*persistSettingBook\([\s\S]*workspaceState\.update\(/,
    'an agent-default choice can persist before retirement excludes another prompt',
  );
  sourceMatch(
    permission,
    /const applyMode =[\s\S]*session\.setAskMode\(mode\)/,
    'an explicit permission choice no longer reaches each leased child',
  );
  const usageAt = extensionSource.indexOf('const readFrom = async');
  const usage = extensionSource.slice(usageAt, extensionSource.indexOf('// What one agent', usageAt));
  sourceMatch(
    usage,
    /withActivity\(key,[\s\S]*session\.rateLimits\([\s\S]*session\.models\(/,
    'a usage or model read can outlive the process retirement guard',
  );
  const mcpAt = extensionSource.indexOf('const readMcpFrom = async');
  const mcp = extensionSource.slice(mcpAt, extensionSource.indexOf('// The same reading', mcpAt));
  sourceMatch(
    mcp,
    /withActivity\(key,[\s\S]*session\.mcpStatus\(/,
    'an MCP status read can outlive the process retirement guard',
  );
  const sendAt = extensionSource.indexOf('panel.onSendPrompt = async');
  const send = extensionSource.slice(sendAt, extensionSource.indexOf('// Compaction is', sendAt));
  sourceMatch(
    send,
    /withExistingSessionActivity\([\s\S]*session\.prompt\(prompt,/,
    'opening a prompt does not reserve the child through its activity lease',
  );
  const compactAt = extensionSource.indexOf('panel.onCompact = async');
  const compact = extensionSource.slice(compactAt, extensionSource.indexOf('panel.onSendDraftPrompt', compactAt));
  sourceMatch(
    compact,
    /withExistingSessionActivity\([\s\S]*session\.compact\(\)/,
    'opening compaction does not reserve the child through its activity lease',
  );
});

test('removing a permission override stores every session before the agent default', async () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const setAt = extensionSource.indexOf('const setAskModeFor = async');
  const modelAt = extensionSource.indexOf('const setModelFor =', setAt);
  assert.ok(setAt >= 0 && modelAt > setAt, 'the permission transition is not available to exercise');
  const loaded = { exports: {} as { setAskModeFor: (...args: any[]) => Promise<void> } };
  const code = esbuild.transformSync(`export ${extensionSource.slice(setAt, modelAt)}`, {
    loader: 'ts',
    format: 'cjs',
    target: 'esnext',
  }).code;
  const events: string[] = [];
  const barriers = new Set<string>();
  let book = withSessionSettings(
    withSessionSettings({}, 'one', { ...sessionSettings({}, 'one'), permissionMode: 'fullAccess' }),
    'two',
    { ...sessionSettings({}, 'two'), permissionMode: 'fullAccess' },
  );
  const host = {
    states: () => [
      { agent: 'codex', exited: false, key: 'codex:one', sessionId: 'one' },
      { agent: 'codex', exited: false, key: 'codex:two', sessionId: 'two' },
    ],
    withRetiringActivities: async (
      keys: string[],
      work: (sessions: ReadonlyMap<string, unknown>) => Promise<boolean>,
    ) => {
      for (const key of keys) {
        barriers.add(key);
      }
      events.push('barrier');
      events.push(keys.every((key) => barriers.has(key)) ? 'all barred' : 'partly barred');
      const result = await work(new Map(keys.map((key) => [key, {}])));
      events.push('retired');
      return result;
    },
    withActivities: async () => {
      throw new Error('an empty permission used the in-process branch');
    },
  };
  new Function(
    'module',
    'exports',
    'context',
    'ASK_MODE_KEY',
    'stored',
    'host',
    'acceptedPermissionMode',
    'settingBook',
    'persistSettingBook',
    'publishPicks',
    'sessionSettings',
    'withSessionSettings',
    'panel',
    code,
  )(
    loaded,
    loaded.exports,
    {
      workspaceState: {
        update: async () => {
          events.push('agent persisted');
        },
      },
    },
    'askMode',
    () => ({}),
    host,
    acceptedPermissionMode,
    () => book,
    async (next: SessionSettingBook) => {
      book = next;
      events.push('sessions persisted');
    },
    () => events.push('published'),
    sessionSettings,
    withSessionSettings,
    {
      clearEffectiveModes: (_agent: string, sessions: string[]) => events.push(`cleared ${sessions.sort().join(',')}`),
    },
  );

  await loaded.exports.setAskModeFor('codex', { value: '', label: '', description: '' }, 'one');
  assert.deepEqual(events, [
    'barrier',
    'all barred',
    'cleared one,two',
    'sessions persisted',
    'agent persisted',
    'published',
    'retired',
  ]);
  assert.equal(sessionSettings(book, 'one').permissionMode, '');
  assert.equal(sessionSettings(book, 'two').permissionMode, '');
});

test('an explicit permission pick mutates no state when a default transition owns admission', async () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const setAt = extensionSource.indexOf('const setAskModeFor = async');
  const modelAt = extensionSource.indexOf('const setModelFor =', setAt);
  const loaded = { exports: {} as { setAskModeFor: (...args: any[]) => Promise<void> } };
  const code = esbuild.transformSync(`export ${extensionSource.slice(setAt, modelAt)}`, {
    loader: 'ts',
    format: 'cjs',
    target: 'esnext',
  }).code;
  const events: string[] = [];
  let releaseBarrier: () => void = () => undefined;
  const barrier = new Promise<void>((resolve) => {
    releaseBarrier = resolve;
  });
  const host = {
    states: () => [{ agent: 'claude', exited: false, key: 'claude:one', sessionId: 'one' }],
    withRetiringActivities: async () => {
      throw new Error('an explicit permission used retirement');
    },
    withActivities: async () => {
      await barrier;
      return null;
    },
  };
  new Function(
    'module',
    'exports',
    'context',
    'ASK_MODE_KEY',
    'stored',
    'host',
    'acceptedPermissionMode',
    'settingBook',
    'persistSettingBook',
    'publishPicks',
    'sessionSettings',
    'withSessionSettings',
    'panel',
    code,
  )(
    loaded,
    loaded.exports,
    {
      workspaceState: {
        update: async () => {
          events.push('agent persisted');
        },
      },
    },
    'askMode',
    () => ({}),
    host,
    acceptedPermissionMode,
    () => ({}),
    async () => {
      events.push('sessions persisted');
    },
    () => events.push('published'),
    sessionSettings,
    withSessionSettings,
    { clearEffectiveModes: () => undefined },
  );

  const changing = loaded.exports.setAskModeFor(
    'claude',
    { value: 'plan', label: 'Plan', description: '', claude: 'plan' },
    'one',
  );
  await vi.waitFor(() => assert.deepEqual(events, []));
  releaseBarrier();
  await assert.rejects(changing, /agent session closed before the permission changed/);
  assert.deepEqual(events, []);
});

test('an MCP change without its exact live owner uses an isolated child and refreshes that owner', () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const mcpChangeAt = extensionSource.indexOf('const setMcpFor = async');
  const mcpChange = extensionSource.slice(mcpChangeAt, extensionSource.indexOf('// What to start', mcpChangeAt));
  sourceMatch(
    mcpChange,
    /const target = liveMcpTarget\(live, owner, draftMcpKeys\);[\s\S]*if \(target\) \{[\s\S]*host\.changeMcp\(keys, changes\)/,
    'an MCP change without its owner was applied to same-agent siblings',
  );
  sourceMatch(
    mcpChange,
    /if \(result\.servers && noteMcp\(owner,/,
    'an exact live owner did not publish the status returned after its change',
  );
  sourceMatch(
    mcpChange,
    /\} else \{[\s\S]*askIdleMcpChange\(plan, spawnCli, changes\)[\s\S]*noteMcp\(owner,/,
    'an isolated MCP change did not refresh the selected owner',
  );
  sourceMatch(
    mcpChange,
    /agent: AgentName, owner: string, cwd: string \| null, value: string\)/,
    'an MCP change does not carry the selected owner folder',
  );
  sourceMatch(
    mcpChange,
    /const plan = cwd \? idlePlanFor\(agent, cwd\) : null;/,
    'an isolated MCP change starts in the workspace folder instead of the selected session folder',
  );
  sourceDoesNotMatch(mcpChange, /workspaceCwd\(\)/, 'an isolated MCP change discards the selected owner folder');
  sourceMatch(
    extensionSource,
    /setMcpFor\(which, session, cwd, value\)/,
    'the selected owner folder does not reach the MCP change',
  );
});

