function catalogRefreshFixture() {
  const source = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const statements = ['const publishPicks =', 'const readFrom =', 'const askAgent ='].map((needle) =>
    statementFrom(source, source.indexOf(needle)),
  );
  const models = new ModelBook();
  const mcp = new McpBook();
  const settledUsage = new Set<string>();
  const publications: Array<{ catalogs: Record<string, unknown>; pending: string[] }> = [];
  const calls: string[] = [];
  const control = { failure: 'none', live: false };
  const scope = {
    models,
    USAGE_AGENT_ORDER,
    mcp,
    liveMcpTarget,
    panel: {
      setAskLevels() {},
      setPicks() {},
      setModels(catalogs: Record<string, unknown>, pending: string[]) {
        publications.push({ catalogs, pending });
      },
    },
    settingBook: () => ({}),
    stored: () => ({}),
    ASK_MODE_KEY: 'askModes',
    publishUsage() {},
    publishCommands() {},
    commandLists: { revision: () => 0 },
    commandsAsked: new Set<string>(),
    usage: {
      toAsk: (agents: string[]) => agents.filter((agent) => !settledUsage.has(agent)),
      note: (agent: string) => settledUsage.add(agent),
      noteSilent: (agent: string) => settledUsage.add(agent),
    },
    usageReads: { run: (_agent: string, force: boolean, work: (force: boolean) => Promise<void>) => work(force) },
    host: {
      states: () => (control.live ? [{ agent: 'codex', key: 'live', exited: false, busy: false }] : []),
      withActivity: (_key: string, work: (session: unknown) => Promise<void>) =>
        work({
          agent: 'codex',
          rateLimits: async () => null,
          models: async () => {
            if (control.failure === 'throw') throw new Error('read failed');
            return null;
          },
        }),
    },
    draftMcpKeys: new Map(),
    mcpSurfaceGeneration: 0,
    workspaceCwd: () => 'C:/workspace',
    idlePlanFor: () => (control.failure === 'plan' ? null : {}),
    spawnCli() {},
    askIdle: async () => {
      calls.push('catalog');
      if (control.failure === 'throw') throw new Error('read failed');
      return {
        usage: {},
        models: control.failure === 'empty' ? null : { readAt: Date.now(), models: [] },
        commands: [],
      };
    },
    readIdleMcp: async (_agent: string, cwd: string, owner: string) => {
      calls.push(`MCP ${cwd} ${owner}`);
      return true;
    },
    readMcpFrom: async () => {},
  };
  const code = esbuild.transformSync(`${statements.join('\n')}\nreturn askAgent;`, { loader: 'ts' }).code;
  const ask = new Function(...Object.keys(scope), code)(...Object.values(scope)) as (
    agent: string,
    force: boolean,
    owner?: string,
    cwd?: string,
  ) => Promise<void>;
  return { ask, models, mcp, calls, publications, control };
}

test('a failed agent catalog read settles its pending state after the other agent publishes', async () => {
  for (const failure of ['plan', 'empty', 'throw']) {
    for (const live of failure === 'plan' ? [false] : [false, true]) {
      const fixture = catalogRefreshFixture();
      await fixture.ask('claude', false);
      assert.deepEqual(fixture.publications.at(-1)?.pending, ['codex']);
      Object.assign(fixture.control, { failure, live });
      await fixture.ask('codex', false);
      assert.equal(fixture.models.pending('codex'), false);
      assert.deepEqual(
        fixture.publications.at(-1)?.pending,
        [],
        `${failure} live=${live} kept failed catalogs pending`,
      );
    }
  }
});

