test('draft acceptance survives profile-save and adoption failures until removal or adoption', async () => {
  const source = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const statements = [
    'const acceptedDrafts =',
    'panel.onSendDraftPrompt =',
    'panel.onDraftProfileChanged =',
    'panel.onDraftAdopted =',
    'panel.onDraftRemoved =',
  ].map((needle) => statementFrom(source, source.indexOf(needle)));
  for (const failSave of [true, false]) {
    const retired: string[] = [];
    const panel: any = {
      setupProject: 'B',
      setRecentProfiles() {
        assert.fail('A recent history reached B');
      },
      refresh() {},
    };
    const live = { key: 'codex:fresh:accepted', prompt: async () => 7, state: () => ({ sessionId: 'actual' }) };
    const scope = {
      panel,
      retireDraftProfile,
      freshHostKey,
      USAGE_AGENT_ORDER,
      host: {
        cancelSessionRetirement() {},
        retireSession: async (key: string) => {
          retired.push(key);
        },
      },
      startFreshSession: async () => live,
      validateResolvedPromptAssets() {},
      withStartedSessionActivity: (_session: unknown, work: (session: typeof live) => unknown) => work(live),
      resumePlanForDraft() {},
      draftMcpKeys: new Map(),
      mcp: new McpBook(),
      mcpRefreshes: new McpPendingRefreshes(),
      activeMcpOwner: null,
      context: {
        globalState: {
          get: () => [],
          update: async () => {
            if (failSave) throw new Error('save failed');
          },
        },
      },
      RECENT_PROFILES_KEY: 'recent',
      recentProfiles,
      setupProjects: {
        resolve: async (cwd: string) => {
          assert.equal(cwd, 'C:/workspace');
          return 'A';
        },
      },
      setupStore: {
        accept: async (project: string) => {
          assert.equal(project, 'A');
          if (failSave) throw new Error('save failed');
          return { recents: [] };
        },
      },
      publishMcp() {},
      failedPromptDelivery: () => ({ delivered: false }),
      vscode: { window: { showErrorMessage() {} } },
    };
    const code = esbuild.transformSync(`${statements.join('\n')}\nreturn acceptedDrafts;`, { loader: 'ts' }).code;
    const accepted = new Function(...Object.keys(scope), code)(...Object.values(scope)) as Set<string>;
    const draft = newSessionDraft('accepted', 'C:/workspace', null, 0, {
      agent: 'codex',
      model: '',
      effort: '',
      permissionMode: '',
      source: 'recent',
    });
    assert.equal((await panel.onSendDraftPrompt(draft, { assets: [] })).delivered, !failSave);
    assert.equal(accepted.has(live.key), true);
    panel.onDraftProfileChanged(draft);
    assert.deepEqual(retired, []);
    accepted.add(freshHostKey('claude', draft.draftId));
    if (failSave) panel.onDraftRemoved(draft);
    else panel.onDraftAdopted(draft.draftId, 'actual');
    assert.equal(accepted.size, 0);
  }
});

test('an idle live child answers a missing initial MCP read', async () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const askAt = extensionSource.indexOf('const askAgent =');
  const liveAt = extensionSource.indexOf('if (live[0]) {', askAt);
  assert.ok(askAt >= 0 && liveAt >= 0, 'the idle live-child refresh branch is not available to exercise');
  const liveBranch = statementFrom(extensionSource, liveAt);
  const liveBody = liveBranch.slice(liveBranch.indexOf('{') + 1, liveBranch.lastIndexOf('}'));
  const calls: string[] = [];
  const run = new Function(
    'publishCommands',
    'commandsAsked',
    'mcp',
    'readMcpFrom',
    'readIdleMcp',
    'readFrom',
    'cwd',
    `return async function (live, agent, force, wantMcp, resolvedMcpOwner, mcpLive) {${liveBody}\n};`,
  )(
    () => calls.push('commands'),
    { add: () => calls.push('commands settled') },
    { beginInitialRead: () => true, finishInitialRead: () => calls.push('MCP settled') },
    async () => {
      calls.push('MCP read');
    },
    async () => {
      calls.push('idle MCP read');
      return true;
    },
    async () => {
      calls.push('usage read');
    },
    'C:\\ws',
  ) as (
    live: Array<{ key: string }>,
    agent: string,
    force: boolean,
    wantMcp: boolean,
    owner: string,
    mcpLive: { key: string } | undefined,
  ) => Promise<void>;

  await run([{ key: 'idle-live' }], 'claude', false, true, 'session-1', { key: 'idle-live' });
  assert.deepEqual(
    calls,
    ['commands', 'commands settled', 'MCP read', 'usage read'],
    'an idle live child closed the initial MCP gate without asking for server status',
  );
});

test('selected-owner MCP discovery ignores a busy sibling but waits for its own busy child', () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const askAt = extensionSource.indexOf('const askAgent =');
  const ask = extensionSource.slice(askAt, extensionSource.indexOf('const refreshUsage', askAt));
  sourceMatch(
    ask,
    /if \(mcpOwner \? mcpLive\?\.busy : live\.some\(\(s\) => s\.busy\)\)/,
    'a busy sibling suppresses the selected owner server read',
  );
  sourceMatch(
    ask,
    /const idleLive = mcpLive \?\? live\.find\(\(state\) => !state\.busy\);/,
    'selected-owner discovery reads a busy sibling after starting the owner server read',
  );
  const boundAt = ask.indexOf('const requestedMcpRevision =');
  assert.ok(
    boundAt >= 0 && boundAt < ask.indexOf('return usageReads.run('),
    'owner discovery binds its profile generation only after account reads begin',
  );
  sourceMatch(
    ask,
    /readIdleMcp\(agent, mcpCwd \?\? cwd, resolvedMcpOwner, revision, requestedMcpGeneration\)/,
    'selected-owner discovery starts its idle child in another folder',
  );
  sourceMatch(ask, /\}, requestOwner\);/, 'same-agent catalog reads can share a request across different MCP owners');
});

test('draft MCP wiring cancels stale work and leaves Codex Servers on its cached path', () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const commandAt = extensionSource.indexOf('panel.onPanelCommand =');
  const command = extensionSource.slice(commandAt, extensionSource.indexOf('const openPanelControl', commandAt));
  const claudeAt = command.indexOf("if (draft && which === 'claude')");
  const cachedCodexAt = layoutIndexOf(command, 'if (draft) { return; }');
  const idleReadAt = command.indexOf('readIdleMcp(which, directory, owner, revision, mcpSurfaceGeneration)');
  assert.ok(
    claudeAt >= 0 && cachedCodexAt > claudeAt && idleReadAt > cachedCodexAt,
    'opening Servers on a Codex draft can start a process instead of keeping its cached menu',
  );

  const selectionAt = extensionSource.indexOf('panel.onSelectionChanged =');
  const selection = extensionSource.slice(selectionAt, extensionSource.indexOf('panel.onDraftRemoved', selectionAt));
  sourceMatch(
    selection,
    /mcp\.change\(activeMcpOwner\);[\s\S]*mcpRefreshes\.cancel\(activeMcpOwner\)/,
    'leaving the owner can still publish or schedule from its in-flight initial read',
  );
  sourceMatch(
    selection,
    /if \(session && agent\) \{ refreshUsage\(agent, false, session, agent, cwd \?\? undefined\); \}/,
    'selecting a recorded session leaves its owner-scoped Servers state undiscovered',
  );
  const closeAt = extensionSource.indexOf('panel.onPanelsClosed =');
  const close = extensionSource.slice(closeAt, extensionSource.indexOf('panel.onPicked', closeAt));
  sourceMatch(
    close,
    /mcpSurfaceGeneration\+\+;[\s\S]*mcp\.invalidateInitialReads\(\)[\s\S]*mcpRefreshes\.dispose\(\)[\s\S]*host\.retireSession\(key\)/,
    'closing every panel leaves a draft read, scheduler, or provisional child alive',
  );
  sourceMatch(
    extensionSource,
    /const noteMcp = \([\s\S]*generation === mcpSurfaceGeneration && mcp\.note/,
    'an automatic MCP answer can publish after the panel surface that requested it closes',
  );
  sourceMatch(
    extensionSource,
    /const readIdleMcp =[\s\S]*const accepted = noteMcp\([\s\S]*return accepted;/,
    'a stale automatic read closes the initial-read gate after its panel closes',
  );
  const disposeAt = panelHostSource.indexOf('private disposeOwned(): void {');
  const dispose = memberFrom(panelHostSource, disposeAt);
  sourceMatch(dispose, /this\.onPanelsClosed\?\.\(\);/, 'extension disposal does not invalidate automatic MCP reads');
});

test('an accepted draft adopts before its settings are published under the real id', () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const draftAt = extensionSource.indexOf('panel.onSendDraftPrompt = async');
  const draft = extensionSource.slice(draftAt, extensionSource.indexOf('// The turn in the session', draftAt));
  sourceDoesNotMatch(
    draft,
    /persistSettingBook|publishPicks|SESSION_SETTINGS_KEY/,
    'provider acceptance publishes the real id before the panel can adopt the provisional state',
  );
  sourceMatch(
    extensionSource,
    /panel\.onSessionSettingsAdopted = \(session, settings\) => \{[\s\S]{0,120}persistSessionSettings\(session, settings\)/,
    'successful panel adoption does not publish the accepted setup to the reopening book',
  );
  const adoptAt = panelHostSource.indexOf('private adoptDraft(');
  const adopt = panelHostSource.slice(adoptAt, panelHostSource.indexOf('public setCommands(', adoptAt));
  const movedAt = adopt.indexOf('const next = adoptSessionIdentity(');
  const publishedAt = adopt.indexOf('this.onSessionSettingsAdopted?.(actual');
  assert.ok(
    movedAt >= 0 && publishedAt > movedAt,
    'settings publication can occupy the real id before the draft collision guard runs',
  );
  sourceMatch(
    adopt,
    /delete this\.newDrafts\[provisional\];[\s\S]*onSessionSettingsAdopted/,
    'settings publication runs while duplicate-retry draft state still exists',
  );
});

test('agent-default sessions leave permission overrides out of resume and fork plans', async () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const askAt = extensionSource.indexOf('function askModeFor(agent: string, session?: string): AskMode | undefined {');
  const modelAt = extensionSource.indexOf('const modelFor =', askAt);
  const openingAt = extensionSource.indexOf('const withExistingSessionActivity = async');
  const forkAt = extensionSource.indexOf('const forkCodexSession = async');
  const freshAt = extensionSource.indexOf('const startFreshSession = async');
  assert.ok(
    askAt >= 0 && modelAt > askAt && openingAt >= 0 && forkAt > openingAt && freshAt > forkAt,
    'the Codex opening functions are not available to exercise',
  );

  const askModule = {
    exports: {} as {
      askModeFor: (agent: string, session?: string) => unknown;
      askValueFor: (agent: string, session: string) => string | undefined;
    },
  };
  const askCode = esbuild.transformSync(`export ${extensionSource.slice(askAt, modelAt)}`, {
    loader: 'ts',
    format: 'cjs',
    target: 'esnext',
  }).code;
  let book: SessionSettingBook = {};
  new Function(
    'module',
    'exports',
    'sessionSettings',
    'savedAskMode',
    'storedAskValue',
    'settingBook',
    'stored',
    'ASK_MODE_KEY',
    `${askCode}\nmodule.exports.askValueFor = askValueFor;`,
  )(
    askModule,
    askModule.exports,
    sessionSettings,
    savedAskMode,
    storedAskValue,
    () => book,
    () => ({}),
    'askMode',
  );
  assert.equal(
    askModule.exports.askModeFor('codex', 'source'),
    undefined,
    'an unpicked Codex session resolves to an Arc permission mode',
  );
  assert.equal(
    askModule.exports.askModeFor('claude', 'source'),
    undefined,
    'an unpicked Claude session resolves to an Arc permission mode',
  );

  const resumeModule = { exports: {} as { withExistingSessionActivity: (...args: any[]) => Promise<unknown> } };
  const resumeCode = esbuild.transformSync(`export ${extensionSource.slice(openingAt, forkAt)}`, {
    loader: 'ts',
    format: 'cjs',
    target: 'esnext',
  }).code;
  let resumePlan: Record<string, unknown> | undefined;
  new Function(
    'module',
    'exports',
    'host',
    'launchFor',
    'existingHostKey',
    'askModeFor',
    'modelFor',
    'effortFor',
    'claudePlan',
    'claudeAskMode',
    'codexPlan',
    'CLIENT_INFO',
    resumeCode,
  )(
    resumeModule,
    resumeModule.exports,
    {
      find: () => null,
      withSessionActivity: async (_key: string, plan: () => Record<string, unknown>, work: () => Promise<unknown>) => {
        resumePlan = plan();
        return await work();
      },
    },
    () => ({ command: 'codex' }),
    () => 'codex:source',
    askModule.exports.askModeFor,
    () => 'gpt-5.6-sol',
    () => 'high',
    (_launch: unknown, plan: Record<string, unknown>) => plan,
    () => '',
    (_launch: unknown, plan: Record<string, unknown>) => plan,
    { name: 'arc' },
  );
  await resumeModule.exports.withExistingSessionActivity('codex', 'source', 'C:\\ws', async () => 'opened');
  assert.ok(resumePlan);
  for (const setting of ['approvalPolicy', 'approvalsReviewer', 'sandbox']) {
    assert.equal(setting in resumePlan, false, `an unpicked Codex resume sent ${setting}`);
  }

  const forkModule = { exports: {} as { forkCodexSession: (session: string, cwd: string | null) => Promise<unknown> } };
  const forkCode = esbuild.transformSync(`export ${extensionSource.slice(forkAt, freshAt)}`, {
    loader: 'ts',
    format: 'cjs',
    target: 'esnext',
  }).code;
  let forkPlan: Record<string, unknown> | undefined;
  let storedSettings: Record<string, unknown> | undefined;
  new Function(
    'module',
    'exports',
    'launchFor',
    'askModeFor',
    'askValueFor',
    'modelFor',
    'effortFor',
    'sessionSettingsForProfile',
    'ensureSession',
    'codexPlan',
    'codexAskMode',
    'CLIENT_INFO',
    'persistSessionSettings',
    'publishPicks',
    'forkSequence',
    forkCode,
  )(
    forkModule,
    forkModule.exports,
    () => ({ command: 'codex' }),
    askModule.exports.askModeFor,
    askModule.exports.askValueFor,
    () => 'gpt-5.6-sol',
    () => 'high',
    sessionSettingsForProfile,
    async (_key: string, plan: Record<string, unknown>) => {
      forkPlan = plan;
      return { state: () => ({ sessionId: 'continued' }) };
    },
    (_launch: unknown, plan: Record<string, unknown>) => plan,
    () => ({}),
    { name: 'arc' },
    async (_session: string, settings: Record<string, unknown>) => {
      storedSettings = settings;
    },
    () => undefined,
    0,
  );
  await forkModule.exports.forkCodexSession('source', 'C:\\ws');
  assert.ok(forkPlan);
  for (const setting of ['approvalPolicy', 'approvalsReviewer', 'sandbox']) {
    assert.equal(setting in forkPlan, false, `an unpicked Codex fork sent ${setting}`);
  }
  assert.ok(storedSettings);
  assert.equal(
    'permissionMode' in storedSettings,
    false,
    'a Codex fork of a session with no stored pick stored a pick of the Codex default',
  );
  book = withSessionSettings({}, 'source', { ...sessionSettings({}, 'source'), permissionMode: '' });
  await forkModule.exports.forkCodexSession('source', 'C:\\ws');
  assert.equal(storedSettings?.permissionMode, '', 'a Codex fork dropped the Codex default its source session chose');
  for (const setting of ['approvalPolicy', 'approvalsReviewer', 'sandbox']) {
    assert.equal(setting in forkPlan, false, `a Codex fork of an explicit Codex default sent ${setting}`);
  }
  book = {};

  await resumeModule.exports.withExistingSessionActivity('claude', 'source', 'C:\\ws', async () => 'opened');
  assert.ok(resumePlan);
  assert.equal('permissionMode' in resumePlan, false, 'an unpicked Claude resume sent --permission-mode');
});

