test('the corpus does not fill the cache the render path reads', () => {
  // `readFor` holds one entry per file. A corpus read asks for every turn and a different
  // number of bytes, so going through it overwrites what the render path just filled, and
  // stores a full parsed read of every session in the workspace rather than the few on screen.
  const body = memberFrom(panelHostSource, panelHostSource.indexOf('private searchCorpus(only'));
  assert.ok(body.length > 100, 'searchCorpus has gone, so this guard cannot see how it reads');
  sourceDoesNotMatch(
    body,
    /this\.readFor\(/,
    'the corpus reads through the shared cache, so it evicts the render path and stores every session',
  );
  sourceMatch(body, /readCodexSession\(session\.file/, 'the corpus no longer reads a Codex session at all');
  sourceMatch(
    body,
    /held\.mtimeMs === session\.mtimeMs && held\.size === session\.size/,
    'the corpus is keyed on mtime alone, so two appends in one tick leave it stale',
  );
});

test('a repaint follows every session drawn, not only the few that are parsed', () => {
  // The picker draws every session in the workspace with its name and its clock time, so one
  // that is listed and never parsed can still change what is on screen: renaming it writes a
  // new title into its transcript. Watching only the parsed few means nothing notices until
  // something else moves.
  sourceMatch(
    panelHostSource,
    /const listed: ListingFacts = \{\s*showing: this\.showing, files: all,/,
    'the repaint signature watches only the sessions being parsed, so renaming any other one is never noticed',
  );
  sourceDoesNotMatch(
    panelHostSource,
    /const listed: ListingFacts = \{\s*showing: this\.showing, files: sessions,/,
    'the repaint signature is back to the parsed few',
  );
});

test('a Codex thread being named is a reason to repaint', () => {
  // Renaming a Codex session writes into an index of its own and touches no transcript, so
  // the file terms of the signature all stay where they were. The index has to be looked at
  // before the signature is built and its state carried into it, or a name that lands after
  // the rollout has gone quiet is never noticed and the panel shows `Session 01a0545e` until
  // the window is reloaded.
  const body = memberFrom(panelHostSource, panelHostSource.indexOf('async refresh('));
  assert.ok(body.length > 100, 'refresh has gone, so this guard cannot see what it compares');
  sourceMatch(
    body,
    /this\.threadNames = readThreadNames\(codexSessionIndexPath\(\), this\.threadNames\);[\s\S]*const listed: ListingFacts = \{/,
    'the thread names are not read before the signature, so a session being named cannot reach it',
  );
  sourceMatch(
    body,
    /threadNames: this\.threadNames\.stamp/,
    'the signature ignores the thread index, so a name landing on a finished session repaints nothing',
  );
});

test('a child refreshes its cost while a running child is scanned again at most once a band', () => {
  const refresh = panelHostSource.slice(panelHostSource.indexOf('async refresh('));
  const compare = refresh.indexOf('refreshWanted({');
  assert.ok(compare > 0, 'refresh no longer has an early-return comparison');
  assert.ok(
    refresh.slice(0, compare).includes('const children = this.agentListingStamp(sessions);'),
    'completed child files are checked only after an unchanged parent returns early',
  );
  const workerEntry = fs.readFileSync(path.join(__dirname, 'progressiveworker-entry.ts'), 'utf8');
  const body = statementFrom(workerEntry, workerEntry.indexOf('const agentSpendOf: AgentSpendLookup'));
  sourceMatch(
    body,
    /readChildSpend\(agentSpends, file, agent\.status,[\s\S]*readClaudeAgentSpend[^;]*spendNow\)[\s\S]*readChildSpend\(agentSpends, file, agent\.status,[^;]*readCodexSpend[^;]*spendNow\)/,
    'a running child transcript is scanned again on every write instead of once a band',
  );
  sourceMatch(
    workerEntry,
    /agentKey: agentSpendDependencyKey\([^;]*codexChildFiles, spendNow\)/,
    'the worker files a cost key from another clock reading than its spend reads, so a quiet child keeps a stale cost',
  );
  const factsAt = panelHostSource.indexOf('private async refreshAgentFacts(');
  const facts = memberFrom(panelHostSource, factsAt);
  sourceMatch(
    facts,
    /progressiveInput\(session, now\)/,
    'the host stores a cost key from another clock reading than the worker read, so a quiet child keeps a stale cost',
  );
});

