test('complete renders publish every pending session adoption before composer state', () => {
  const payloadAt = panelHostSource.indexOf('const payloadInput = {');
  const payload = statementFrom(panelHostSource, payloadAt);
  sourceMatch(
    panelHostSource.slice(panelHostSource.lastIndexOf('const railAdoptions =', payloadAt), payloadAt),
    /const railAdoptions = sessionAdoptions\(this\.sessionAliases\);/,
    'the render does not collect every pending session adoption',
  );
  sourceMatch(
    payload,
    /sessionAdoptions: railAdoptions,/,
    'a background adoption is omitted when another session is selected',
  );
  sourceDoesNotMatch(
    payload,
    /sessionAdoptionFor|sessionAdoptions[^;]*this\.showing/,
    'the complete render still limits adoption mappings to the selected session',
  );

  const renderHandler = panelHandler('render');
  const adoptionAt = renderHandler.indexOf('composerRenderer.adoptSessionIdentity(');
  const usageAt = renderHandler.indexOf('usageState = msg.usage;');
  assert.ok(
    adoptionAt >= 0 && usageAt > adoptionAt,
    'the complete render applies composer state before it registers pending session adoptions',
  );
});

test('archive and unarchive are bounded membership updates', () => {
  const updateSessionMembership = new Function(
    'STATE_KEY',
    `return function (action, session, openPinned = false) {\n${methodBody('private updateSessionMembership(')
      .replace(/: ReadonlySet<string>/g, '')
      .replace(/\): boolean =>/, ') =>')}\n};`,
  )('arc.panelState');
  const setSessionArchived = new Function(
    `return function (session, archived) {\n${methodBody('public setSessionArchived(')}\n};`,
  )();
  const archiveChanges: string[][] = [];
  const persisted: unknown[] = [];
  const provider = {
    sessionAliases: new Map(),
    hidden: new Set<string>(),
    pinnedTop: new Set(['durable']),
    saved: { hidden: ['durable'], pinnedTop: ['durable'] },
    memento: {
      update(_key: string, value: unknown) {
        persisted.push(structuredClone(value));
      },
    },
    refreshes: 0,
    enumerations: 0,
    railPosts: 0,
    panelSession(session: string) {
      return resolveSessionAlias(this.sessionAliases, session);
    },
    onArchivedSessionsChange(sessions: ReadonlySet<string>) {
      archiveChanges.push([...sessions]);
    },
    refresh() {
      this.refreshes += 1;
    },
    allSessions() {
      this.enumerations += 1;
    },
    postRail() {
      this.railPosts += 1;
    },
    updateSessionMembership(action: string, session?: string) {
      updateSessionMembership.call(this, action, session);
    },
  };
  rememberSessionAlias(provider.sessionAliases, 'provisional', 'durable');
  setSessionArchived.call(provider, 'provisional', true);
  assert.deepEqual([...provider.hidden], ['durable']);
  assert.deepEqual([...provider.pinnedTop], []);
  assert.deepEqual(archiveChanges, [['durable']]);
  assert.equal(persisted.length, 1);
  assert.equal(provider.railPosts, 1);

  setSessionArchived.call(provider, 'provisional', false);
  assert.deepEqual([...provider.hidden], []);
  assert.deepEqual(
    provider.saved,
    { hidden: [], pinnedTop: [] },
    'the durable membership change was not made reload-safe',
  );
  assert.deepEqual(archiveChanges, [['durable'], []]);
  assert.equal(persisted.length, 2);
  assert.equal(provider.railPosts, 2);
  assert.equal(provider.refreshes, 0);
  assert.equal(provider.enumerations, 0);
});

