test('overlapping membership operations from two panels preserve and publish both changes', async () => {
  const provider = Object.create(PanelProvider.prototype) as LiveProvider;
  const first = { name: 'first' };
  const second = { name: 'second' };
  const delivered = new Map<object, Array<{ hidden: string[]; pinnedTop: string[] }>>([
    [first, []],
    [second, []],
  ]);
  const persisted: unknown[] = [];
  Object.assign(provider, {
    hosts: [first, second],
    readyHosts: new Set([first, second]),
    sessionAliases: new Map(),
    clearRoutes: new Map(),
    hidden: new Set<string>(),
    pinnedTop: new Set<string>(),
    saved: normalizePanelState(null),
    cards: [],
    onArchivedSessionsChange: null,
    memento: {
      update(_key: string, state: unknown) {
        persisted.push(structuredClone(state));
      },
    },
    postRail() {
      for (const host of this.hosts) {
        delivered.get(host)!.push({ hidden: [...this.hidden], pinnedTop: [...this.pinnedTop] });
      }
    },
  });
  const onMessage = provider as unknown as {
    onMessage(message: unknown, host: object): Promise<void>;
  };

  await onMessage.onMessage(
    {
      type: 'sessionMembership',
      action: 'archive',
      session: 'archived-by-first',
    },
    first,
  );
  await onMessage.onMessage(
    {
      type: 'sessionMembership',
      action: 'pin',
      session: 'pinned-by-second',
    },
    second,
  );

  const expected = { hidden: ['archived-by-first'], pinnedTop: ['pinned-by-second'] };
  assert.deepEqual(delivered.get(first)?.at(-1), expected);
  assert.deepEqual(delivered.get(second)?.at(-1), expected);
  assert.equal(persisted.length, 2, 'one operation caused more than one workspace-state write');
});

