test('a failed turn without runtime facts keeps the Composer on the last recorded runtime', () => {
  const rows = [{ id: 'codex', label: 'Codex session', agentKey: 'codex' }];
  const recorded = turn({
    agent: 'codex',
    sessionId: 'codex',
    promptId: 'recorded',
    startedAt: 1_000,
    endedAt: 2_000,
    model: 'gpt-5.6-sol',
    effort: 'high',
    provider: 'openai',
    contextTokens: 100_000,
    contextWindow: 272_000,
    contextRequest: {
      at: 1_500,
      lifetime: '30m',
      inferenceClass: null,
      serviceTier: null,
      readBack: true,
      outputTokens: 8_000,
    },
  });
  const failed = turn({
    agent: 'codex',
    sessionId: 'codex',
    promptId: 'failed',
    startedAt: 3_000,
    endedAt: 3_500,
    model: null,
    effort: null,
    contextTokens: 0,
    contextWindow: null,
    finished: true,
    error: 'AWS credentials expired',
  });
  const current = currentRecordsBySession([recorded, failed], []);
  assert.equal(current.newestTurns.get('codex'), failed, 'the failed turn stopped being the newest timeline record');

  const state = stateForRow(rows, {}, 'codex', {
    newest: current.newestTurns,
    compactions: current.newestCompactions,
    runtime: composerRuntimeBySession([recorded, failed], current.newestCompactions),
  });
  assert.deepEqual(
    {
      model: state.settings.confirmedModel,
      effort: state.settings.confirmedEffort,
      context: state.context,
      nextTurn: state.nextTurn && {
        tokens: state.nextTurn.tokens,
        outputTokens: state.nextTurn.outputTokens,
        lastRequestAt: state.nextTurn.lastRequestAt,
      },
    },
    {
      model: 'gpt-5.6-sol',
      effort: 'high',
      context: { used: 100_000, max: 272_000 },
      nextTurn: { tokens: 100_000, outputTokens: 8_000, lastRequestAt: 1_500 },
    },
  );
});

