  '.summary code, .headline code { font-size: 0.9em }',
  '.codeblock .copy { font: inherit }',
  '.codeblock .copy { font-size: var(--t-small) }',
  '.summary table { font-size: 0.9em }',
  '.editor-link { font: inherit }',
  '.editor-link { font-size: var(--t-body) }',
  '.summary .image-link { font: inherit }',
  '.prompt { font-size: 0.9em }',
  '.more { font: inherit }',
  '.more { font-size: var(--t-body) }',
  '.notequote { font-size: 0.9em }',
  '.noteact { font: inherit }',
  '.noteact { font-size: var(--t-body) }',
  '.notesave { font: inherit }',
  '.notesave { font-size: var(--t-body) }',
  '.noteclose { font: inherit }',
  '.noteclose { font-size: 1.05em }',
  '.notearea { font: inherit }',
  '.notearea { font-size: 0.92em }',
  '.cask .twist { font-size: var(--t-body) }',
  '#prompt { font: inherit }',
  '#prompt { font-size: 0.95em }',
  '.cfile { font-size: var(--t-small) }',
  '.ckind { font-size: 0.9em }',
  '.cfileremove { font: inherit }',
  '.cnotice { font-size: var(--t-small) }',
  '.clivereply { font-size: var(--t-small) }',
