test('local HTML and Markdown response links use their readers', () => {
  const opener = panelHostSource.slice(
    panelHostSource.indexOf('async function openLink('),
    panelHostSource.indexOf('// A picture the reader pressed', panelHostSource.indexOf('async function openLink(')),
  );
  const directory = opener.indexOf("executeCommand('revealInExplorer', uri)");
  const html = opener.indexOf("if (uri.scheme === 'file' && linkTargetIsHtml(uri.fsPath))");
  assert.ok(directory !== -1 && html > directory, 'an HTML-named directory bypasses the existing directory action');

  // A picture reaches the editor's own viewer. The text editor refuses one and throws from
  // the same call a missing file throws from, so without this branch a link to a picture
  // that is on disk told the reader there was no file at that path.
  const image = opener.indexOf("if (uri.scheme === 'file' && linkTargetIsImage(uri.fsPath))");
  assert.ok(
    image !== -1 && image > directory && image < html,
    'a response link to a picture is opened as text, which reports the file as missing',
  );
  sourceMatch(
    opener.slice(image, html),
    /executeCommand\('vscode\.open', uri, \{ viewColumn: column \}\)/,
    'a picture is not handed to the editor viewer in the group the link asked for',
  );
  sourceMatch(
    opener,
    /executeCommand\(\s*'workbench\.action\.browser\.open',\s*uri\.toString\(true\)\s*\)/,
    'a local HTML file is not sent to the integrated browser',
  );

  const markdown = opener.indexOf("if (uri.scheme === 'file' && linkTargetIsMarkdown(uri.fsPath))");
  const htmlBranch = opener.slice(html, markdown);
  sourceMatch(
    htmlBranch,
    /Arc: VS Code did not open \$\{uri\.fsPath\} in the integrated browser\./,
    'a browser failure does not name the local file and browser action',
  );
  sourceDoesNotMatch(htmlBranch, /showTextDocument/, 'a browser failure falls back to raw HTML in the text editor');
  sourceMatch(htmlBranch, /\breturn;\s*\}\s*$/, 'the HTML branch falls through and opens the same file as raw text');
  assert.ok(markdown > html, 'a Markdown response link bypasses the directory, picture, or HTML routes');
  const markdownBranch = opener.slice(markdown, opener.indexOf('const selection', markdown));
  sourceMatch(
    markdownBranch,
    /executeCommand\(\s*'vscode\.openWith',\s*uri,\s*'vscode\.markdown\.preview\.editor',\s*column\s*\)/,
    'a Markdown response link is not sent to Markdown Preview in its requested editor group',
  );
  sourceMatch(
    markdownBranch,
    /Arc: VS Code did not open \$\{uri\.fsPath\} in Markdown Preview\./,
    'a Markdown Preview failure does not name the local file and reader',
  );
  sourceDoesNotMatch(
    markdownBranch,
    /showTextDocument/,
    'a Markdown Preview failure falls back to raw Markdown in the text editor',
  );
  sourceMatch(
    markdownBranch,
    /\breturn;\s*\}\s*$/,
    'the Markdown Preview branch falls through and opens the same file as raw text',
  );
  sourceMatch(
    opener,
    /showTextDocument\(uri, \{ selection, preview: true, viewColumn: column \}\)/,
    'a non-Markdown response link no longer opens in its requested editor group',
  );
});

test('a picture in a response reaches the reader, and the file it names opens on a press', () => {
  // The tested renderer produces the button and decides which file may be drawn. This guard
  // holds the host seams no test can import to it. Each one is invisible on its own: a
  // resource root nothing asks for, a message nothing sends, and a listener nothing reaches
  // all read as working code, and the reader sees the same empty box behind any of them.
  const rootsAt = panelHostSource.indexOf('private allowThemeFiles(webview: vscode.Webview)');
  const roots = memberFrom(panelHostSource, rootsAt);
  assert.ok(roots.length > 60, 'allowThemeFiles has gone, so this guard cannot see the resource roots');
  sourceMatch(
    roots,
    /workspaceFolders \?\? \[\]\)\.map\(\(f\) => f\.uri\)/,
    'the webview may not read the open folders, so every picture a response names draws nothing',
  );

  // Built per host, like the icon column beside it. One shared URI draws a picture in the
  // webview it was made for and a broken box in the other.
  sourceMatch(
    panelHostSource,
    /webview\.asWebviewUri\(vscode\.Uri\.file\(file\)\)\.toString\(\)/,
    'a picture is addressed to no webview, so only the host that built it can load one',
  );
  sourceMatch(
    panelHostSource,
    /const resolveImage = this\.imagesFor\(webview\);/,
    'cards are sent without a per-host picture address',
  );
  sourceMatch(
    panelHostSource,
    /if \(!inSummary && !inAnswers && !inSaid\) \{ return card; \}/,
    'every card is rendered again for every host, so an idle poll pays a parse per card',
  );
  // The mid-turn messages are markdown too, so a picture named in one is re-rendered per
  // host beside the response and the answers. Without it the section draws image syntax.
  sourceMatch(
    panelHostSource,
    /saidMessages: card\.saidMessages\.map\(\(said\) => \(\{/,
    'a mid-turn message is posted without rendered html, so the section draws nothing',
  );
  sourceMatch(
    panelHostSource,
    /const inSaid = card\.saidMessages\.some\(\(said\) => hasImageReference\(said\.text\)\);/,
    'a picture named in a mid-turn message draws as literal text',
  );

  // The rule itself, lifted and run against a card that names a picture. Read as text it
  // answers nothing: a scan finds the names it looks for whether or not they are wired to
  // anything, and a whole branch can go missing under one.
  const pictured = (card: Record<string, unknown>) => {
    const marker = 'private picturedFor(card: RenderCard, resolveImage: ImageResolver): RenderCard {';
    const from = panelHostSource.indexOf(marker);
    assert.notEqual(from, -1, 'panelhost.ts no longer has a picturedFor, so this guard cannot run it');
    const rest = memberFrom(panelHostSource, from).slice(marker.length);
    const end = rest.lastIndexOf('}');
    assert.notEqual(end, -1, 'picturedFor has no closing brace');
    return new Function(
      'card',
      'resolveImage',
      'hasImageReference',
      'renderRichMarkdown',
      esbuild.transformSync(rest.slice(0, end), { loader: 'ts' }).code,
    )(
      card,
      (target: string) => ({ src: `vscode-webview://host/${target}`, path: `C:/work/${target}` }),
      hasImageReference,
      renderRichMarkdown,
    ) as Record<string, unknown>;
  };
  const drawn = pictured({
    kind: 'turn',
    summary: 'the response names no picture',
    summaryHtml: '<p>the response names no picture</p>',
    earlierAnswers: [],
    saidMessages: [
      {
        kind: 'commentary',
        at: 1,
        text: 'Here is how it looks: ![a shot](shot.png)',
        summaryHtml: '<p>rendered once with no host, which is the parse thrown away here</p>',
      },
    ],
  });
  const message = (drawn.saidMessages as Array<{ summaryHtml: string }>)[0].summaryHtml;
  assert.match(
    message,
    /<img src="vscode-webview:\/\/host\/shot\.png"/,
    'a picture named while the turn ran is addressed to no host, so the section draws a broken box',
  );
  assert.match(
    message,
    /data-image="C:\/work\/shot\.png"/,
    'the picture in a mid-turn message opens nothing when the reader presses it',
  );
  // A card naming a picture nowhere is handed back whole, which is what keeps an idle poll
  // from paying a parse per card per host.
  const plain = {
    kind: 'turn',
    summary: 's',
    summaryHtml: '<p>s</p>',
    earlierAnswers: [],
    saidMessages: [{ kind: 'commentary', at: 1, text: 'no picture', summaryHtml: '<p>no picture</p>' }],
  };
  assert.equal(pictured(plain), plain, 'a card naming no picture is rebuilt for every host');

  sourceMatch(
    hostHandler('openImage'),
    /await openImage\(msg\.path,/,
    'the extension host does not receive the picture press',
  );

  const opener = panelHostSource.slice(
    panelHostSource.indexOf('async function openImage('),
    panelHostSource.indexOf('// A visualization reference is local HTML'),
  );
  assert.ok(opener.length > 60, 'openImage has gone, so this guard cannot see how a picture opens');
  sourceMatch(
    opener,
    /imagePathFor\(target, folders\)/,
    'the host opens whatever path the webview sent, without asking whether it is in the workspace',
  );
  sourceMatch(
    opener,
    /'vscode\.open', vscode\.Uri\.file\(file\)/,
    'the picture does not open in the editor, so the panel needs a viewer of its own',
  );

  // A screenshot is taller than a card. Without the bound it pushes everything below it off
  // the screen, and the browser test measures that. Written against the picture rather than
  // the button, because a picture the response wrote as a link is drawn without one.
  assert.match(
    styleRulesNaming('.summary img'),
    /max-height:/,
    'a picture in a response is drawn at its own height, so one screenshot fills the panel',
  );
});

test('the panel imports shared label notes and keeps no copied rule', () => {
  sourceMatch(railSource, /from '\.\.\/domain\/labels[.]ts'/);
  sourceDoesNotMatch(script + railSource, /function labelTypedNotes\(/);
  assert.deepEqual(labelTypedNotes('rail, perf'), ['comma']);
  assert.deepEqual(labelTypedNotes('a'.repeat(LABEL_NAME_LIMIT + 1)), ['limit']);
});
// The popover itself, built and pressed. It is the one surface in the panel that writes to a
// record the extension owns, so what it posts is what the reader's labels become.

// What a keystroke costs the reader, and what the popover is still holding when it redraws.
//
// The popover is rebuilt on every keystroke, because the box narrows the rows under it. So the
// three things a rebuild can take are the whole of what this asks about: the box the reader is
// typing into, the two keys that move a caret inside it, and the control the popover hangs off.

// The id a session the panel starts is filed under, held against the rule that sweeps it.
//
// `sweepDraftLabels` takes an entry off the stored record when its key opens with
// `DRAFT_SESSION_PREFIX`. A draft id built any other way is one the sweep never recognizes: its
// labels stay on the record for ever, they hold a place under the record's ceiling, and they
// count towards a label in the catalogue that files nothing a reader can open.
test('every provisional session id is built from the prefix the sweep matches on', () => {
  const template = '`${DRAFT_SESSION_PREFIX}${crypto.randomUUID()}`';
  const built: string[] = [];
  for (const call of panelHostSource.matchAll(/this\.createDraft\(\s*([^,\n]+),/g)) {
    const arg = call[1].trim();
    if (!/^\w+$/.test(arg)) {
      built.push(arg);
      continue;
    }
    // A name rather than the id itself, so the declaration it was last given before the call
    // is what the id is really built from.
    const declared = [...panelHostSource.slice(0, call.index).matchAll(new RegExp(`const ${arg} = (.+);`, 'g'))].pop();
    built.push(declared ? declared[1] : arg);
  }
  assert.ok(built.length > 0, 'panelhost.ts starts no session of its own, so nothing here is measured');
  assert.deepEqual(
    [...new Set(built)],
    [template],
    'a draft session is filed under an id the sweep cannot recognize, so its labels outlive the window',
  );
});

// Two hosts, two editors, one record.
//
// A write moves the count on every label the workspace has, and can add one no open editor
// names. The extension cannot tell which session each host has open, so it says only that
// something moved and each host asks again for its own.

// The walk inside the popover, run rather than scanned. Which key does what is a run of
// conditionals, and a guard that only reads the call site passes with any two of them swapped.

// The one press that makes a label, and the composition that owns it.
//
// A reader typing a Japanese or Chinese name accepts each candidate with Enter. Taken here,
// that press files the session under whatever half-written text the box holds at the
// moment they accept, and the label is on the record before the word is finished.

// The order a popover already open keeps through a write.
//
// The extension answers every write with a fresh set of rows, and its order puts the
// session's own labels at the front. Taken again while the popover is open, that order
// moves the row the reader has just ticked to the top of the list they are reading, between
// one press and the next.

test('the rail card and the session heading both offer the read state the session is not in, and none of it in the palette', () => {
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
  const titles = new Map<string, string>(
    manifest.contributes.commands.map((c: { command: string; title: string }) => [c.command, c.title]),
  );
  // The words are the manifest's, since the entries are drawn by the editor. The rail card
  // and the session heading share one title on purpose, and every session command is hidden
  // from the command palette below, so `category` only has to tell the session command apart
  // from the turn command of the same name in the Keyboard Shortcuts editor, where the menu's
  // own placement offers no such hint.
  assert.equal(titles.get('arc.markSessionRead'), 'Mark as read');
  assert.equal(titles.get('arc.markSessionUnread'), 'Mark as unread');
  const categories = new Map<string, string | undefined>(
    manifest.contributes.commands.map((c: { command: string; category?: string }) => [c.command, c.category]),
  );
  for (const command of [
    'arc.markSessionRead',
    'arc.markSessionUnread',
    'arc.markTurnRead',
    'arc.markTurnUnread',
    'arc.pinSession',
    'arc.unpinSession',
    'arc.archiveSession',
    'arc.unarchiveSession',
    'arc.renameSession',
    'arc.labelSession',
    'arc.showSessionDetails',
  ]) {
    const expected = command.includes('Turn') ? 'Arc Turn' : 'Arc Session';
    assert.equal(
      categories.get(command),
      expected,
      `${command} carries no category consistent with the rest of its own menu`,
    );
  }
  for (const [session, turn] of [
    ['arc.markSessionRead', 'arc.markTurnRead'],
    ['arc.markSessionUnread', 'arc.markTurnUnread'],
  ]) {
    assert.notEqual(
      `${categories.get(session)} ${titles.get(session)}`,
      `${categories.get(turn)} ${titles.get(turn)}`,
      `${session} and ${turn} share a title and a category, so the Keyboard Shortcuts editor cannot tell them apart`,
    );
  }

  const menu = manifest.contributes.menus['webview/context'] as { command: string; when: string; group: string }[];
  const whenOf = (command: string) => menu.filter((m) => m.command === command).map((m) => m.when);
  // Composed from the table rather than written out, so a name renamed on one side still
  // fails: a clause naming a section nothing writes matches no card at all, and the entry
  // simply never appears. The rail names its read state in its own section, and the
  // session heading carries a plain read flag instead, since its two sections already name
  // the archived state.
  const S = RAIL_MENU_SECTIONS;
  const H = SESSION_MENU_SECTIONS;
  const onHeading = (suffix: string) =>
    `(webviewSection == '${H.live}' || webviewSection == '${H.archived}') && ${suffix}`;
  assert.deepEqual(
    whenOf('arc.markSessionRead'),
    [onHeading("sessionRead == 'unread'"), `webviewSection == '${S.unread}'`],
    'the mark is not offered on exactly the sessions with something new',
  );
  assert.deepEqual(
    whenOf('arc.markSessionUnread'),
    [onHeading("sessionRead == 'read'"), `webviewSection == '${S.read}'`],
    'the way back is not offered on exactly the sessions with nothing new',
  );
  // A context key VS Code compares against the boolean literal `false` also matches the key
  // being absent, which is exactly the case of nothing markable this entry must stay off of.
  // A word the key holds only when an entry applies has no such reading.
  assert.doesNotMatch(
    whenOf('arc.markSessionRead').join(''),
    /=== false|== false/,
    'the mark reads a boolean the absent case answers the same way as the direction it is not',
  );
  assert.doesNotMatch(
    whenOf('arc.markSessionUnread').join(''),
    /=== true|== true/,
    'the way back reads a boolean the absent case can be mistaken for',
  );

  // Out of the palette, like every other entry that acts on what was right-clicked: pressed
  // with nothing under the pointer they have no session to name.
  const palette = manifest.contributes.menus.commandPalette as { command: string; when: string }[];
  for (const command of ['arc.markSessionRead', 'arc.markSessionUnread']) {
    assert.ok(
      palette.some((m) => m.command === command && m.when === 'false'),
      `${command} is in the command palette, where it has no session to act on`,
    );
  }

  // The hand-off, both halves: a message nothing listens for and a listener nothing sends to
  // look the same from either side.
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  sourceMatch(
    extensionSource,
    /reg\('arc\.markSessionRead', \(arg\) => setSessionRead\(panel, arg, true\)\);/,
    'the session mark is registered on something other than the read hand-off',
  );
  sourceMatch(
    extensionSource,
    /reg\('arc\.markSessionUnread', \(arg\) => setSessionRead\(panel, arg, false\)\);/,
    'the session way back is registered on something other than the read hand-off',
  );
  // Nothing about the argument's shape is guaranteed, so a session is named or nothing
  // is sent, the way a turn key is read.
  sourceMatch(
    extensionSource,
    /const session = sessionIdFrom\(arg\);\s*if \(!session\) \{\s*return;\s*\}/,
    'the session commands send a message for an argument that names no session',
  );
  sourceMatch(
    panelHostSource,
    /void this\.post\(\{ type: 'setSessionRead', session: this\.panelSession\(session\), read \}\);/,
    'the session commands reach no host, or they reach only one of the two',
  );
  sourceMatch(
    panelHandler('setSessionRead'),
    /readState\.setSession\(msg\.session, msg\.read\);/,
    'the message never reaches the two presses, so the menu entries do nothing',
  );
  // The heading's own read flag, refreshed the way its pinned and archived facts are.
  const panelSource = fs.readFileSync(path.join(__dirname, 'webview', 'panel.ts'), 'utf8');
  sourceMatch(
    panelSource,
    /sessionState\.context\(session, persisted, \{\s*sessionRead: sessionReadState\(session\),/,
    'the heading row no longer carries the read state its own menu entries gate on',
  );
  sourceMatch(
    fs.readFileSync(path.join(__dirname, 'webview', 'timeline-renderer.ts'), 'utf8'),
    /options\.cardOptions\.read\.subscribe\(reconcile\)/,
    'a read change elsewhere in the session no longer refreshes the heading menu',
  );
});

test('the rail card and the session heading both offer archiving, and none of it in the palette', () => {
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
  const titles = new Map<string, string>(
    manifest.contributes.commands.map((c: { command: string; title: string }) => [c.command, c.title]),
  );
  // Short words: the context menu is the only place either title is drawn, since both are
  // withheld from the command palette below.
  assert.equal(titles.get('arc.archiveSession'), 'Archive');
  assert.equal(titles.get('arc.unarchiveSession'), 'Unarchive');
  // Bare enough, out of the menu that gives them a session, to read as nothing in the
  // Keyboard Shortcuts editor: a category names what they act on, and it names the session
  // rather than the whole extension so it also tells the pair apart from the turn command of
  // the same title.
  const categories = new Map<string, string | undefined>(
    manifest.contributes.commands.map((c: { command: string; category?: string }) => [c.command, c.category]),
  );
  assert.equal(categories.get('arc.archiveSession'), 'Arc Session');
  assert.equal(categories.get('arc.unarchiveSession'), 'Arc Session');

  const menu = manifest.contributes.menus['webview/context'] as { command: string; when: string; group: string }[];
  const whenOf = (command: string) => menu.filter((m) => m.command === command).map((m) => m.when);
  // Composed from the table rather than written out. Nothing typechecks a when clause, and a
  // clause naming a section nothing writes matches no row at all: the entry then never
  // appears, silently, and a one-character difference on either side is enough. The rail
  // names its archived state directly, since its three sections already name read state.
  const S = RAIL_MENU_SECTIONS;
  const H = SESSION_MENU_SECTIONS;
  const onRail = (suffix: string) =>
    `(webviewSection == '${S.unread}' || webviewSection == '${S.read}' || webviewSection == '${S.plain}') && ${suffix}`;
  assert.deepEqual(
    whenOf('arc.archiveSession'),
    [`webviewSection == '${H.live}'`, onRail('!sessionArchived')],
    'archiving is not offered on exactly the sessions that are not archived',
  );
  assert.deepEqual(
    whenOf('arc.unarchiveSession'),
    [`webviewSection == '${H.archived}'`, onRail('sessionArchived')],
    'the way back is not offered on exactly the sessions that are archived',
  );

  // Out of the palette, like every other entry that acts on what was right-clicked: pressed
  // with nothing under the pointer they have no session to name.
  const palette = manifest.contributes.menus.commandPalette as { command: string; when: string }[];
  for (const command of ['arc.archiveSession', 'arc.unarchiveSession']) {
    assert.ok(
      palette.some((m) => m.command === command && m.when === 'false'),
      `${command} is in the command palette, where it has no session to act on`,
    );
  }

  // The hand-off, both halves: a message nothing listens for and a listener nothing sends to
  // look the same from either side.
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  sourceMatch(
    extensionSource,
    /reg\('arc\.archiveSession', \(arg\) => setSessionArchived\(panel, arg, true\)\);/,
    'archiving is registered on something other than the archive hand-off',
  );
  sourceMatch(
    extensionSource,
    /reg\('arc\.unarchiveSession', \(arg\) => setSessionArchived\(panel, arg, false\)\);/,
    'the way back is registered on something other than the archive hand-off',
  );
  sourceMatch(
    panelHostSource,
    /public setSessionArchived[\s\S]*this\.updateSessionMembership\(archived \? 'archive' : 'unarchive', session\);/,
    'the archive commands do not update and publish the provider-owned durable set',
  );
  sourceMatch(
    panelHandler('setSessionArchived'),
    /if \(msg\.archived\) sessionState\.hide\(msg\.session\);\s*else sessionState\.unarchive\(msg\.session\);/,
    'the message never reaches the two presses, so the menu entries do nothing',
  );
  // An archive or a pin refreshes both rows' native context in place, so a menu reopened on
  // either surface right after the press already offers the other direction.
  const panelSource = fs.readFileSync(path.join(__dirname, 'webview', 'panel.ts'), 'utf8');
  sourceMatch(
    panelSource,
    /refreshContext: \(session\) => \{\s*timelineRenderer\?\.drawRowContext\(session\);\s*railRenderer\?\.drawRowContext\(session\);\s*\},/,
    'archiving or pinning refreshes only one of the two surfaces, so the other keeps offering the state the press just left',
  );
  const railSource = fs.readFileSync(path.join(__dirname, 'webview', 'rail.ts'), 'utf8');
  sourceMatch(
    railSource,
    /drawRowContext\(session\) \{/,
    'the rail no longer answers a context refresh, so a row can only redraw its menu by waiting for the next full rail message',
  );
});

test('read changes belong to mounted headings without a full timeline refresh', () => {
  const panelSource = fs.readFileSync(path.join(__dirname, 'webview', 'panel.ts'), 'utf8');
  assert.deepEqual(
    callSources(panelSource, 'readState.subscribe'),
    [],
    'a page read subscriber still redraws the timeline',
  );
  const timelineSource = fs.readFileSync(path.join(__dirname, 'webview', 'timeline-renderer.ts'), 'utf8');
  sourceMatch(
    timelineSource,
    /const reconcile = \(\) => \{[\s\S]*?row\.current\.dataset\.vscodeContext = options\.rowContext\(session\.id, session\.row\?\.persisted === true\);[\s\S]*?setRevision[\s\S]*?const unsubscribe = options\.cardOptions\.read\.subscribe\(reconcile\);\s*reconcile\(\);\s*return unsubscribe;/,
    'mounted headings no longer own current native context and remembered Preact props',
  );
});

test('the rail card and the session heading offer Copy session ID beside details, and neither is in the palette', () => {
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
  const copyTitle = manifest.contributes.commands.find(
    (command: { command: string }) => command.command === 'arc.copySessionId',
  );
  assert.deepEqual(copyTitle, {
    command: 'arc.copySessionId',
    title: 'Copy session ID',
    category: 'Arc Session',
  });
  const title = manifest.contributes.commands.find(
    (command: { command: string }) => command.command === 'arc.showSessionDetails',
  );
  assert.deepEqual(title, {
    command: 'arc.showSessionDetails',
    title: 'Show session details',
    category: 'Arc Session',
  });
  const menu = manifest.contributes.menus['webview/context'] as { command: string; when: string; group: string }[];
  const copies = menu.filter((entry) => entry.command === 'arc.copySessionId');
  const details = menu.filter((entry) => entry.command === 'arc.showSessionDetails');
  assert.deepEqual(
    copies.map((entry) => entry.when),
    [
      `webviewSection == '${SESSION_MENU_SECTIONS.live}' || webviewSection == '${SESSION_MENU_SECTIONS.archived}'`,
      `webviewSection == '${RAIL_MENU_SECTIONS.unread}' || webviewSection == '${RAIL_MENU_SECTIONS.read}' || webviewSection == '${RAIL_MENU_SECTIONS.plain}'`,
    ],
  );
  assert.deepEqual(
    details.map((entry) => entry.when),
    [
      `webviewSection == '${SESSION_MENU_SECTIONS.live}' || webviewSection == '${SESSION_MENU_SECTIONS.archived}'`,
      `webviewSection == '${RAIL_MENU_SECTIONS.unread}' || webviewSection == '${RAIL_MENU_SECTIONS.read}' || webviewSection == '${RAIL_MENU_SECTIONS.plain}'`,
    ],
  );
  // The editor sorts the sections by their group name and draws a rule between them. Copy
  // session ID and details read together in the final group, under both the entries that
  // change the session and the editor's own copy entries under `9_cutcopypaste`.
  const archive = menu.find((entry) => entry.command === 'arc.archiveSession');
  const section = (group: string) => group.split('@')[0];
  assert.ok(
    section(archive!.group) < section(copies[0].group),
    `copy is in ${copies[0].group}, which the editor draws above ${archive?.group}`,
  );
  assert.equal(
    section(copies[0].group),
    section(details[0].group),
    `copy is in ${copies[0].group}, separated from details in ${details[0].group}`,
  );
  assert.ok(
    copies.every((entry) => entry.group === 'z_details@1'),
    'the rail card and the session heading do not draw Copy session ID first in the details group',
  );
  assert.ok(
    copies.every((entry) => entry.group === copies[0].group),
    'the rail card and the session heading draw Copy session ID in different groups',
  );
  assert.ok(
    section(archive!.group) < section(details[0].group),
    `details is in ${details[0].group}, which the editor draws above ${archive?.group}`,
  );
  assert.ok(
    section(details[0].group) > '9_cutcopypaste',
    `details is in ${details[0].group}, which the editor draws over its own copy entries`,
  );
  assert.ok(
    details.every((entry) => entry.group === 'z_details@2'),
    'the rail card and the session heading do not draw Show session details after Copy session ID',
  );
  assert.ok(
    details.every((entry) => entry.group === details[0].group),
    'the rail card and the session heading draw Show session details in different groups',
  );
  const palette = manifest.contributes.menus.commandPalette as { command: string; when: string }[];
  assert.ok(
    palette.some((entry) => entry.command === 'arc.copySessionId' && entry.when === 'false'),
    'Copy session ID is available in the command palette',
  );
  assert.ok(
    palette.some((entry) => entry.command === 'arc.showSessionDetails' && entry.when === 'false'),
    'session details is available in the command palette',
  );
  sourceMatch(
    fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8'),
    /reg\('arc\.copySessionId', \(arg\) => copySessionId\(panel, arg\)\);/,
  );
  sourceMatch(
    fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8'),
    /reg\('arc\.showSessionDetails', \(arg\) => showSessionDetails\(panel, arg\)\);/,
  );
  sourceMatch(script, /vscode\.postMessage\(\{ type: 'armSessionDetails', session \}\);/);
  // The arm also names the control the press landed on, so a rail card for a session the
  // timeline is not showing still has somewhere to send focus back to when the dialog closes.
  sourceMatch(
    script,
    /const row = start\?\.closest<HTMLElement>\('\.sessionrow'\) \|\| start\?\.closest<HTMLElement>\('\.railrow'\);/,
  );
  sourceMatch(script, /const card = row\.querySelector<HTMLElement>\('\.railcard'\);/);
  sourceMatch(hostHandler('armSessionDetails'), /browserSession: browserSession \?\? msg\.session/);
  sourceMatch(
    panelHostSource,
    /void this\.sendToHost\(arm\.host, \{ type: 'showSessionDetails', session: arm\.browserSession \}\);/,
  );
  sourceMatch(
    panelHandler('showSessionDetails'),
    /sessionDetails\.openById\(composerRenderer\.sessionIdentity\(msg\.session\), anchor\);/,
  );
});

test('the context menu and Session details dispatch the exact session ID to the clipboard', async () => {
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  const functionSource = (start: string, next: string): string => {
    const from = extensionSource.indexOf(start);
    const end = extensionSource.indexOf(next, from);
    assert.ok(from >= 0 && end > from, `${start} no longer has a body this guard can run`);
    return extensionSource.slice(from, end);
  };
  const registration = /^\s*reg\('arc\.copySessionId'.*$/m.exec(extensionSource)?.[0];
  assert.ok(registration, 'the native Copy session ID command is not registered');
  const compiled = esbuild.transformSync(
    `
    ${functionSource('function sessionIdFrom(', 'function setSessionRead(')}
    ${functionSource('function copySessionId(', 'function showSessionDetails(')}
    export function wire(reg: (id: string, fn: (arg: unknown) => void) => void, panel: PanelProvider): void {
      ${registration}
    }
  `,
    { loader: 'ts', format: 'cjs', target: 'node18' },
  ).code;
  const commandModule = {
    exports: {} as {
      wire: (reg: (id: string, fn: (arg: unknown) => void) => void, panel: PanelProviderType) => void;
    },
  };
  new Function('module', 'exports', compiled)(commandModule, commandModule.exports);

  const copied: string[] = [];
  const stubEnv = vscode.env as unknown as Record<string, unknown>;
  const stubWindow = vscode.window as unknown as Record<string, unknown>;
  const priorClipboard = stubEnv.clipboard;
  const priorStatus = stubWindow.setStatusBarMessage;
  stubEnv.clipboard = {
    async writeText(text: string) {
      copied.push(text);
    },
  };
  stubWindow.setStatusBarMessage = () => ({ dispose() {} });
  const provider = Object.create(PanelProvider.prototype) as PanelProviderType;
  try {
    const commands = new Map<string, (arg: unknown) => void>();
    commandModule.exports.wire((id, fn) => commands.set(id, fn), provider);
    const menuCopy = commands.get('arc.copySessionId');
    assert.ok(menuCopy, 'the registered Copy session ID command has no dispatcher');
    menuCopy({ session: 'context-menu:Exact/42' });

    const copyMessage = new Function(
      `return async function copyMessage(msg) {${handlerBody(panelHostSource, 'copy')}\n}`,
    )() as (this: PanelProviderType, msg: { type: 'copy'; text: string }) => Promise<void>;
    await copyMessage.call(provider, { type: 'copy', text: 'details:Exact/43' });
  } finally {
    if (priorClipboard === undefined) {
      delete stubEnv.clipboard;
    } else {
      stubEnv.clipboard = priorClipboard;
    }
    if (priorStatus === undefined) {
      delete stubWindow.setStatusBarMessage;
    } else {
      stubWindow.setStatusBarMessage = priorStatus;
    }
  }
  assert.deepEqual(
    copied,
    ['context-menu:Exact/42', 'details:Exact/43'],
    'one of the two session ID copy routes did not reach the clipboard unchanged',
  );
});

