test('the Composer context command returns only to its menu host', () => {
  const from = panelHostSource.indexOf('public setComposerHidden(hidden: boolean): void {');
  assert.notEqual(from, -1, 'the provider no longer exposes the Composer visibility command');
  const rest = memberFrom(panelHostSource, from);
  const end = rest.lastIndexOf('}');
  assert.notEqual(end, -1, 'the Composer visibility command no longer has a readable body');
  const body = rest.slice(rest.indexOf('{') + 1, end);
  const setComposerHidden = new Function(`return function setComposerHidden(hidden) {${body}\n}`)() as (
    this: {
      composerMenuArm: { host: object; at: number } | null;
      hosts: object[];
      sendToHost: (host: object, message: unknown) => void;
    },
    hidden: boolean,
  ) => void;
  const firstPanel = {};
  const secondPanel = {};
  const sent: Array<{ host: object; message: unknown }> = [];
  const provider = {
    composerMenuArm: { host: firstPanel, at: Date.now() },
    hosts: [firstPanel, secondPanel],
    sendToHost(host: object, message: unknown) {
      sent.push({ host, message });
    },
  };

  setComposerHidden.call(provider, true);
  assert.deepEqual(
    sent,
    [{ host: firstPanel, message: { type: 'setComposerHidden', hidden: true } }],
    'the Composer command broadcasts to every panel instead of returning to its menu host',
  );

  provider.composerMenuArm = { host: firstPanel, at: Date.now() - 30_001 };
  setComposerHidden.call(provider, false);
  assert.equal(sent.length, 1, 'an expired Composer menu arm changes a panel after its native menu has closed');
});

test('session details returns only to the panel that opened its native menu', () => {
  const from = panelHostSource.indexOf('public showSessionDetails(session: string): void {');
  assert.notEqual(from, -1, 'the provider no longer exposes the native details command');
  const rest = memberFrom(panelHostSource, from);
  const end = rest.lastIndexOf('}');
  assert.notEqual(end, -1, 'the native details command no longer has a readable body');
  const body = rest.slice(rest.indexOf('{') + 1, end);
  const showSessionDetails = new Function(`return function showSessionDetails(session) {${body}\n}`)() as (
    this: {
      detailsMenuArm: { host: object; session: string; browserSession: string; at: number } | null;
      hosts: object[];
      sendToHost: (host: object, message: unknown) => void;
      post: (message: unknown) => void;
    },
    session: string,
  ) => void;
  const firstPanel = {};
  const secondPanel = {};
  const sent: Array<{ host: object; message: unknown }> = [];
  const provider = {
    detailsMenuArm: { host: firstPanel, session: 's1', browserSession: 's1', at: Date.now() },
    hosts: [firstPanel, secondPanel],
    sendToHost(host: object, message: unknown) {
      sent.push({ host, message });
    },
    post(message: unknown) {
      for (const host of this.hosts) {
        this.sendToHost(host, message);
      }
    },
    panelSession(session: string) {
      return session;
    },
  };

  showSessionDetails.call(provider, 's1');
  assert.deepEqual(
    sent,
    [{ host: firstPanel, message: { type: 'showSessionDetails', session: 's1' } }],
    'the command broadcasts the dialog to every panel instead of returning to its menu host',
  );

  provider.detailsMenuArm = {
    host: firstPanel,
    session: 's1',
    browserSession: 's1',
    at: Date.now() - 30_001,
  };
  showSessionDetails.call(provider, 's1');
  assert.equal(sent.length, 1, 'an expired native-menu arm opens a stale dialog instead of being discarded');
});

test('the rail card and the session heading both offer pinning, and none of it in the palette', () => {
  const manifest = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'package.json'), 'utf8'));
  const titles = new Map<string, string>(
    manifest.contributes.commands.map((c: { command: string; title: string }) => [c.command, c.title]),
  );
  // Short words for the menu, deliberately apart from CARD_ACTIONS.railPin and railUnpin: those
  // name the rail card's own pin button in a full sentence an accessible name reads well, and
  // this menu entry is scanned rather than read aloud, so it keeps the short form the rest of
  // the menu uses. Both are withheld from the command palette below, so this is the only place
  // either title is drawn.
  assert.equal(titles.get('arc.pinSession'), 'Pin to top');
  assert.equal(titles.get('arc.unpinSession'), 'Unpin');
  // Both carry a category the way the menu's other short titles do, naming the session
  // rather than the whole extension so it also tells this pair apart from nothing else, since
  // no turn command shares either title.
  const categories = new Map<string, string | undefined>(
    manifest.contributes.commands.map((c: { command: string; category?: string }) => [c.command, c.category]),
  );
  assert.equal(categories.get('arc.pinSession'), 'Arc Session');
  assert.equal(categories.get('arc.unpinSession'), 'Arc Session');

  const menu = manifest.contributes.menus['webview/context'] as { command: string; when: string; group: string }[];
  const whenOf = (command: string) => menu.filter((m) => m.command === command).map((m) => m.when);
  // Composed from the table rather than written out. Nothing typechecks a when clause, and a
  // clause naming a section nothing writes matches no row at all: the entry then never
  // appears, silently, and a one-character difference on either side is enough. A pinned or
  // archived session is either one or the other, so the rail's entry also excludes archived,
  // the state its own three sections do not name.
  const S = SESSION_MENU_SECTIONS;
  const R = RAIL_MENU_SECTIONS;
  const onRail = (suffix: string) =>
    `(webviewSection == '${R.unread}' || webviewSection == '${R.read}' || webviewSection == '${R.plain}') && ${suffix}`;
  assert.deepEqual(
    whenOf('arc.pinSession'),
    [`webviewSection == '${S.live}' && !sessionPinned`, onRail('!sessionPinned && !sessionArchived')],
    'pinning is not offered on exactly the live sessions that are not already pinned',
  );
  assert.deepEqual(
    whenOf('arc.unpinSession'),
    [`webviewSection == '${S.live}' && sessionPinned`, onRail('sessionPinned && !sessionArchived')],
    'the way back is not offered on exactly the live sessions that are pinned',
  );

  // Out of the palette, like every other entry that acts on what was right-clicked: pressed
  // with nothing under the pointer they have no session to name.
  const palette = manifest.contributes.menus.commandPalette as { command: string; when: string }[];
  for (const command of ['arc.pinSession', 'arc.unpinSession']) {
    assert.ok(
      palette.some((m) => m.command === command && m.when === 'false'),
      `${command} is in the command palette, where it has no session to act on`,
    );
  }

  // The hand-off, both halves: a message nothing listens for and a listener nothing sends to
  // look the same from either side.
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  sourceMatch(
    extensionSource,
    /reg\('arc\.pinSession', \(arg\) => setSessionPinned\(panel, arg, true\)\);/,
    'pinning is registered on something other than the pin hand-off',
  );
  sourceMatch(
    extensionSource,
    /reg\('arc\.unpinSession', \(arg\) => setSessionPinned\(panel, arg, false\)\);/,
    'the way back is registered on something other than the pin hand-off',
  );
  sourceMatch(
    panelHostSource,
    /const target = this\.panelSession\(session\);[\s\S]*this\.saved\.pinnedTop = \[\.\.\.this\.pinnedTop\];[\s\S]*this\.refresh\(true\);/,
    'the pin commands do not update and publish the provider-owned durable set',
  );
  sourceMatch(
    panelHandler('setSessionPinned'),
    /sessionState\.setPinned\(msg\.session, msg\.pinned\);/,
    'the message never reaches the press that holds the pinned set, so the menu entries do nothing',
  );
});

test('nothing the panel opens is left to land wherever focus happens to be', () => {
  // Every way a file reaches the editor names its group. Left to the default it opens wherever
  // focus is, and once the panel is an editor tab of its own that is the panel's own
  // group: the reader's editor splits in two and the file lands where the panel was. This is a
  // sweep rather than a list, so a sixth way added later cannot slip in untouched.
  const extensionSource = fs.readFileSync(path.join(__dirname, 'extension.ts'), 'utf8');
  // Each opener is read as the whole call that holds it, so the group must be one of its
  // arguments.
  const opens = [panelHostSource, extensionSource].flatMap((source) =>
    [...source.matchAll(/showTextDocument\(|'vscode\.open'|'vscode\.diff'/g)].map(
      (m) =>
        sourceNodes(source, (node) => ts.isCallExpression(node) && node.getStart() <= m.index && m.index < node.end).at(
          -1,
        ) ?? '',
    ),
  );
  assert.ok(opens.length >= 4, `only ${opens.length} ways of opening a file were found, so this guard has gone blind`);
  for (const call of opens) {
    sourceMatch(
      call,
      /viewColumn/,
      `something opens a file without naming a group, so it can split the reader editor:\n${call.slice(0, 160)}`,
    );
  }
  // `vscode.changes` is the one that cannot be told, so it focuses the group first instead.
  for (const source of [panelHostSource, extensionSource]) {
    if (!source.includes("'vscode.changes'")) {
      continue;
    }
    sourceMatch(
      source,
      /FOCUS_GROUP\[/,
      'a multi-file diff is opened without focusing the group it should land in first',
    );
  }
  // And a link out of a summary takes the same rule as everything else.
  sourceMatch(
    hostHandler('openLink'),
    /await openLink\(msg\.href, msg\.beside \? vscode\.ViewColumn\.Beside : this\.column\(\)\)/,
    'a link in a summary opens without naming a group',
  );
});

test('a ctrl-opened turn diff reuses the group the last press split off', () => {
  // vscode.changes cannot be told a column, so the beside press splits a group off, and
  // splitting on every press opened a new group per ctrl-click. The rule saying when the
  // remembered column still answers is besideColumn in turnview.ts, where it is tested;
  // this holds the untested glue to asking it and to remembering where the split landed.
  sourceMatch(
    panelHostSource,
    /const reuse = besideColumn\(\{/,
    'the beside press never asks besideColumn what to reuse, so every press splits again',
  );
  sourceMatch(
    panelHostSource,
    /this\.lastBeside = vscode\.window\.tabGroups\.activeTabGroup\.viewColumn(?: as number)?;/,
    'where the split landed is never remembered, so there is nothing to reuse',
  );
});

test('a turn diff never opens an empty pair for a file the shell record could not detail', () => {
  // A row with countsUnknown carries no edits and, ordinarily, no snapshot baseline either, so
  // sidesFor would hand it two empty strings and the diff would draw the row with nothing
  // in it. Decision 2 says such a row has no diff to open, so the loop drops it before it
  // ever reaches sidesFor or the resource list.
  const body = methodBody('private async openTurnDiff(');
  sourceMatch(
    body,
    /for \(const file of turn\.files\) \{\s*\/\/[^\n]*\s*\/\/[^\n]*\s*if \(file\.countsUnknown\) \{\s*continue;\s*\}/,
    'a shell-named file with no hunks still reaches vscode.changes as an empty diff',
  );
});

test('every function called in the panel is declared there or imported into its browser graph', () => {
  // The guard this file most needed and did not have. `withWhere` was imported from turnview.ts
  // and called inside SCRIPT, where that import does not reach: the import lands in the
  // extension host bundle and the webview is a separate script. The control that called it threw
  // on every use and shipped that way, because the assertion written for it matched the *text*
  // of a call to a function that did not exist.
  //
  // This is the shape of that mistake, so this is what is checked: a name imported into
  // panelhost.ts and called in SCRIPT has to be declared in SCRIPT or interpolated into it.
  const imports = /import \{([^}]*)\} from '\.\/turnview';/.exec(panelHostSource);
  assert.ok(imports, 'panelhost.ts no longer imports from turnview.ts, so this guard is blind');
  const named = imports[1]
    .split(',')
    .map((n) => n.trim())
    .filter(Boolean);
  assert.ok(named.length > 10, `only ${named.length} imports found, so this guard is not seeing them`);

  const declared = new Set([
    ...[...script.matchAll(/function\s+([A-Za-z_$][\w$]*)\s*\(/g)].map((m) => m[1]),
    ...[...script.matchAll(/(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=/g)].map((m) => m[1]),
    ...[...script.matchAll(/import\s+\{([\s\S]*?)\}\s+from/g)].flatMap((match) =>
      match[1]
        .split(',')
        .map(
          (part) =>
            part
              .trim()
              .split(/\s+as\s+/)
              .pop() ?? '',
        )
        .filter(Boolean),
    ),
  ]);
  const unreachable = named.filter((name) => {
    // Called as a function somewhere in the panel, and not something the panel has of its own.
    const calls = new RegExp(`(?:^|[^.\\w$])${name}\\s*\\(`).test(script);
    return calls && !declared.has(name);
  });
  assert.deepEqual(
    unreachable,
    [],
    `the panel calls ${unreachable.join(', ')}, which is neither declared nor imported in the browser graph`,
  );
});

test('the heading, rail card and View menu label chips are drawn by one rule', () => {
  // Two rules drift: one grows a border, a radius or a tone the other does not, and the reader
  // has to read the words to see that the two lines say the same thing.
  const shared = styleRule('.raillabel, .sessionlabel, .railfilterlabel');
  assert.match(
    shared,
    /border: 1px solid var\(--edge\)/,
    'the outlined chip lost the outline that tells it from the filled figures above it',
  );
  assert.match(
    shared,
    /text-overflow: ellipsis/,
    'a chip no longer cuts itself, so a long label paints over what is beside it',
  );
  assert.equal(
    styleRules().some((rule) => rule.selector === '.sessionlabel'),
    false,
    'the heading chip has a rule of its own, so it and the rail card chip can be drawn differently',
  );
  assert.equal(
    styleRules().some((rule) => /^\.railfilterlabel(:[a-z-]+)?$/.test(rule.selector)),
    false,
    'the View menu chip has a rule of its own, so it and the rail card chip can be drawn differently',
  );
  // The heading's line wraps where the card's refuses to, which is the whole of what it has
  // that the card does not.
  assert.match(
    styleRule('.sessionlabels'),
    /flex-wrap: wrap/,
    'the heading line holds every label on one row, so a filed session runs its chips off the panel',
  );
});

// The list under the filter box, run rather than scanned: which presses it takes, and which
// word a dismissal belongs to.
//
// A flag held against the whole box and a dismissal held against one word read the same to
// every text scan, and they differ only once the caret moves. `label:perf label:co` is two
// words the list has something to say about, and Escape on the first says nothing about the
// second.

// The pattern the filter box claims, and the hover every offered name carries.
//
// The list is the only way to type a whole label name, so this is the one axis a reader
// working by ear cannot reach without it. A box carrying a combobox's state without a
// combobox's role is announced as a plain text box, and the list and the row under the walk
// are never mentioned.

test('the rail owner imports the shared time projection', () => {
  sourceMatch(railSource, /from '\.\.\/view\/rail[.]ts'/);
  sourceDoesNotMatch(railSource, /function railTimeSlot\(/);
  for (const status of ['done', 'failed', 'interrupted', 'running', 'waiting', 'stopped', null] as const) {
    for (const unsent of [false, true]) {
      assert.ok(railTimeSlot(status, unsent));
    }
  }
  assert.deepEqual(railTimeSlot('running', false), { word: 'running', time: false });
  assert.deepEqual(railTimeSlot('waiting', true), { word: 'needs input', time: false });
  assert.deepEqual(railTimeSlot('failed', false), { word: 'failed', time: true });
  assert.deepEqual(railTimeSlot('done', true), { word: null, time: false });
  assert.deepEqual(railTimeSlot(null, false), { word: null, time: true });
});

test('the shared rail projection groups sessions by day', () => {
  sourceDoesNotMatch(script, /function railBuckets\(/);
  // Mid-afternoon, so yesterday and the week boundary are whole days away from it rather
  // than a few hours.
  const now = new Date(2026, 7, 27, 15, 30).getTime();
  const at = (days: number, hour = 12) => new Date(2026, 7, 27 - days, hour).getTime();
  const card = (id: string, days: number, over: object = {}) => ({
    id,
    at: at(days),
    pinnedTop: false,
    current: false,
    archived: false,
    ...over,
  });
  const ids = (cards: { id: string }[]) => cards.map((c) => c.id);
  for (const buckets of [railBuckets]) {
    const full = buckets(
      [
        card('pin', 40, { pinnedTop: true }),
        card('now', 0),
        card('early', 0, {}),
        card('yest', 1),
        card('week', 5),
        card('old', 30),
      ],
      now,
    );
    assert.deepEqual(
      full.buckets.map((b) => [b.id, b.label, ids(b.cards)]),
      [
        ['top', 'Pinned', ['pin']],
        ['today', 'Today', ['now', 'early']],
        ['yesterday', 'Yesterday', ['yest']],
        ['week', 'Last 7 days', ['week']],
        ['older', 'Older', ['old']],
      ],
    );
    // A bucket holding nothing is left out entirely rather than drawn as an empty heading.
    assert.deepEqual(
      buckets([card('a', 0), card('b', 0)], now).buckets.map((b) => b.id),
      ['today'],
    );
    assert.deepEqual(buckets([], now).buckets, []);
    // The boundaries, walked as calendar days: midnight this morning starts today, and a
    // minute before it is yesterday; seven days back is still the week, and the day
    // before that is older.
    const edges = buckets(
      [
        card('a', 0, { at: new Date(2026, 7, 27, 0, 0).getTime() }),
        card('b', 0, { at: new Date(2026, 7, 26, 23, 59).getTime() }),
        card('c', 0, { at: new Date(2026, 7, 25, 23, 59).getTime() }),
        card('d', 0, { at: new Date(2026, 7, 20, 0, 0).getTime() }),
        card('e', 0, { at: new Date(2026, 7, 19, 23, 59).getTime() }),
      ],
      now,
    );
    assert.deepEqual(
      edges.buckets.map((b) => [b.id, ids(b.cards)]),
      [
        ['today', ['a']],
        ['yesterday', ['b']],
        ['week', ['c', 'd']],
        ['older', ['e']],
      ],
    );
    // Folded by default, and two things stand the fold down: the session on screen
    // must stay visible in the chooser pointing at it, and a reader back after days away
    // must not open to a nearly empty rail.
    assert.equal(buckets([card('a', 0), card('b', 0), card('c', 30)], now).olderFolded, true);
    assert.equal(buckets([card('a', 0), card('b', 0), card('c', 30, { current: true })], now).olderFolded, false);
    assert.equal(buckets([card('a', 0), card('b', 30), card('c', 40)], now).olderFolded, false);
    assert.equal(buckets([card('a', 0), card('b', 0)], now).olderFolded, false);
    assert.equal(buckets([], now).olderFolded, false);
    // The runs another agent started leave the days entirely, whatever day they ran on,
    // and sit between the older ones and the archive. The reader did not put them away, so
    // they are not archived; they are not one of the reader's days either.
    const runs = buckets(
      [
        card('mine', 0),
        card('yesterday-mine', 1),
        card('run', 0, { agentRun: true }),
        card('old-run', 30, { agentRun: true }),
        card('old', 30),
        card('gone', 0, { archived: true }),
      ],
      now,
    );
    assert.deepEqual(
      runs.buckets.map((b) => [b.id, b.label, ids(b.cards)]),
      [
        ['today', 'Today', ['mine']],
        ['yesterday', 'Yesterday', ['yesterday-mine']],
        ['older', 'Older', ['old']],
        ['agent', 'Run by agents', ['run', 'old-run']],
        ['archived', 'Archived', ['gone']],
      ],
    );
    // Both of the reader's own words outrank the guess. An archived run stays archived,
    // and a pinned one keeps the top it was pinned to.
    const beaten = buckets(
      [
        card('a', 0),
        card('b', 0),
        card('put-away', 0, { agentRun: true, archived: true }),
        card('kept-up', 0, { agentRun: true, pinnedTop: true }),
      ],
      now,
    );
    assert.deepEqual(
      beaten.buckets.map((b) => [b.id, ids(b.cards)]),
      [
        ['top', ['kept-up']],
        ['today', ['a', 'b']],
        ['archived', ['put-away']],
      ],
    );
    // Folded by the same two rules the older ones take: the session on screen stays
    // visible in the chooser pointing at it, and a rail that is nearly all runs does not
    // fold itself down to nothing.
    assert.equal(buckets([card('a', 0), card('b', 0), card('r', 0, { agentRun: true })], now).agentFolded, true);
    assert.equal(
      buckets([card('a', 0), card('b', 0), card('r', 0, { agentRun: true, current: true })], now).agentFolded,
      false,
    );
    assert.equal(
      buckets([card('a', 0), card('r', 0, { agentRun: true }), card('s', 0, { agentRun: true })], now).agentFolded,
      false,
    );
    assert.equal(buckets([card('a', 0), card('b', 0)], now).agentFolded, false);
    assert.equal(buckets([], now).agentFolded, false);
    // The two folds are counted together, because what is left on screen is what both of
    // them left. Two old ones and two runs behind their own headings is a rail of one.
    assert.equal(
      buckets([card('a', 0), card('o', 30), card('p', 30), card('r', 0, { agentRun: true })], now).olderFolded,
      false,
    );
  }
});

test('every message in the Activity log accepts a comment mark, not only a reply', () => {
  const said = '.actrow.message[data-message]';
  const node = (...matches: string[]) =>
    ({
      closest: (selector: string) => (matches.includes(selector) ? { dataset: { message: 'commentary:1:0' } } : null),
    }) as unknown as Element;
  const row = (message: string) =>
    ({
      closest: (selector: string) =>
        selector === '.actlist' ? {} : selector === said ? { dataset: { message } } : null,
    }) as unknown as Element;
  // A run or a step carries no name a comment can be saved under, so it takes no mark.
  assert.equal(outsideCommentMarks(node('.actlist')), true);
  assert.equal(outsideCommentMarks(node('.actlist', '.answer')), false);
  assert.equal(outsideCommentMarks(node('.actlist', said)), false);
  assert.equal(outsideCommentMarks(node('.actlist', '.answer', said)), false);
  assert.equal(outsideCommentMarks(node(said)), false);
  assert.equal(outsideCommentMarks(node()), false);
  assert.equal(outsideCommentMarks(null), false);
  // A message whose id no saved comment keeps takes no comment. An empty id would save the
  // comment on the final response, and a longer or spaced id would move it there on reload.
  assert.equal(outsideCommentMarks(row('')), true);
  assert.equal(outsideCommentMarks(row('x'.repeat(201))), true);
  assert.equal(outsideCommentMarks(row('commentary 1')), true);
  assert.equal(outsideCommentMarks(row('x'.repeat(200))), false);
});

test('the panel dates a session by what it recorded, not by its file being touched', () => {
  // An agent appends bookkeeping to a transcript after the session has stopped: a
  // title, a mode, a snapshot of file history, the records written as a session is closed.
  // Every one of them moves the file's mtime, and reading that as the activity sent a
  // session nobody had touched back to the top of the rail, into the Today bucket,
  // reading `just now`. `readSessionActivity` in transcript.ts is the rule
  // and is tested there; what is checked here is that the host asks it.
  sourceMatch(
    panelHostSource,
    /private activityFor\(session: SessionFile\): number \{/,
    'panelhost.ts no longer has an activityFor, so nothing asks what a session recorded',
  );
  sourceMatch(
    panelHostSource,
    /return this\.metaFor\(session\)\.activityMs \?\? session\.mtimeMs;/,
    'activityFor no longer prefers the recorded time, or no longer falls back to the mtime',
  );
  // Both answers off one read, kept against the mtime, which is still the right question
  // about whether the file has changed at all.
  sourceMatch(
    panelHostSource,
    /private titles = new Map<string, DerivedTitleEntry>\(\);/,
    'the per-file cache no longer carries the derived rail facts beside the label, keyed on the file revision',
  );
  sourceMatch(
    panelHostSource,
    /sameSessionRevision\(hit, session\)/,
    'a session that grew while its timestamp stayed fixed reuses stale title and activity metadata',
  );
  const workerEntry = fs.readFileSync(path.join(__dirname, 'progressiveworker-entry.ts'), 'utf8');
  sourceMatch(
    workerEntry,
    /readSessionMeta\(session\.file, tailBytes, session\.sessionId, session\.childTranscript === true\)/,
    'the worker no longer obtains Claude rail facts from one bounded metadata tail',
  );
  sourceMatch(
    workerEntry,
    /readCodexSessionActivity\(session\.file, tailBytes, \{ sessionId: session\.sessionId, meta: request\.opening \?\? null \}\)/,
    'the worker no longer obtains Codex rail facts from one bounded metadata tail',
  );
  sourceMatch(
    panelHostSource,
    /sessionStatusOf\(\s*\[\], this\.runningSessions\(\), this\.sessionOutcomes, now, this\.waitingSessions\(\),\s*this\.runningSince\(\), openChildren, this\.liveBackgroundCommands\(now\),?\s*\)/,
    'the rail reads selected cards before their progressive result is accepted',
  );

  // The three values the session heading and the ticker draw.
  const from = panelHostSource.indexOf('this.sessionRows = all.map(');
  assert.notEqual(from, -1, 'panelhost.ts no longer builds sessionRows from the listing');
  const rows = statementFrom(panelHostSource, from);
  sourceMatch(rows, /const at = this\.activityFor\(f\);/, 'a session row no longer takes the recorded activity time');
  for (const field of ['when: formatWhen(at)', 'at,', 'relative: formatRelative(at)']) {
    assert.ok(rows.includes(field), `the session row's \`${field}\` no longer comes from the recorded activity time`);
  }
  sourceDoesNotMatch(
    rows,
    /f\.mtimeMs/,
    'a session row dates itself by the file mtime again, which a closed session moves',
  );

  // And the activity order the picker and read cut use directly, and the rail starts from.
  const merge = panelHostSource.indexOf('const listed = claude.filter');
  assert.notEqual(merge, -1, 'allSessions no longer merges the two listings, so this guard cannot see its order');
  const merged = memberFrom(panelHostSource, merge);
  sourceMatch(
    merged,
    /orderSessionCatalog\([\s\S]*this\.activityFor\(session\)\)/,
    'the merged listing is ordered by something other than the recorded activity time',
  );
});

test('initial session listing keeps every metadata read within 64 MiB before the first rail', () => {
  // The affected workspace held 226 Claude sessions with prompts. A synchronous
  // full-history title scan stalled the extension host before the panel could load. This
  // guard measures bytes from the fixed tail window instead of timing a particular machine.
  const eligibleClaudeSessions = 226;
  const maximumAggregateBytes = 64 * 1024 * 1024;
  const claudeMetadataBytes = 256 * 1024;
  const codexMetadataBytes = 256 * 1024 + 1024 * 1024;

  const listingAt = panelHostSource.indexOf('private allSessions(reuseCatalog = false): SessionFile[] {');
  assert.notEqual(listingAt, -1, 'panelhost.ts no longer contains the initial session listing');
  const listing = memberFrom(panelHostSource, listingAt);
  sourceMatch(
    listing,
    /this\.activityFor\(/,
    'the initial session listing no longer reaches metadata through activityFor',
  );

  const activityAt = panelHostSource.indexOf('private activityFor(session: SessionFile): number {');
  assert.notEqual(activityAt, -1, 'panelhost.ts no longer contains activityFor');
  const activity = memberFrom(panelHostSource, activityAt);
  sourceMatch(activity, /this\.metaFor\(session\)/, 'activityFor no longer reaches the shared metadata reader');

  const workerEntry = fs.readFileSync(path.join(__dirname, 'progressiveworker-entry.ts'), 'utf8');
  const metadataAt = workerEntry.indexOf("if (request.kind === 'metadata')");
  assert.notEqual(metadataAt, -1, 'the worker no longer has a metadata request branch');
  const metadataEnd = layoutIndexOf(workerEntry, 'const { session, folders', metadataAt);
  assert.notEqual(metadataEnd, -1, 'the worker metadata branch no longer ends where this guard expects');
  const metadata = workerEntry.slice(metadataAt, metadataEnd);
  sourceMatch(
    metadata,
    /const tailBytes = request\.tailBytes \?\? 256 \* 1024;/,
    'the first worker metadata tail is no longer fixed at 256 KiB',
  );
  sourceMatch(
    metadata,
    /readSessionMeta\(session\.file, tailBytes, session\.sessionId, session\.childTranscript === true\)/,
    'the worker Claude metadata read does not honor its bounded tail',
  );
  sourceMatch(
    metadata,
    /readCodexSessionActivity\(session\.file, tailBytes,/,
    'the worker Codex metadata read does not honor its bounded tail',
  );
  sourceMatch(
    metadata,
    /readCodexSessionTitlePair\(session\.file\)/,
    'the worker no longer charges the bounded Codex title head as catalog metadata',
  );
  sourceDoesNotMatch(
    metadata,
    /read(?:Codex)?TurnStarts/,
    'a 16 MiB turn-start scan returned to the path before the first rail',
  );

  const progressiveWorkerSource = fs.readFileSync(path.join(__dirname, 'progressiveworker.ts'), 'utf8');
  sourceMatch(
    progressiveWorkerSource,
    /export const INITIAL_RAIL_READ_BYTES = 64 \* 1024 \* 1024;/,
    'the first rail no longer has a fixed 64 MiB metadata budget',
  );
  sourceMatch(
    progressiveWorkerSource,
    /tailBytes = 256 \* 1024\): number \{\s*return \(\s*Math\.min\(session\.size, tailBytes\) \+\s*\(session\.agent === 'codex' \? Math\.min\(session\.size, CODEX_TITLE_BYTES\) : 0\) \+\s*\(session\.agent === 'claude' && session\.size > tailBytes \? SESSION_HEAD_BYTES : 0\)\s*\);/,
    'the metadata budget no longer includes the bounded activity tail, the Codex title head, and the Claude prompt head',
  );

  const metadataPreparationAt = panelHostSource.indexOf('private async prepareMetadata(');
  const metadataPreparation = memberFrom(panelHostSource, metadataPreparationAt);
  assert.notEqual(metadataPreparationAt, -1, 'panelhost.ts no longer prepares metadata before rendering the rail');
  sourceMatch(
    metadataPreparation,
    /let remaining = INITIAL_RAIL_READ_BYTES;[\s\S]*const bytes = metadataReadBudget\(session\);[\s\S]*if \(bytes > remaining\) \{ break; \}[\s\S]*remaining -= bytes;[\s\S]*kind: 'metadata'/,
    'metadata reads can exceed the first-rail budget',
  );

  const startsAt = workerEntry.indexOf("if (request.kind === 'starts')");
  const starts = workerEntry.slice(startsAt, metadataAt);
  sourceMatch(
    starts,
    /readSessionTurnStarts\(request\.session\.file(?:, undefined, request\.session\.childTranscript === true)?\)/,
    'Claude turn starts no longer use their deferred worker request',
  );
  sourceMatch(
    starts,
    /readCodexTurnStarts\(request\.session\.file\)/,
    'Codex turn starts no longer use their deferred worker request',
  );
  sourceMatch(
    workerEntry,
    /const kept = stable \? undefined : scanKeptThroughGrowth\(value, before, after\);[\s\S]*kept \? \{ kind: 'stale', agentRunScan: kept,/,
    'a stale worker read drops the agent-run scan progress of a transcript that only grew',
  );
  const enrichmentAt = panelHostSource.indexOf('private async prepareRailEnrichment(');
  const enrichment = memberFrom(panelHostSource, enrichmentAt);
  assert.notEqual(enrichmentAt, -1, 'panelhost.ts no longer defers turn-start enrichment until after the first rail');
  sourceMatch(
    enrichment,
    /let remaining = INITIAL_RAIL_READ_BYTES;[\s\S]*const bytes = [\s\S]*RAIL_ENRICHMENT_READ_BYTES[\s\S]*agentRunScanUnread\(session, previous\.agentRunScan\)[\s\S]*if \(bytes > remaining && remaining < INITIAL_RAIL_READ_BYTES\) \{ break; \}[\s\S]*remaining -= bytes;[\s\S]*kind: 'starts'/,
    'deferred rail enrichment has no bounded admission rule',
  );
  sourceMatch(
    enrichment,
    /kind: 'metadata', session, tailBytes: RAIL_ENRICHMENT_READ_BYTES/,
    'deferred rail enrichment does not retry metadata that found no complete turn',
  );
  sourceMatch(
    enrichment,
    /if \(!acceptsProgressiveResult\([\s\S]*result\.value\.kind === 'stale' && result\.value\.agentRunScan[\s\S]*onlyGrew\(result\.revision, this\.revisionOf\(session\)\)[\s\S]*withAgentRunScanProgress\(current, result\.value\.agentRunScan\)[\s\S]*this\.storeTitleEntry\(session\.file, kept\)/,
    'a stale turn-start result drops the agent-run scan progress of a transcript that only grew',
  );
  const acceptedStartsAt = enrichment.indexOf(
    'next = withRailEnrichment(next, result.value.starts, result.value.agentRunScan);',
  );
  const expandedMetadataAt = layoutIndexOf(
    enrichment,
    "kind: 'metadata', session, tailBytes: RAIL_ENRICHMENT_READ_BYTES",
  );
  const acceptedStarts = enrichment.slice(acceptedStartsAt, expandedMetadataAt);
  assert.ok(
    acceptedStartsAt >= 0 && expandedMetadataAt > acceptedStartsAt,
    'the enrichment sequence no longer accepts starts before expanded metadata',
  );
  sourceMatch(
    acceptedStarts,
    /this\.storeTitleEntry\(session\.file, next\);[\s\S]*this\.derivedCacheCheckpointState\.markChanged\(\);[\s\S]*changed = true;/,
    'accepted turn starts and agent-run progress wait for expanded metadata before entering the cache',
  );
  sourceMatch(
    enrichment,
    /if \(!acceptsProgressiveResult\(result,[\s\S]*catalogCurrent = false;[\s\S]*return \{ changed, catalogCurrent, progress \};/,
    'stale expanded metadata does not request a catalog refresh after retaining safe scan progress',
  );
  sourceMatch(
    enrichment,
    /withMetadataCoverage\(found, result\.value\.coverage\)/,
    'expanded metadata does not record successful coverage independently of drawable stats',
  );

  const readerAt = transcriptSource.indexOf('export function readSessionMeta(');
  assert.notEqual(readerAt, -1, 'transcript.ts no longer contains readSessionMeta');
  const [reader = ''] = sourceNodes(
    transcriptSource,
    (node) =>
      ts.isBlock(node) &&
      node.parent !== undefined &&
      ts.isFunctionDeclaration(node.parent) &&
      node.parent.name?.text === 'readSessionMeta',
  );
  sourceMatch(
    reader,
    /const read = tailOf\(file, bytes\);/,
    'Claude metadata no longer starts from its bounded tail window',
  );
  assert.equal(
    reader.replace('sessionTitleOf(file, read, childTranscript)', '').match(/\bfile\b/g)?.length ?? 0,
    1,
    'Claude metadata passes the transcript file beyond its bounded tail read, which can scan history synchronously',
  );
  sourceMatch(
    transcriptSource,
    /headOf\(file, recorded\.short \? HEAD_KEY_BYTES : SESSION_HEAD_BYTES\)/,
    'Claude metadata reads more of the head than its bounded prompt window',
  );

  // The saved Claude title file is read only to confirm a rename. A read anywhere else can
  // reach the listing path and read one more file per session before the first rail. The
  // file name appears only inside its reader, and the reader has one caller, the rename.
  const uncommented = (text: string) => text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');
  const sources = fs
    .readdirSync(__dirname, { recursive: true, encoding: 'utf8' })
    .filter((file) => /\.ts$/.test(file) && !/\.test\.ts$/.test(file))
    .map((file) => ({
      file: file.replace(/\\/g, '/'),
      text: uncommented(fs.readFileSync(path.join(__dirname, file), 'utf8')),
    }));
  const bodyOf = (text: string, opening: string): string => {
    const start = text.indexOf(opening);
    assert.notEqual(start, -1, `${opening} is missing`);
    return statementFrom(text, start);
  };
  const count = (text: string, pattern: RegExp) => text.match(pattern)?.length ?? 0;
  const sidecarName = /custom-title\.json/g;
  const sidecarReader = /\breadCustomTitleSidecar\b/g;
  assert.deepEqual(
    sources.filter(({ text }) => count(text, sidecarName) > 0).map(({ file }) => file),
    ['transcript.ts'],
    'the saved Claude title file is named outside its reader',
  );
  const transcriptCode = sources.find(({ file }) => file === 'transcript.ts')!.text;
  const sidecarReaderBody = bodyOf(transcriptCode, 'export function readCustomTitleSidecar(');
  assert.equal(
    count(transcriptCode, sidecarName),
    count(sidecarReaderBody, sidecarName),
    'transcript.ts names the saved Claude title file outside readCustomTitleSidecar',
  );
  assert.deepEqual(
    sources
      .filter(({ text }) => count(text, sidecarReader) > 0)
      .map(({ file }) => file)
      .sort(),
    ['agenthost.ts', 'transcript.ts'],
    'the saved Claude title file is read outside the rename confirmation',
  );
  assert.equal(count(transcriptCode, sidecarReader), 1, 'transcript.ts calls readCustomTitleSidecar');
  const hostCode = sources.find(({ file }) => file === 'agenthost.ts')!.text;
  assert.equal(count(hostCode, sidecarReader), 2, 'agenthost.ts reads the saved Claude title file more than once');
  assert.equal(
    count(bodyOf(hostCode, 'export async function renameAgentSession('), sidecarReader),
    1,
    'agenthost.ts reads the saved Claude title file outside renameAgentSession',
  );

  const aggregateBytes = eligibleClaudeSessions * claudeMetadataBytes;
  assert.ok(
    aggregateBytes <= maximumAggregateBytes,
    `${eligibleClaudeSessions} Claude metadata tails read ${aggregateBytes} bytes before the initial panel load, ` +
      `above the ${maximumAggregateBytes}-byte budget`,
  );
  assert.ok(
    codexMetadataBytes > claudeMetadataBytes,
    'the catalog budget no longer accounts for Codex title reads in addition to metadata tails',
  );
});

const USAGE_NOW = new Date(2026, 7, 28, 14, 32, 0).getTime();

// What an agent published for its slash menu, in the shape the wires reduce to. One takes an
// argument and one does not, because the row draws them differently.
const PANEL_COMMANDS = [
  { name: 'commit', description: 'Write a commit for what is in the working tree', argumentHint: '<message>' },
  { name: 'compact', description: 'Summarise the session and keep going', argumentHint: '' },
  { name: 'code-review', description: 'Review the current diff', argumentHint: '[level]' },
  { name: 'polish', description: '', argumentHint: '' },
  // A name that contains what a reader types without starting with it. Without one in here
  // the two groups never both fill, and a copy that returned them the wrong way round would
  // agree with the original on every case this sweeps.
  { name: 'safe-compact', description: 'Save what only the session holds', argumentHint: '' },
];

const COMPOSER_STATE = {
  commands: PANEL_COMMANDS,
  agent: 'claude' as const,
  session: 'Embedded agent input',
  draft: '',
  queued: [],
  history: [],
  onScreen: '',
  running: false,
  comments: [],
  sessionId: 's1',
  models: [
    {
      value: 'opus',
      label: 'Opus 5',
      description: 'Best for everyday work',
      efforts: [{ value: 'high', label: 'high', description: '' }],
    },
  ],
  settings: {
    selectedModel: 'opus',
    selectedEffort: 'high',
    effortModel: 'opus',
    pendingModel: null,
    pendingEffort: null,
    confirmedModel: null,
    confirmedEffort: null,
  },
  askMode: 'auto',
  context: { used: 82_000, max: 200_000 },
  mcpServers: [],
  live: [],
  claudeSkills: null,
};

// The glance spends a budget per refresh, so the rail fills over several polls. A workspace
// where no agent is running produces the same signature for ever, and a refresh that finds
// the signature unchanged gives up before it does anything. So the order of those two decides
// whether the rail ever finishes filling: with the glance after the comparison, the panel
// glanced at one budget on the poll that opened it and every session past that budget
// stayed silent until some transcript happened to move.
test('the glance goes on filling the rail on a refresh where nothing else moved', () => {
  const glance = panelHostSource.indexOf('this.windows = this.glanceAt(all, sessions)');
  assert.notEqual(glance, -1, 'panelhost.ts no longer glances, so this guard cannot see the order');
  const compare = panelHostSource.indexOf('refreshWanted({');
  assert.notEqual(compare, -1, 'panelhost.ts no longer asks refreshWanted, so this guard sees nothing');
  assert.ok(
    glance < compare,
    'the glance runs after the refresh gives up, so a quiet workspace fills one budget and stops',
  );

  // The rule itself is refreshWanted's and is run in turnview.ts. What is checked here is that
  // this file asks it with the sizes either side of the glance, rather than with one of them
  // twice, which would read as a working panel and never repaint.
  sourceMatch(
    panelHostSource,
    /glancedBefore: glanced, glancedNow: this\.windows\.size,/,
    'the refresh asks refreshWanted with the wrong sizes, so a new glance never reaches the rail',
  );

  // And that it asks the clock with both readings rather than with a constant. The rule is
  // statusMoved's and is run in turncard.ts, so a term wired as `false` typechecks, passes
  // every test either file has, and leaves a dead session drawn as running for as long
  // as the panel stays open. Only the call written out here says it is really being asked.
  sourceMatch(
    panelHostSource,
    /const statusFacts = \[[\s\S]*?this\.newestBySession\.values\(\)[\s\S]*?outcomes[\s\S]*?statusMoved: statusMoved\(statusFacts, this\.collectedAt, now\),/,
    'the refresh no longer asks whether a parsed or metadata-only turn stopped running, so a dead session keeps the word',
  );
  sourceMatch(
    panelHostSource,
    /const now = Date\.now\(\);[\s\S]*?this\.collectedAt = now;/,
    'the cards are worded at one clock and compared against another, so the poll repaints for ever or never',
  );

  // Metadata windows are rebuilt by each refresh. The worker owns persistent parse state,
  // so the host must not retain a second per-file glance cache.
  sourceDoesNotMatch(
    panelHostSource,
    /this\.glances/,
    'the host keeps an unused per-file glance cache beside worker-owned progressive state',
  );
  sourceMatch(
    panelHostSource,
    /this\.windows = this\.glanceAt\(all, sessions\);/,
    'the rail loses its refresh-local metadata windows',
  );
});

test('the composer is aimed by the agent key, never by the name the rail draws', () => {
  // A session row carries both spellings: `agent` is what the rail prints, "Claude
  // Code" or "Codex", and `agentKey` is what every table is filed under. Reading the drawn
  // name as a key fails silently and completely. The model list misses, so the picker says
  // it has no models; the ask modes miss, so an unknown agent is lent Claude's four; and the
  // prompt is handed to whichever CLI the name is not equal to, which sent Claude
  // sessions to Codex and answered with "Auto is not a setting Codex can be put in".
  //
  // The type is the real guard, since ComposerState.agent is the two keys and no caller can
  // write a display name. This holds the line the type cannot see: that the row keeps both
  // spellings, and that the composer reads the key.
  const rows = panelHostSource.indexOf('this.sessionRows = all.map');
  assert.notEqual(rows, -1, 'the panel no longer builds its session rows here');
  const built = statementFrom(panelHostSource, rows);
  sourceMatch(built, /agent: AGENT_NAMES\[f\.agent\]/, 'the rail draws something other than the agent name');
  sourceMatch(built, /agentKey: f\.agent/, 'the row carries no key, so everything is filed under a drawn name');

  // `stateForRow` builds it and `composerState` only picks the row, since a queue drains for
  // the session whose turn ended rather than for the one the box is aimed at.
  const at = panelHostSource.indexOf('private stateForRow(');
  assert.notEqual(at, -1, 'the panel no longer builds the composer state here');
  const body = memberFrom(panelHostSource, at);
  sourceDoesNotMatch(
    body,
    /row\.agent\b/,
    'the composer reads the drawn agent name, so its tables miss and its prompts go to the wrong CLI',
  );
  for (const filed of [
    'sessionSettings(this.picks, row.id)',
    'this.models[row.agentKey]',
    'this.askLevels[row.agentKey]',
    'this.codexEffectiveModes?.[row.id]',
    'this.claudeEffectiveModes?.[row.id]',
  ]) {
    assert.ok(body.includes(filed), `${filed} is looked up under something other than the agent key`);
  }
  sourceMatch(body, /agent: row\.agentKey/, 'the composer is handed something other than the agent key');
});

