test('a queued clear removes its attempted record after the session moves', async () => {
  const methods = clearSettlementMethods();
  const flushQueue = extractedFlushQueue();
  const clear = { id: 'clear', text: '/clear', commentIds: [], assets: [], at: 1, attempted: true };
  const followUp = { id: 'follow-up', text: 'continue', commentIds: [], assets: [], at: 2 };
  const delivered: string[] = [];
  const host: Record<string, any> = {
    repositoryScopeReady: true,
    pendingQueueDrains: new Set<string>(),
    clearSettlements: new Map<string, Record<string, any>>(),
    queues: { source: [clear, followUp] },
    queueHandoffs: new Set([clear.id]),
    queuedEditReservations: new Set<string>(),
    attachmentStorageDir: null,
    noteLive() {
      return 1;
    },
    cwdForSession() {
      return 'C:\\ws';
    },
    usagePayload() {
      return {};
    },
    post() {
      return Promise.resolve();
    },
    writeDrafts() {
      return Promise.resolve();
    },
    livePressAnswered() {},
    noteLocalAnswer() {},
    stateFor(session: string) {
      return { sessionId: session, agent: 'codex', running: false, comments: [], queued: this.queues[session] ?? [] };
    },
    send(_state: unknown, _text: string, queued: { id: string }) {
      delivered.push(queued.id);
    },
    flushQueue(session: string) {
      flushQueue.call(this, session);
    },
    finishClearSettlement(settlement: Record<string, any>) {
      methods.finishClearSettlement.call(this, settlement);
    },
    noteSessionMoved(source: string, successor: string) {
      const settlement = this.clearSettlements.get(source);
      this.clearSettlements.delete(source);
      settlement.session = successor;
      this.clearSettlements.set(successor, settlement);
      this.queues = { [successor]: this.queues[source] };
      if (settlement.delivery?.delivered) {
        this.finishClearSettlement(settlement);
      }
    },
    onClear() {
      return Promise.resolve({ delivered: true, reason: '', session: 'successor' });
    },
  };
  methods.startClear.call(host, { agent: 'codex', sessionId: 'source' }, clear);
  await vi.waitFor(() => {
    assert.equal('source' in host.queues, false, 'the source queue returned after its session moved');
    assert.deepEqual(
      host.queues.successor.map((entry: { id: string }) => entry.id),
      [followUp.id],
      'the attempted clear stayed first after the queue moved to its successor and blocked the follow-up',
    );
    assert.deepEqual(
      delivered,
      [followUp.id],
      'the follow-up prompt waited in the successor queue until another event drained it',
    );
  });
});

