test('watcher refreshes and project checkpoints share only the bounded scheduler primitive', () => {
  const constructor = memberFrom(panelHostSource, panelHostSource.indexOf('constructor('));
  const constructorBody = constructor;
  sourceMatch(
    constructorBody,
    /this\.watchScheduler = new BoundedTrailingScheduler\(\s*TRANSCRIPT_WAKE_MS, TRANSCRIPT_WAKE_MAX_MS,/,
    'watcher refreshes do not use the trailing quiet and maximum waits',
  );
  sourceMatch(
    constructorBody,
    /this\.projectSpendSaveScheduler = this\.newProjectSpendSaveScheduler\(\);/,
    'Project cost checkpoints do not use their own scheduler',
  );
  sourceMatch(
    memberFrom(panelHostSource, panelHostSource.indexOf('private newProjectSpendSaveScheduler()')),
    /new BoundedTrailingScheduler\(PROJECT_SPEND_SAVE_MS, PROJECT_SPEND_SAVE_MAX_MS,/,
    'Project cost checkpoints do not use their trailing quiet and maximum waits',
  );
  sourceDoesNotMatch(
    constructorBody,
    /this\.watchScheduler = this\.projectSpendSaveScheduler|this\.projectSpendSaveScheduler = this\.watchScheduler/,
    'watcher and ledger work share pending state instead of only the scheduling rule',
  );

  const schedule = memberFrom(panelHostSource, panelHostSource.indexOf('private scheduleProjectSpendSave()'));
  const scheduleBody = schedule;
  sourceMatch(
    scheduleBody,
    /this\.projectSpendSaveOwed = true;\s*this\.projectSpendSaveScheduler\.offer\(\);/,
    'a ledger change does not restart its trailing quiet period',
  );
  sourceDoesNotMatch(
    scheduleBody,
    /setTimeout/,
    'Project cost keeps a second leading-edge checkpoint timer beside the tested scheduler',
  );

  const workspace = memberFrom(panelHostSource, panelHostSource.indexOf('private ensureProjectSpendWorkspace()'));
  sourceMatch(
    workspace,
    /this\.flushProjectSpendSave\(\);\s*this\.projectSpendSaveOwed = false;/,
    "a workspace change leaves the replaced workspace's checkpoint owed",
  );
  const dispose = memberFrom(panelHostSource, panelHostSource.indexOf('private disposeOwned(): void {'));
  const disposeBody = dispose;
  sourceMatch(
    disposeBody,
    /this\.flushProjectSpendSave\(\)/,
    'provider disposal leaves a scheduled checkpoint pending',
  );

  const runningBody = memberFrom(panelHostSource, panelHostSource.indexOf('public setRunning('));
  sourceMatch(runningBody, /this\.post\(\{ type: 'usage'/, 'running state no longer reaches the composer immediately');
  sourceMatch(
    runningBody,
    /if \(moved\) \{ void this\.refresh\(true\); \}/,
    'running state no longer reaches cards and the rail immediately',
  );
  sourceDoesNotMatch(
    runningBody,
    /watchScheduler|projectSpendSaveScheduler/,
    'extension-owned running state waits on a filesystem or ledger scheduler',
  );
});

