// A Claude transcript at one path, then a different transcript written at the same path. The
// first names itself far into the file and the second names itself near the start, so the
// name of the file that is gone outranks the name of the file that is there.
function replacedClaudeTranscript(): { file: string; replace: () => void } {
  const file = path.join(tempDir('replaced-panel-'), 'named-session.jsonl');
  const prompt = (text: string, uuid: string) => `${JSON.stringify({
    type: 'user',
    uuid,
    sessionId: 'named-session',
    timestamp: '2026-09-18T10:00:00.000Z',
    message: { role: 'user', content: text },
  })}
`;
  fs.writeFileSync(file, prompt('a'.repeat(4000), 'u1') + customTitleRecord('First name'));
  return {
    file,
    // Written beside the transcript and renamed over it, so the replacement holds a file
    // number of its own. A file written after the old one is removed can be given the number
    // the removal freed, which ext4 does for the next file in the directory, and the test
    // would then assert nothing about a replacement it cannot see.
    replace() {
      const written = `${file}.next`;
      fs.writeFileSync(written, prompt('b', 'u2') + customTitleRecord('Second name') + prompt('c'.repeat(8000), 'u3'));
      fs.renameSync(written, file);
    },
  };
}

// The catalog walk lists a session, the transcript grows, and the metadata read that follows
// stats the file for itself. The parse of that same refresh must measure the file too. Given
// the listed size it reports a transcript smaller than the one the metadata read named, which
// reads as a replacement and throws away the name the owner gave the session.
test('a session that only grew between the walk and its metadata read keeps its name through the next parse', () => {
  const file = renamedClaudeTranscript();
  const provider = namedSessionProvider([], { file });
  fs.appendFileSync(
    file,
    `${JSON.stringify({ type: 'ai-title', aiTitle: 'Generated name', sessionId: 'named-session' })}
`,
  );
  provider.readMetadataAfterGrowth();
  assert.deepEqual(provider.drawn(), { rail: 'First name', heading: 'First name' });

  const generated = turn({
    sessionId: 'named-session',
    sessionTitle: 'Generated name',
    sessionTitleSource: 'generated',
    sessionTitleAt: fs.statSync(file).size - 100,
  });
  assert.deepEqual(
    provider.refresh(generated),
    { rail: 'First name', heading: 'First name' },
    'a refresh of a growing session dropped the name the owner gave it',
  );
});

// A search parses a session on its own timer while a metadata read of the same session is in
// flight. The search reads the file as it is now and finds the name the owner gave it. The
// read measured the file before the session grew, and its window found only the first prompt.
// The two reports are of one file, so the earlier measurement arriving last must not read as
// a transcript that shrank and take the higher name with it.
test('a metadata read that measured a session before a search keeps the name the search raised', () => {
  const file = renamedClaudeTranscript();
  const provider = namedSessionProvider([], { file });
  fs.appendFileSync(
    file,
    `${JSON.stringify({
      type: 'user',
      uuid: 'u2',
      sessionId: 'named-session',
      timestamp: '2026-09-18T10:05:00.000Z',
      message: { role: 'user', content: 'x'.repeat(4000) },
    })}\n`,
  );
  const parsed = turn({
    sessionId: 'named-session',
    sessionTitle: 'First name',
    sessionTitleSource: 'custom',
    sessionTitleAt: 100,
  });
  assert.deepEqual(provider.refresh(parsed), { rail: 'First name', heading: 'First name' });

  provider.metadata({ label: 'Fix the login flow', nameSource: 'prompt', nameAt: 0 });
  assert.deepEqual(
    provider.drawn(),
    { rail: 'First name', heading: 'First name' },
    'a read measured before the search read as a replacement and dropped the name the owner gave the session',
  );
  assert.equal(
    provider.titles.get(file)?.label,
    'First name',
    'the stored entry took the lower name, so a restart draws it',
  );
});

// A parse reports before any metadata read, and the transcript at that path is replaced
// before the read arrives. The replacement is larger and its own name sits earlier in it, so
// only the identity of the file the parse read keeps the old name out of the new transcript.
test('a transcript replaced after its turns were parsed takes its own name, and keeps it after a restart', () => {
  const replaced = replacedClaudeTranscript();
  const provider = namedSessionProvider([], { file: replaced.file });
  const parsed = turn({
    sessionId: 'named-session',
    sessionTitle: 'First name',
    sessionTitleSource: 'custom',
    sessionTitleAt: fs.readFileSync(replaced.file, 'utf8').indexOf(customTitleRecord('First name')),
  });
  assert.deepEqual(provider.refresh(parsed), { rail: 'First name', heading: 'First name' });

  replaced.replace();
  provider.readMetadata();
  assert.deepEqual(
    provider.drawn(),
    { rail: 'Second name', heading: 'Second name' },
    'the name parsed from the transcript that is gone outranked the one the new transcript gives',
  );
  assert.equal(
    provider.titles.get(replaced.file)?.label,
    'Second name',
    'the stored entry of the new transcript carries the old name into a restart',
  );
});

test('the rail row and the session heading keep one name while a running Claude turn is refreshed', () => {
  const provider = namedSessionProvider();
  provider.metadata({ label: 'retry', nameSource: 'prompt', nameAt: 0 });
  const titled = turn({
    sessionId: 'named-session',
    sessionTitle: 'Fix login flow',
    sessionTitleSource: 'generated',
    sessionTitleAt: 500,
  });
  const untitled = turn({ sessionId: 'named-session', sessionTitle: null });
  const drawn = [provider.refresh(titled)];
  provider.metadata({ label: 'retry', nameSource: 'prompt', nameAt: 0 });
  drawn.push(provider.refresh(untitled));
  assert.deepEqual(drawn, [
    { rail: 'Fix login flow', heading: 'Fix login flow' },
    { rail: 'Fix login flow', heading: 'Fix login flow' },
  ]);
  assert.equal(
    provider.titles.get('named-session.jsonl')?.label,
    'Fix login flow',
    'the derived cache keeps a lower name',
  );
});

test('the rail row and the session heading draw the later title when the metadata read lags a rename', () => {
  const provider = namedSessionProvider();
  const renamed = turn({
    sessionId: 'named-session',
    sessionTitle: 'New title',
    sessionTitleSource: 'generated',
    sessionTitleAt: 900,
  });
  const untitled = turn({ sessionId: 'named-session', sessionTitle: null });
  const drawn = [];
  provider.metadata({ label: 'Old title', nameSource: 'generated', nameAt: 100 });
  drawn.push(provider.refresh(renamed));
  provider.metadata({ label: 'Old title', nameSource: 'generated', nameAt: 100 });
  drawn.push(provider.refresh(untitled));
  drawn.push(provider.refresh(renamed));
  provider.metadata({ label: 'Old title', nameSource: 'generated', nameAt: 100 });
  drawn.push(provider.refresh(untitled));
  assert.deepEqual(drawn, Array(4).fill({ rail: 'New title', heading: 'New title' }));
});

test('a Claude session raised by its parsed turns before its metadata read draws the raised name after a restart', () => {
  const provider = namedSessionProvider();
  const titled = turn({
    sessionId: 'named-session',
    sessionTitle: 'Fix login flow',
    sessionTitleSource: 'generated',
    sessionTitleAt: 500,
  });
  assert.deepEqual(provider.refresh(titled), { rail: 'Fix login flow', heading: 'Fix login flow' });
  provider.metadata({ label: 'retry', nameSource: 'prompt', nameAt: 0 });
  assert.deepEqual(provider.drawn(), { rail: 'Fix login flow', heading: 'Fix login flow' });
  const derivedCache = JSON.parse(JSON.stringify([...provider.titles])) as [string, Record<string, unknown>][];
  const restarted = namedSessionProvider(derivedCache);
  assert.deepEqual(
    restarted.drawn(),
    { rail: 'Fix login flow', heading: 'Fix login flow' },
    'the first render after a restart draws the prompt, then flips when the parse arrives',
  );
});

// Turn 1 launches a background subagent, and turn 2's main agent finishes while it still runs.
// The tail read reaches only turn 2, so the host merges the parsed window. The rail then says
// 1 subagent, and the newest card counts the same carried subagent on a full draw and on a
// single-card activity refresh.
test('the host counts a carried subagent on the rail and the newest card alike', () => {
  const stampAt = (second: number) => new Date(Date.UTC(2026, 0, 1, 0, 0, second)).toISOString();
  const prompt = (text: string, second: number, id: string) => ({
    type: 'user',
    promptId: id,
    timestamp: stampAt(second),
    message: { role: 'user', content: [{ type: 'text', text }] },
  });
  const answer = (text: string, second: number, id: string) => ({
    type: 'assistant',
    timestamp: stampAt(second),
    message: {
      role: 'assistant',
      id,
      model: 'claude-opus-5',
      stop_reason: 'end_turn',
      content: [{ type: 'text', text }],
    },
  });
  const file = path.join(tempDir('carried-'), 'sess.jsonl');
  fs.writeFileSync(
    file,
    [
      prompt('scan in the background', 0, 'p1'),
      {
        type: 'assistant',
        timestamp: stampAt(1),
        message: {
          role: 'assistant',
          model: 'claude-opus-5',
          content: [
            { type: 'tool_use', id: 'bg1', name: 'Agent', input: { description: 'Scan x1', run_in_background: true } },
          ],
        },
      },
      {
        type: 'user',
        timestamp: stampAt(2),
        message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'bg1', content: 'launched' }] },
        toolUseResult: { isAsync: true, status: 'async_launched', agentId: 'x1', description: 'Scan x1' },
      },
      answer(`The scan is running. ${'x'.repeat(8_000)}`, 3, 'm1'),
      prompt('anything else?', 4, 'p2'),
      answer('Nothing else yet.', 5, 'm2'),
    ]
      .map((record) => JSON.stringify(record))
      .join('\n') + '\n',
  );
  const read = readSession(file, 'sess');
  const tail = readSessionMeta(file, 2_048, 'sess').outcome;
  assert.equal(tail?.openChildren, undefined, 'the tail read does not reach the launch');
  const now = Date.parse(stampAt(20));
  vi.useFakeTimers();
  vi.setSystemTime(now);
  try {
    const { provider, posted } = liveProviderFixture(livePress({ sessionId: 'sess' }));
    Object.assign(provider, {
      live: {},
      cache: new Map([[file, { read, revision: { mtimeMs: 10, size: 10 } }]]),
      titles: new Map([[file, { outcome: tail }]]),
      lifetimeRailFacts: () => ({}),
      claudeChildren: [{ parentSessionId: 'sess', sessionId: 'x1', mtimeMs: now - 60_000 }],
      claudeChildReferences: [],
      claudeChildStatWrites: new Map(),
    });
    const host = provider as unknown as {
      sessionOutcomes: unknown;
      cards: unknown[];
      newestBySession: Map<string, unknown>;
      outcomesFor(sessions: { sessionId: string; file: string; agent: string }[]): unknown;
      railStatuses(now: number): { statuses: Map<string, string>; openChildren: Map<string, number> };
      drawTurnCards(listed: unknown[], titleOf: () => string, now: number, folders: string[]): CardView[];
      postActivity(session: string): boolean;
    };
    host.sessionOutcomes = host.outcomesFor([{ sessionId: 'sess', file, agent: 'claude' }]);
    const rail = host.railStatuses(now);
    assert.deepEqual(
      { status: rail.statuses.get('sess'), count: rail.openChildren.get('sess') },
      { status: 'subagents', count: 1 },
    );
    const turns = [...read.turns].sort((a, b) => b.startedAt - a.startedAt);
    const figure = (card: CardView) => card.chips?.find((chip) => chip.metric === 'agents')?.running;
    const cards = host.drawTurnCards(turns, () => 'Session', now, []);
    assert.equal(figure(cards[0]), 1, 'the newest card counts the carried subagent');
    host.cards = cards;
    host.newestBySession = new Map([['sess', turns[0]]]);
    assert.equal(host.postActivity('sess'), true);
    assert.equal(figure((posted.at(-1) as { card: CardView }).card), 1, 'the activity refresh keeps the count');
  } finally {
    vi.useRealTimers();
  }
});

// A dispatched session can close its turn while its work goes on: a subagent it launched in the
// background still runs, or a command it started in the background does. The rail words each
// state, and the parent card's dispatched row reads running until the work ends, then done.
test.each(['subagents', 'background'] as const)(
  'the host draws a dispatched row as running while its session reads %s, then done',
  (status) => {
    const stampAt = (second: number) => new Date(Date.UTC(2026, 0, 1, 0, 0, second)).toISOString();
    const lines = (records: unknown[]) => records.map((record) => JSON.stringify(record)).join('\n') + '\n';
    const subagent = status === 'subagents';
    const answer = (text: string, second: number, id: string) => ({
      type: 'assistant',
      timestamp: stampAt(second),
      message: {
        role: 'assistant',
        id,
        model: 'claude-opus-5',
        stop_reason: 'end_turn',
        content: [{ type: 'text', text }],
      },
    });
    const file = path.join(tempDir(`dispatched-${status}-`), 'sess.jsonl');
    fs.writeFileSync(
      file,
      lines([
        {
          type: 'user',
          promptId: 'p1',
          timestamp: stampAt(0),
          message: { role: 'user', content: [{ type: 'text', text: 'run the suite' }] },
        },
        {
          type: 'assistant',
          timestamp: stampAt(1),
          message: {
            role: 'assistant',
            model: 'claude-opus-5',
            stop_reason: 'tool_use',
            content: [
              subagent
                ? {
                    type: 'tool_use',
                    id: 'bg1',
                    name: 'Agent',
                    input: { description: 'Scan x1', run_in_background: true },
                  }
                : {
                    type: 'tool_use',
                    id: 'cmd1',
                    name: 'Bash',
                    input: { command: 'npm test', run_in_background: true },
                  },
            ],
          },
        },
        subagent
          ? {
              type: 'user',
              timestamp: stampAt(2),
              message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'bg1', content: 'launched' }] },
              toolUseResult: { isAsync: true, status: 'async_launched', agentId: 'x1', description: 'Scan x1' },
            }
          : {
              type: 'user',
              timestamp: stampAt(2),
              message: {
                role: 'user',
                content: [
                  {
                    type: 'tool_result',
                    tool_use_id: 'cmd1',
                    content: 'Command running in background with ID: b349silf3',
                  },
                ],
              },
              toolUseResult: { stdout: '', stderr: '', interrupted: false, backgroundTaskId: 'b349silf3' },
            },
        answer('The work runs in the background.', 3, 'm1'),
      ]),
    );
    const now = Date.parse(stampAt(20));
    vi.useFakeTimers();
    vi.setSystemTime(now);
    try {
      const { provider } = liveProviderFixture(livePress({ sessionId: 'parent' }));
      Object.assign(provider, {
        lifetimeRailFacts: () => ({}),
        claudeChildren: subagent ? [{ parentSessionId: 'sess', sessionId: 'x1', mtimeMs: now - 10_000 }] : [],
        claudeChildStatWrites: new Map(),
        claudeChildReferences: [
          {
            kind: 'dispatch',
            agent: 'claude',
            parentSessionId: 'parent',
            sessionId: 'sess',
            toolUseIds: ['launch'],
            name: 'Run the suite',
            owned: false,
          },
        ],
        // The rail input's other figures are not under test.
        lifetimeFiguresBySession: () => ({ stats: {}, contextDetails: {}, costs: {}, dispatched: {} }),
        railRows: () => [],
        windows: new Map(),
        parsedRailCaches: {},
        metadataRailCaches: {},
        railSourceRevisions: {},
      });
      const host = provider as unknown as {
        titles: Map<string, unknown>;
        sessionOutcomes: unknown;
        outcomesFor(sessions: { sessionId: string; file: string; agent: string }[]): unknown;
        railStatuses(now: number): { statuses: Map<string, string>; openChildren: Map<string, number> };
        railInputFor(
          counts: Map<string, unknown>,
          statuses: Map<string, string>,
          openChildren: Map<string, number>,
          now: number,
        ): { backgroundCommands: Map<string, number> };
        drawTurnCards(listed: unknown[], titleOf: () => string, now: number, folders: string[]): CardView[];
      };
      const parent = turn({ sessionId: 'parent', files: [], commits: [], agents: [], dispatchToolUseIds: ['launch'] });
      const draw = (at: number) => {
        host.titles = new Map([[file, { outcome: readSessionMeta(file, 2_048, 'sess').outcome }]]);
        host.sessionOutcomes = host.outcomesFor([{ sessionId: 'sess', file, agent: 'claude' }]);
        const rail = host.railStatuses(at);
        const input = host.railInputFor(new Map(), rail.statuses, rail.openChildren, at);
        const [card] = host.drawTurnCards([parent], () => 'Parent', at, []);
        const figure = card.chips?.find((chip) => chip.metric === 'dispatched');
        return {
          rail: rail.statuses.get('sess'),
          subagents: rail.openChildren.get('sess'),
          commands: input.backgroundCommands.get('sess'),
          rows: card.dispatched?.map((row) => row.state),
          mark: figure?.running,
          heading: figure?.detailList?.heading?.value,
          busy: figure?.detailList?.heading?.busyValue,
        };
      };
      assert.deepEqual(draw(now), {
        rail: status,
        subagents: subagent ? 1 : undefined,
        commands: subagent ? undefined : 1,
        rows: ['running'],
        mark: 1,
        heading: '1 running',
        busy: true,
      });
      fs.appendFileSync(
        file,
        lines([
          {
            type: 'user',
            origin: { kind: 'task-notification' },
            timestamp: stampAt(30),
            message: {
              role: 'user',
              content: subagent
                ? '<task-notification><task-id>x1</task-id><status>completed</status></task-notification>'
                : '<task-notification><tool-use-id>cmd1</tool-use-id><status>completed</status></task-notification>',
            },
          },
          answer('The work finished.', 31, 'm2'),
        ]),
      );
      const later = Date.parse(stampAt(40));
      vi.setSystemTime(later);
      assert.deepEqual(draw(later), {
        rail: 'done',
        subagents: undefined,
        commands: undefined,
        rows: ['done'],
        mark: undefined,
        heading: undefined,
        busy: undefined,
      });
    } finally {
      vi.useRealTimers();
    }
  },
);

// A dispatched session's typed prompt lies before the metadata tail, and the command it
