// The subagent figure each side of the message boundary declares. `AgentFigureFacts` in
// `view/stat-detail.ts` is the one declaration of the fields a figure carries. `AgentFigure` in
// `turncard.ts` builds the figures from it, and `WireAgentFigure` in `webview/payload-contracts.ts`
// types what arrives. The declarations below hold the two to each other.
//
// They compare field names as well as field types. Mutual assignability on its own reads an
// optional field that one side alone declares as a match, and six of the figure's eight fields
// are optional, so the name comparison is the half that catches the next field anyone adds.
//
// A wider field type fails earlier, at each side's own `extends` clause, because both sides
// extend the shared declaration instead of intersecting with it.
//
// Three things these declarations do not reach. The record behind a figure is the field each side
// declares for itself, for the reason `view/stat-detail.ts` gives, so a field added inside a
// record arrives unchecked. The rest of a subagent row is mirrored by hand and is compared
// nowhere: `description`, `model`, `effort`, `state`, `stateWord`, `since`, `hintDetail` and
// `sessionId` each stand written twice, and `state` repeats a union word for word. And nothing
// here reads a message, because the host casts the card it posts, so this proves the two
// declarations agree and not that a payload matches either one.
//
// The compiler alone runs this check. `npm run typecheck` builds `extension/tsconfig.json`, which
// includes this file, and a mismatch fails there. It does not stop the test run:
// `extension/vitest.config.ts` sets no `typecheck` option, so vitest transpiles through esbuild
// and runs this file green with a type error present.
type HostFigure = AgentCard['figures'][number];
type WireFigure = NonNullable<CardView['agents']>[number]['figures'][number];

// What a mismatch reads as, so the compiler's own message says what broke.
type FigureMismatch = 'the panel contract and the card reducer describe different subagent figures';

// True where two shapes carry the same field names and each side's field types accept the
// other's, and the sentence above otherwise.
type Mirrors<A, B> = [keyof A] extends [keyof B]
  ? [keyof B] extends [keyof A]
    ? [A] extends [B]
      ? [B] extends [A]
        ? true
        : FigureMismatch
      : FigureMismatch
    : FigureMismatch
  : FigureMismatch;

// Resolves to what it is given, and fails to compile where that is the sentence above, which then
// reads in the compiler's message.
type Holds<T extends true> = T;

export type SubagentFigureMirror = Holds<Mirrors<Omit<HostFigure, 'record'>, Omit<WireFigure, 'record'>>>;

// Returning a commit row's subject or its maker's name to wrapping has to be a change to one
// rule each, so no second rule may set the four truncation properties on either.
test('one rule truncates a commit row subject, and one rule truncates its maker name', () => {
  const rules = [...styleSource.replace(/\/\*[\s\S]*?\*\//g, '').matchAll(/([^{}]+)\{([^{}]*)\}/g)];
  const setting = (selector: string) =>
    rules.filter(
      ([, selectors, body]) =>
        selectors.split(',').some((one) => one.trim() === selector) &&
        /(^|;)\s*(white-space|overflow|text-overflow|overflow-wrap)\s*:/.test(body),
    ).length;
  assert.equal(setting('.commitrow .name'), 1, 'a second rule sets how a commit subject truncates');
  assert.equal(setting('.commitrow .commitmakerlink'), 1, 'a second rule sets how a maker name truncates');
});

// Every popover shares one layer, so a hint whose control sits inside a popover drew under it
// whenever that popover came later in the body. The hint box now has a layer of its own. This
// holds what keeps it on top: the highest z-index in the stylesheet, no inline z-index in the
// panel's scripts, and no entry to the browser's top layer, which draws over any z-index.
test('the hint box draws over every popover', () => {
  const css = styleSource.replace(/\/\*[\s\S]*?\*\//g, '');
  const hint = /(?:^|\n)#hintpop \{([^}]*)\}/.exec(css);
  assert.ok(hint, 'panel.css has no #hintpop rule');
  // A declaration ends at a semicolon or at the brace that closes its rule.
  const own = /z-index:\s*([^;}]+?)\s*(?:;|$)/.exec(hint[1]);
  assert.ok(own, 'the #hintpop rule sets no z-index');
  const top = Number(own[1].trim());
  const others = [...css.replace(hint[0], '').matchAll(/z-index:\s*([^;}]+)[;}]/g)].map((match) => match[1].trim());
  for (const value of others) {
    assert.match(value, /^-?\d+$/, `panel.css sets a z-index of ${value}, which this check cannot rank`);
    assert.ok(Number(value) < top, `panel.css sets a z-index of ${value}, which reaches the hint box's ${top}`);
  }
  const forbidden: [RegExp, string][] = [
    [/zIndex|z-index/, 'an inline z-index'],
    [/(?:showModal|showPopover|togglePopover)\s*(?:\?\.)?\(/, 'a top-layer call'],
    [/\.popover\s*=(?!=)/, 'a popover assignment'],
    [/setAttribute\(\s*['"]popover['"]/, 'a popover attribute'],
    [/popover\s*:\s*['"](?:auto|manual|hint)['"]/, 'a popover prop'],
    [/popoverTarget|popovertarget/, 'a popover target'],
  ];
  for (const folder of ['webview', 'view']) {
    const files = fs
      .readdirSync(path.join(__dirname, folder), { recursive: true, encoding: 'utf8' })
      .filter((file) => file.endsWith('.ts') && !/\.test\.ts$/.test(file));
    assert.ok(files.length, `no scripts found under ${folder}`);
    for (const file of files) {
      const source = fs.readFileSync(path.join(__dirname, folder, file), 'utf8');
      for (const [pattern, what] of forbidden) {
        assert.doesNotMatch(source, pattern, `${folder}/${file} holds ${what}, which can draw over the hint box`);
      }
    }
  }
});

test('a small Claude worker tail carries recovered model evidence through host settings into the inherited setup', async () => {
  const directory = tempDir('host-attachment-recovery-');
  const file = path.join(directory, 'source.jsonl');
  const encode = (records: unknown[]) => records.map((record) => JSON.stringify(record)).join('\n') + '\n';
  fs.writeFileSync(
    file,
    encode([
      {
        type: 'attachment',
        attachment: { type: 'model', identity: { modelId: 'us-gov.anthropic.claude-opus-5-5[1m]' } },
      },
      ...Array.from({ length: 160 }, () => ({ type: 'ignored', text: 'x'.repeat(16384) })),
      { type: 'user', timestamp: new Date(1000).toISOString(), message: { role: 'user', content: 'Go' } },
      {
        type: 'assistant',
        effort: 'high',
        timestamp: new Date(2000).toISOString(),
        message: {
          role: 'assistant',
          id: 'answer',
          model: 'claude-opus-5-5',
          stop_reason: 'end_turn',
          content: [{ type: 'text', text: 'Done' }],
        },
      },
    ]),
  );
  const worker = new ProgressiveWorker(progressiveWorkerSource);
  const stat = fs.statSync(file);
  const input: ProgressiveInput = {
    session: { file, sessionId: 'source', agent: 'claude', size: stat.size, mtimeMs: stat.mtimeMs },
    folders: [],
    children: [],
    maxTurns: 40,
    tailBytes: 2048,
  };
  const signal = new AbortController().signal;
  try {
    let result = await worker.run({ kind: 'window', input }, 1, signal);
    assert.ok(result?.value.kind === 'window');
    assert.equal(result.value.readBytes, 2048);
    assert.equal(result.value.recoveryPending, true);
    const deadline = Date.now() + 10000;
    while (result.value.recoveryPending && Date.now() < deadline) {
      result = await worker.run({ kind: 'window', input, checkpoint: result.value.checkpoint }, 1, signal);
      assert.ok(result?.value.kind === 'window');
    }
    assert.equal(result.value.recoveryPending, false);
    let newest = await worker.run({ kind: 'window', input: { ...input, tailBytes: 128 } }, 2, signal);
    assert.ok(newest?.value.kind === 'window');
    const newestDeadline = Date.now() + 10000;
    while (newest.value.recoveryPending && Date.now() < newestDeadline) {
      newest = await worker.run(
        { kind: 'window', input: { ...input, tailBytes: 128 }, checkpoint: newest.value.checkpoint },
        2,
        signal,
      );
      assert.ok(newest?.value.kind === 'window');
    }
    assert.equal(newest.value.recoveryPending, false);
    assert.equal(newest.value.read.turns[0].modelAttachment, 'us-gov.anthropic.claude-opus-5-5[1m]');
    const runtime = composerRuntimeBySession(result.value.read.turns, new Map());
    const state = stateForRow([{ id: 'source', label: 'Source', agentKey: 'claude' }], {}, 'source', { runtime });
    const efforts = [{ value: 'high', label: 'High', description: '' }];
    const choice = (value: string, resolvedModel: string) => ({
      value,
      resolvedModel,
      label: value,
      description: '',
      efforts,
    });
    const catalog = [
      choice('default', 'claude-opus-5-5'),
      choice('opus', 'claude-opus-5-5'),
      choice('opus[1m]', 'claude-opus-5-5[1m]'),
    ];
    state.models = catalog;
    assert.equal(state.settings.confirmedModelAttachment, 'us-gov.anthropic.claude-opus-5-5[1m]');
    assert.equal(
      launcherProfile(sessionLauncherView(state, [], { claude: catalog }), { kind: 'row', key: 'current' })?.model,
      'opus[1m]',
    );
  } finally {
    worker.stop();
    fs.rmSync(directory, { recursive: true, force: true });
  }
});

