test('pending current-profile launch ignores a changed host and does not delay explicit choices', async () => {
  const moved = pendingModelLauncher();
  moved.provider.newSession(undefined, moved.owner);
  moved.provider.hostSessions.set(moved.owner, 'other');
  moved.release(moved.result);
  await moved.completed();
  assert.deepEqual(moved.created, []);
  for (const choice of ['picked', 'custom', 'recent', 'pinned']) {
    const f = pendingModelLauncher();
    const { state } = f.provider.launcherFor();
    const profile: SessionProfile = {
      agent: 'claude',
      model: 'opus',
      effort: 'high',
      permissionMode: 'auto',
      source: 'recent',
    };
    if (choice === 'picked') state.settings.selectedModel = 'opus';
    const view = sessionLauncherView(
      state,
      [profile],
      { claude: state.models },
      choice === 'pinned' ? [{ id: 'pin', ...normalizeSetupValues(profile)! }] : [],
    );
    f.provider.launcherFor = () => ({ owner: f.owner, state, view });
    const request =
      choice === 'picked'
        ? undefined
        : choice === 'custom'
          ? { kind: 'custom', ...profile }
          : { kind: 'row', key: choice === 'recent' ? view.recent[0].key : view.pinned[0].key };
    assert.equal(f.provider.newSession(request, f.owner), true);
    assert.equal(f.created.length, 1);
    assert.equal(f.provider.attachmentHandoffs.size, 0);
  }
});

