test.each(['storage', 'acceptance'])(
  'submitted recovery freezes comment membership across queue note edit at %s',
  async (window) => {
    const comment: TurnComment = {
      id: 'C',
      sessionId: 'source',
      turnKey: 'source:1',
      part: 'summary',
      quote: '',
      note: 'old captured comment',
      headline: 'Turn',
      sessionTitle: 'Source',
      turnAt: 1,
      at: 2,
    };
    const { provider } = queueRecoveryProvider([comment]);
    const host = { webview: {} };
    Object.assign(provider, { hosts: [host], hostSessions: new Map([[host, 'source']]), readyHosts: new Set([host]) });
    let release!: () => void;
    const waiting = new Promise<void>((resolve) => {
      release = resolve;
    });
    let stored: any;
    let writes = 0;
    provider.memento = {
      get: () => structuredClone(stored),
      update: async (_key: string, value: unknown) => {
        if (++writes === 1) await waiting;
        stored = structuredClone(value);
      },
    };
    let accept!: (answer: PromptDelivery) => void;
    const sent: string[] = [];
    provider.onSendPrompt = (_agent: string, _session: string, _cwd: string, prompt: { text: string }) => {
      sent.push(prompt.text);
      return new Promise<PromptDelivery>((resolve) => {
        accept = resolve;
      });
    };
    const text = 'frozen prompt';
    await provider.onMessage({ type: 'draft', session: 'source', text, keep: text, revision: 1 }, host);
    const pending = provider.onMessage(
      {
        type: 'sendPrompt',
        session: 'source',
        text,
        revision: 2,
        attempt: { id: window, order: 1, source: 'source', revision: 2, text },
      },
      host,
    );
    await vi.waitFor(() => assert.equal(writes, 1));
    const edited = { ...comment, offset: undefined, note: 'new reader comment' };
    if (window === 'storage') await provider.onMessage({ type: 'note', note: { op: 'write', note: edited } }, host);
    release();
    await pending;
    await vi.waitFor(() => assert.equal(sent.length, 1));
    if (window === 'acceptance') await provider.onMessage({ type: 'note', note: { op: 'write', note: edited } }, host);
    assert.equal(provider.saved.comments[0].note, edited.note);
    assert.match(sent[0], /old captured comment/);
    assert.doesNotMatch(sent[0], /new reader comment/);
    accept({ delivered: true, reason: '', session: 'source' });
    await vi.waitFor(() => assert.equal(provider.saved.submittedPrompts[0].accepted, true));
    assert.deepEqual(provider.saved.comments, [edited]);
    await provider.writeDrafts();
    assert.deepEqual(stored.comments, [edited]);
    const listener = vi
      .spyOn(PanelProvider.prototype as unknown as { wireEditorListeners(): void }, 'wireEditorListeners')
      .mockImplementation(() => {});
    let fresh: InstanceType<typeof PanelProvider> | undefined;
    try {
      fresh = new PanelProvider('', {} as vscode.Uri, provider.memento);
      assert.deepEqual((fresh as unknown as Record<string, any>).saved.comments, [edited]);
    } finally {
      fresh?.dispose();
      listener.mockRestore();
    }
  },
);

test.each(['typing', 'emptied', 'untouched', 'success'])(
  'submitted recovery retains host drafts across rename %s and provider reconstruction',
  async (change) => {
    const { provider } = queueRecoveryProvider();
    const host = { webview: {} };
    Object.assign(provider, { hosts: [host], hostSessions: new Map([[host, 'source']]), readyHosts: new Set([host]) });
    let release!: () => void;
    const waiting = new Promise<void>((resolve) => {
      release = resolve;
    });
    let stored: any;
    let writes = 0;
    provider.memento = {
      get: () => structuredClone(stored),
      update: async (_key: string, value: unknown) => {
        if (++writes === 1) await waiting;
        stored = structuredClone(value);
      },
    };
    let finish!: () => void;
    let renamed = false;
    provider.renameSession = () => {
      renamed = true;
      return new Promise((resolve) => {
        finish = () => resolve({ title: 'Name', error: change === 'success' ? '' : 'refused' });
      });
    };
    let settled = false;
    const originalError = vscode.window.showErrorMessage;
    (vscode.window as any).showErrorMessage = () => {
      settled = true;
      return Promise.resolve();
    };
    const text = '/rename Name';
    try {
      await provider.onMessage({ type: 'draft', session: 'source', text, keep: text, revision: 1 }, host);
      const pending = provider.onMessage(
        {
          type: 'sendPrompt',
          session: 'source',
          text,
          revision: 2,
          attempt: { id: change, order: 1, source: 'source', revision: 2, text },
        },
        host,
      );
      await vi.waitFor(() => assert.equal(writes, 1));
      if (change !== 'untouched')
        await provider.onMessage(
          { type: 'draft', session: 'source', text: 'reader B', keep: 'reader B', revision: 3 },
          host,
        );
      if (change === 'emptied')
        await provider.onMessage({ type: 'draft', session: 'source', text: '', keep: '', revision: 4 }, host);
      release();
      await pending;
      await vi.waitFor(() => assert.equal(renamed, true));
      finish();
      if (change !== 'success') await vi.waitFor(() => assert.equal(settled, true));
      const expected = change === 'untouched' ? text : change === 'emptied' ? '' : 'reader B';
      await provider.writeDrafts();
      assert.equal(stored.drafts.source ?? '', expected);
      assert.equal(provider.stateFor('source').onScreen, expected);
      assert.equal(provider.saved.submittedPrompts[0].text, text);
      const listener = vi
        .spyOn(PanelProvider.prototype as unknown as { wireEditorListeners(): void }, 'wireEditorListeners')
        .mockImplementation(() => {});
      let fresh: InstanceType<typeof PanelProvider> | undefined;
      try {
        fresh = new PanelProvider('', {} as vscode.Uri, provider.memento);
        assert.equal((fresh as unknown as Record<string, any>).drafts.source ?? '', expected);
      } finally {
        fresh?.dispose();
        listener.mockRestore();
      }
    } finally {
      (vscode.window as any).showErrorMessage = originalError;
    }
  },
);

test('submitted recovery waits behind compaction started during storage', async () => {
  const { provider } = queueRecoveryProvider();
  const host = { webview: {} };
  Object.assign(provider, { hosts: [host], hostSessions: new Map([[host, 'source']]), readyHosts: new Set([host]) });
  let release!: () => void;
  const waiting = new Promise<void>((resolve) => {
    release = resolve;
  });
  let writes = 0;
  provider.memento.update = async () => {
    if (++writes === 1) await waiting;
  };
  let finishCompact!: (answer: PromptDelivery) => void;
  provider.onCompact = () => {
    provider.setRunning(['codex:source']);
    return new Promise<PromptDelivery>((resolve) => {
      finishCompact = resolve;
    });
  };
  const sent: Array<{ text: string }> = [];
  provider.onSendPrompt = async (_agent: string, _session: string, _cwd: string, prompt: { text: string }) => {
    sent.push(prompt);
    return { delivered: true, reason: '', session: 'source' };
  };
  const text = '  frozen A\n  ';
  const settings = { ...provider.stateFor('source').settings };
  assert.deepEqual(provider.stateFor('source').live, []);
  await provider.onMessage({ type: 'draft', session: 'source', text, keep: text, revision: 1 }, host);
  const attempt = { id: 'compact-window', order: 1, source: 'source', revision: 2, text };
  const pending = provider.onMessage({ type: 'sendPrompt', session: 'source', text, revision: 2, attempt }, host);
  await vi.waitFor(() => assert.equal(writes, 1));
  await provider.onMessage({ type: 'compact', session: 'source' }, host);
  await vi.waitFor(() => {
    assert.equal(provider.stateFor('source').running, true);
    assert.equal(provider.stateFor('source').live[0].kind, 'compact');
    assert.equal(typeof finishCompact, 'function');
  });
  await provider.onMessage({ type: 'draft', session: 'source', text: 'newer B', keep: 'newer B', revision: 3 }, host);
  release();
  await pending;
  assert.equal(sent.length, 0, 'prompt delivery began before compaction ended');
  assert.equal(provider.queues.source.length, 1);
  assert.equal(provider.queues.source[0].text, text.trim());
  assert.equal(provider.queues.source[0].recoveryId, attempt.id);
  assert.deepEqual(provider.stateFor('source').settings, settings);
  assert.equal(provider.drafts.source, 'newer B');
  finishCompact({ delivered: true, reason: '', session: 'source' });
  await vi.waitFor(() => assert.equal(provider.live.source[0].ran, true));
  provider.setRunning([]);
  provider.flushQueue('source');
  await vi.waitFor(() => assert.equal(sent.length, 1));
  await vi.waitFor(() => assert.equal(provider.queues.source, undefined));
  assert.equal(sent[0].text, 'frozen A');
  assert.equal(provider.drafts.source, 'newer B');
  assert.deepEqual(provider.saved.submittedPrompts[0].text, text);
});

test.each([
  'queued edit',
  'newer draft swap',
  'live recovery',
  'live recovery above pending',
  'live recovery without submission',
  'failed rename',
])('submitted recovery retains host drafts across %s and provider reconstruction', async (change) => {
  const comments = ['submitted', 'later', 'queued'].map((id) => ({
    id,
    sessionId: id === 'later' ? 'other' : 'source',
    turnKey: 'source:1',
    part: 'summary' as const,
    quote: '',
    note: id,
    headline: 'Turn',
    sessionTitle: 'Source',
    turnAt: 1,
    at: 2,
  }));
  const { provider } = queueRecoveryProvider(comments);
  delete provider.stateFor;
  delete provider.dropCarriedAssets;
  const host = { webview: {} };
  Object.assign(provider, {
    hosts: [host],
    hostSessions: new Map([[host, 'source']]),
    sessionRows: [{ id: 'source', label: 'Source', agentKey: 'codex' }],
    readyHosts: new Set([host]),
    running: new Set(),
    models: {},
    commandLists: {},
    skillLists: {},
    mcpServers: {},
    askLevels: {},
    sendToHost: () => Promise.resolve(true),
  });
  const assets = ['1', '2', '3'].map((n) => ({
    id: `${n}2345678-1234-4123-8123-123456789abc`,
    name: `${n}.txt`,
    mime: 'text/plain',
    size: 4,
    digest: '9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08',
  }));
  await provider.onMessage(
    { type: 'draft', session: 'source', text: 'submitted A', keep: 'submitted A', revision: 1 },
    host,
  );
  provider.draftCommentIds.source = ['submitted'];
  provider.assets.source = [assets[0]];
  provider.queues.source = queueSubmissionAfter(
    [],
    'Q',
    'queued Q outside recovery',
    ['queued'],
    [assets[2]],
    1,
    false,
    { agent: 'codex', owner: 'source' },
  );
  provider.saved.submittedPrompts = Array.from({ length: 5 }, (_, index) => ({
    id: `retained-${index}`,
    order: index + 1,
    source: 'missing',
    revision: 1,
    text: `retained ${index}`,
  }));
  let release!: () => void;
  const waiting = new Promise<void>((resolve) => {
    release = resolve;
  });
  let stored: any;
  let writes = 0;
  provider.memento = {
    get: () => structuredClone(stored),
    update: async (_key: string, value: unknown) => {
      if (++writes === 1) await waiting;
      stored = structuredClone(value);
    },
  };
  const sent: string[] = [];
  provider.onSendPrompt = async (_agent: string, _session: string, _cwd: string, prompt: { text: string }) => {
    sent.push(prompt.text);
    return { delivered: true, session: 'source' };
  };
  let pending: Promise<void>;
  let refuseRename!: () => void;
  let renameStarted = false;
  if (change === 'failed rename') {
    provider.renameSession = () => {
      renameStarted = true;
      return new Promise((resolve) => {
        refuseRename = () => resolve({ title: 'New name', error: 'rename refused' });
      });
    };
    const text = '/rename New name';
    pending = provider.onMessage(
      {
        type: 'sendPrompt',
        session: 'source',
        text,
        revision: 2,
        attempt: { id: 'rename', order: 6, source: 'source', revision: 2, text },
      },
      host,
    );
    await vi.waitFor(() => assert.equal(writes, 1));
  } else if (change === 'live recovery without submission') {
    pending = Promise.resolve();
  } else {
    const attempt = { id: 'A', order: 6, source: 'source', revision: 2, text: 'submitted A' };
    pending = provider.acceptSubmission(attempt.text, 'source', 2, 'source', host, attempt);
    await vi.waitFor(() => assert.equal(writes, 1));
  }
  let expected = 'queued Q outside recovery';
  if (change.startsWith('live recovery')) {
    expected = 'failed live prompt';
    if (change === 'live recovery above pending') {
      await provider.onMessage(
        { type: 'draft', session: 'source', text: 'reader B', keep: 'reader B', revision: 3 },
        host,
      );
    }
    const priorRevision = provider.draftRevisions.get('source');
    provider.live.source = [
      livePress({ sessionId: 'source', agent: 'codex', kind: 'prompt', text: expected, failed: true }),
    ];
    provider.restoreLive('source', 'prompt');
    assert.equal(provider.live.source, undefined);
    assert.equal(provider.drafts.source, expected);
    assert.equal(provider.stateFor('source').onScreen, expected);
    assert.equal(provider.draftRevisions.get('source') > priorRevision, true);
  } else {
    const revision = change === 'newer draft swap' ? 3 : 2;
    if (change === 'newer draft swap') {
      await provider.onMessage(
        { type: 'draft', session: 'source', text: 'reader B', keep: 'reader B', revision },
        host,
      );
      provider.draftCommentIds.source = ['submitted', 'later'];
      provider.assets.source = [assets[0], assets[1]];
    }
    provider.requestQueuedEdit('Q', 'source', revision, host);
    assert.equal(provider.queuedEditReservations.has('Q'), true);
    provider.acceptQueuedEdit('Q', 'source', revision, revision + 1, true, host);
    assert.equal(provider.queues.source?.some((entry: any) => entry.text === 'submitted A') ?? false, false);
    if (change === 'newer draft swap') {
      assert.equal(provider.queues.source[0].text, 'reader B');
      assert.deepEqual(provider.queues.source[0].commentIds, ['later']);
      assert.deepEqual(provider.queues.source[0].assets, [assets[1]]);
    }
  }
  release();
  const originalError = vscode.window.showErrorMessage;
  if (change === 'failed rename') (vscode.window as any).showErrorMessage = () => Promise.resolve();
  try {
    await pending;
    if (change === 'failed rename') {
      await vi.waitFor(() => assert.equal(renameStarted, true));
      refuseRename();
      await vi.waitFor(() => assert.equal(provider.typedRenames.has('source'), false));
      await provider.writeDrafts();
      assert.equal(stored.drafts.source, expected, 'failed rename replaced newer persisted draft');
    }
  } finally {
    (vscode.window as any).showErrorMessage = originalError;
  }
  await vi.waitFor(() => {
    const queued = (provider.queues.source ?? []).filter((entry: any) => entry.text === 'submitted A').length;
    if (change !== 'failed rename' && change !== 'live recovery without submission')
      assert.equal(queued + sent.filter((text) => text.startsWith('submitted A')).length, 1);
    if (change === 'live recovery without submission') assert.deepEqual(sent, []);
    assert.equal(provider.drafts.source, expected);
    assert.equal(provider.stateFor('source').onScreen, expected);
  });
  await provider.writeDrafts();
  assert.equal(stored.drafts.source, expected);
  assert.equal(
    provider.saved.submittedPrompts.some((entry: any) => entry.text === 'queued Q outside recovery'),
    false,
  );
  assert.equal(
    provider.saved.submittedPrompts.some((entry: any) => entry.text === 'failed live prompt'),
    false,
  );
  const listener = vi
    .spyOn(PanelProvider.prototype as unknown as { wireEditorListeners(): void }, 'wireEditorListeners')
    .mockImplementation(() => {});
  let fresh: InstanceType<typeof PanelProvider> | undefined;
  try {
    fresh = new PanelProvider('', {} as vscode.Uri, provider.memento);
    const reconstructed = fresh as unknown as Record<string, any>;
    reconstructed.sessionRows = [{ id: 'source', label: 'Source', agentKey: 'codex' }];
    reconstructed.repositoryScopeReady = true;
    assert.equal(reconstructed.drafts.source, expected);
    assert.equal(reconstructed.stateFor('source').onScreen, expected);
    if (!change.startsWith('live recovery')) {
      assert.deepEqual(reconstructed.draftCommentIds.source, ['queued']);
      assert.deepEqual(reconstructed.assets.source, [assets[2]]);
    }
  } finally {
    fresh?.dispose();
    listener.mockRestore();
  }
});

